INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C1','kor',3,2,'u2',2,'유창하게 읽는다는 것 — 소리 내어 읽을 때 듣는 사람에게 뜻이 잘 전해지게 읽는 것이고, 남보다 빨리 읽거나 가장 큰 소리로 읽는 것이 아님',ARRAY['[4국02-01]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C2','kor',3,2,'u2',2,'띄어 읽기 표시와 띄어 읽는 자리 — ∨는 조금 쉬어 읽고 ≡는 조금 더 길게 쉬어 읽는 표시, ‘누가/무엇이’ 다음에 조금 띄어 읽고 그 말이 길면 한 번 더, 문장과 문장 사이는 조금 더 길게 쉬며, 뜻이 달라지지 않으면 쉬는 곳은 사람마다 조금씩 달라도 됨(아무 데서나는 아님)',ARRAY['[4국02-01]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C3','kor',3,2,'u2',2,'글자 대신 쓰는 그림 기호 — 복도 바닥 화살표·책꽂이 옆 책 그림·급식실 발자국처럼 긴 글 없이 무엇을 하라는 말인지 멀리서도 바쁠 때도 한눈에 알아보게 하려고 그림이나 색을 씀',ARRAY['[4국02-01]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C4','kor',3,2,'u2',2,'글 내용 확인과 스스로 점검하기 — 소리 내어 읽은 글에서 알 수 있는 것은 글에 쓰여 있는 것만이고, 녹음을 다시 들을 때는 몇 초 걸렸는지가 아니라 듣는 사람에게 뜻이 전해지게 읽었는지를 살피며, 점검은 잘못을 찾아 점수 매기는 일이 아니라 다음에 더 잘 읽으려고 하는 일',ARRAY['[4국02-01]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C5','kor',3,2,'u2',3,'장면의 분위기와 그 까닭 — 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 모으면 장면의 분위기가 드러나고, 분위기나 마음을 말할 때는 글 안에서 그렇게 느낀 까닭을 함께 말함(먼저 말한 사람·많이 고른 답을 따르지 않음)',ARRAY['[4국02-01]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C6','kor',3,2,'u2',3,'분위기를 살려 읽는 방법 — 상황을 떠올리며 실감 나게, 말이나 행동에 어울리는 표정과 몸짓으로, 마음이 드러나는 목소리로 읽고(쓸쓸한 장면은 낮고 느리게, 그러나 뜻은 또렷이), 꾸며 주는 말·문장 부호도 느낌을 살려 읽으며, 장면에 어울리면 읽는 방법은 사람마다 달라도 됨',ARRAY['[4국02-01]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C7','kor',3,2,'u2',5,'장면을 떠올리며 뜻 덩어리로 읽기 — 「노란 조끼」에서 인물이 하는 일과 까닭을 글에서 찾고, 장면의 상황·말·마음을 정리해 장면이 떠오르게 뜻 덩어리로 묶어 읽기(아주 빠르게도, 한 낱말씩 다 끊어서도 아님)',ARRAY['[4국02-01]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C8','kor',3,2,'u2',5,'뜻이 비슷한 낱말 — 글에 나온 낱말(다독이다·서두르다·살피다)을 그 낱말이 들어간 줄에서 뜻을 찾아 비슷한 말(달래다·급히 하다·둘러보다)로 바꾸어 넣어 보면 뜻이 더 또렷해짐',ARRAY['[4국02-01]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C9','kor',3,2,'u2',5,'글을 읽고 생각 나누기와 배울 점 — 글을 읽고 든 생각이나 느낌은 마음이 움직인 곳이 서로 달라도 되고, 배울 점은 유명한 사람에게만 있는 것이 아니라 둘레의 사람에게도 있음',ARRAY['[4국02-01][4국05-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C10','kor',3,2,'u2',7,'글과 그림이 하는 일 — 글은 자세한 내용을 알려 주고 그림은 글로 알기 어려운 것을 한눈에 보여 주며, 둘을 이어 읽으면 더 잘 이해됨(그림은 꾸미려고 넣는 것이 아니고, 한쪽만 있으면 되는 것도 아님)',ARRAY['[4국01-05][4국06-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C11','kor',3,2,'u2',7,'색·크기·모양으로 나타내기 — 색은 서로 다른 것을 구별해 보여 주고, 크기는 중요한 것을 눈에 띄게 하며, 모양(화살표 등)은 어디에 있는지·어느 쪽인지 알려 줌; 같은 내용도 나타내는 방법은 여러 가지',ARRAY['[4국01-05][4국06-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C12','kor',3,2,'u2',8,'목적에 맞는 발표 주제와 내용 — 자료의 도막마다 중요한 내용을 고르고, 누구에게 왜 알려 줄지부터 정하면 넣을 내용도 정해지며, 목적과 상관없는 재미있는 것·덜 중요한 것은 넣지 않음',ARRAY['[4국01-05][4국06-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C13','kor',3,2,'u2',8,'발표 자료의 얼개와 꾸밈 — 제목·그림·설명을 어디에 놓을지 얼개를 먼저 짜고(맨 위 크게 쓴 제목 · 가운데 보여 주려는 그림 · 그림 아래 짧은 설명), 색과 크기는 전하려는 것이 눈에 띄게 쓰며 많이 쓸수록 좋은 것이 아님',ARRAY['[4국01-05][4국06-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C14','kor',3,2,'u2',8,'서로 다른 자료 보기와 의견 말하기 — 같은 내용이라도 표현과 배치가 다를 수 있어 전하려는 것이 잘 보이면 둘 다 알맞고(글이 많은 쪽·그림이 큰 쪽이 나은 것이 아님), 친구 자료에 의견을 말할 때는 잘한 곳과 더 잘 보이게 할 방법을 함께 말함',ARRAY['[4국01-05][4국06-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C15','kor',3,2,'u2',11,'배운 내용 실천하기 — 이야기를 소개할 그림은 흐름에서 중요한 장면이 드러난 것으로 고르고, 나타내려는 것마다 글로 쓸지 그림으로 보일지 갈라 두며, 친구 발표는 끝까지 듣고 좋았던 곳을 말해 줌',ARRAY['[4국01-05][4국06-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C16','kor',3,2,'u2',11,'‘것·수·줄’ 띄어쓰기 — ‘것·수·줄’은 혼자 쓰이지 못하고 다른 말에 기대어 쓰이는 말이라 앞말과 띄어 쓰고(먹을 것 · 갈 수 있다 · 탈 줄 안다), 줄넘기·수요일처럼 한 낱말 속에 들어 있을 때는 붙여 씀(기초 다지기)',ARRAY['[4국04-02](케이티처 표기)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C17','kor',3,2,'u2',11,'특징이 드러나는 이름 짓기 — 물건의 생김새나 하는 일을 살펴 새 이름을 지으면, 이름에 특징이 드러나 처음 듣는 사람도 무엇인지 알 수 있음(기초 다지기)',ARRAY['[4국04-02](케이티처 표기)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X01','kor',3,'u2',ARRAY['K3-2-u2-C1','K3-2-u2-C4','K3-2-u2-C6','K3-2-u2-C15']::text[],'남보다 빨리 읽거나 몇 초 만에 다 읽는 것을 잘 읽은 것으로 여긴다','읽고 난 뒤 듣는 사람에게 무엇이 남았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X02','kor',3,'u2',ARRAY['K3-2-u2-C1','K3-2-u2-C6','K3-2-u2-C15']::text[],'처음부터 끝까지 가장 큰 소리로 읽는 것을 잘 읽은 것으로 여긴다','크기보다 뜻이 전해지는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X03','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'쉬어 읽는 곳은 언제나 한 곳뿐이라 친구와 다르면 하나는 틀렸다고 여긴다','뜻이 달라지지 않으면 조금씩 달라도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X04','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'아무 데서나 쉬어도 된다고 여겨 ‘누가/무엇이’ 덩어리 한가운데서 끊어 읽는다','‘무엇이’에 해당하는 말이 끝나는 곳은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X05','kor',3,'u2',ARRAY['K3-2-u2-C2','K3-2-u2-C7']::text[],'띄어 읽기를 잘하려고 한 낱말씩 모두 끊어 읽어 뜻이 흩어진다','뜻 덩어리로 묶어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X06','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'∨(조금 쉬기)와 ≡(조금 더 길게 쉬기)를 바꾸어 알거나, 문장과 문장 사이를 짧게 쉰다','≡ 는 문장 끝 — 더 길게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X07','kor',3,'u2',ARRAY['K3-2-u2-C3']::text[],'글자 대신 그림 기호를 쓰는 까닭을 꾸미거나 글씨 쓰기가 귀찮아서라고 여긴다','멀리서도, 바쁠 때도 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X08','kor',3,'u2',ARRAY['K3-2-u2-C4','K3-2-u2-C7']::text[],'글에 쓰여 있지 않은 것(짐작한 것·값·이름)을 글에서 알 수 있다고 여긴다','그 내용이 적힌 줄을 찾을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X09','kor',3,'u2',ARRAY['K3-2-u2-C4']::text[],'스스로 점검하기를 잘못을 찾아 점수를 매기거나 남과 견주는 일로 여긴다','점검은 다음에 더 잘 읽으려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X10','kor',3,'u2',ARRAY['K3-2-u2-C5']::text[],'분위기나 마음을 말할 때 까닭 없이 말하거나, 먼저 말한 사람·많이 고른 답을 따른다','그렇게 느낀 까닭을 글에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X11','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C7']::text[],'인물의 마음을 짐작할 근거로 인물의 말·행동이 아니라 날씨·때처럼 마음과 상관없는 곳을 고른다','인물이 한 말이나 행동은 어디?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X12','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C6']::text[],'장면과 분위기를 엇갈리게 잇거나, 쓸쓸한 장면을 웃는 목소리로 읽는다','그 장면에서 인물은 무엇을 하고 있었나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X13','kor',3,'u2',ARRAY['K3-2-u2-C6']::text[],'실감 나게 읽기를 아주 크고 빠르게, 또는 들리지 않을 만큼 작게 읽는 것으로 여긴다','낮고 느리게, 그러나 뜻은 또렷이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X14','kor',3,'u2',ARRAY['K3-2-u2-C6']::text[],'분위기를 살려 읽는 방법은 하나뿐이라 서로 다르게 읽으면 하나는 틀렸다고 여긴다','장면에 어울리면 방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X15','kor',3,'u2',ARRAY['K3-2-u2-C4','K3-2-u2-C5','K3-2-u2-C7']::text[],'글에서 인물이 겪은 일·하는 일이나 그 까닭을 잘못 읽는다','그 일이 적힌 줄을 다시 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X16','kor',3,'u2',ARRAY['K3-2-u2-C8']::text[],'뜻이 비슷한 낱말을 앞뒤 줄을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 줄에 바꾸어 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X17','kor',3,'u2',ARRAY['K3-2-u2-C9']::text[],'배울 점은 유명하거나 나이가 많은 사람에게만 있다고 여기거나, 글을 읽고 든 느낌에 정답이 있다고 여긴다','둘레의 사람에게도 · 느낌은 달라도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X18','kor',3,'u2',ARRAY['K3-2-u2-C10']::text[],'설명하는 글에 그림을 넣는 까닭을 보기 좋게 꾸미거나 글을 적게 쓰려고라고 여긴다','그림이 없으면 무엇이 어려울까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X19','kor',3,'u2',ARRAY['K3-2-u2-C10','K3-2-u2-C15']::text[],'글과 그림 가운데 한쪽만 있으면 된다고 여기거나, 그림으로 보일 것과 글로 쓸 것을 엇갈리게 고른다','글이 할 일과 그림이 할 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X20','kor',3,'u2',ARRAY['K3-2-u2-C11']::text[],'색·크기·모양이 하는 일(구별하기·눈에 띄게 하기·쪽 알려 주기)을 엇갈리게 안다','그 표현이 없으면 무엇을 알기 어려울까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X21','kor',3,'u2',ARRAY['K3-2-u2-C12','K3-2-u2-C15']::text[],'누구에게 왜 알려 줄지와 상관없이 재미있는 것·덜 중요한 것을 중요한 내용으로 고른다','누구에게, 왜 알려 주나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X22','kor',3,'u2',ARRAY['K3-2-u2-C13']::text[],'얼개에서 제목·그림·설명의 자리를 엇갈리게 놓거나 얼개 없이 바로 만든다','가장 먼저 눈에 들어와야 할 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X23','kor',3,'u2',ARRAY['K3-2-u2-C13']::text[],'색과 크기는 많이 쓸수록, 알록달록하고 모두 크게 쓸수록 좋다고 여긴다','모두 크면 무엇이 중요한지 보일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X24','kor',3,'u2',ARRAY['K3-2-u2-C11','K3-2-u2-C14']::text[],'같은 내용을 다르게 나타낸 자료 가운데 글이 많은 쪽이나 그림이 큰 쪽이 더 잘 만든 것이라고 여긴다','전하려는 것이 잘 보이면 둘 다 알맞아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X25','kor',3,'u2',ARRAY['K3-2-u2-C14']::text[],'친구 자료에 의견을 말할 때 잘못한 곳만 찾아 말하거나 무조건 잘했다고만 말한다','잘한 곳 + 더 잘 보이게 할 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X26','kor',3,'u2',ARRAY['K3-2-u2-C15']::text[],'친구가 발표할 때 내 차례만 준비하거나 내용과 상관없이 박수만 친다','끝까지 듣고 좋았던 곳 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X27','kor',3,'u2',ARRAY['K3-2-u2-C16']::text[],'‘것·수·줄’을 앞말에 붙여 쓰거나 뒷말에 붙여 쓴다','‘것·수·줄’ 앞뒤를 모두 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X28','kor',3,'u2',ARRAY['K3-2-u2-C16']::text[],'줄넘기·수요일처럼 한 낱말 속에 든 ‘줄·수’도 띄어 써야 한다고 여긴다','혼자 떨어져 다른 말에 기댈 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X29','kor',3,'u2',ARRAY['K3-2-u2-C17']::text[],'새 이름에 물건의 특징이 드러나지 않거나, 특징과 이름을 엇갈리게 잇는다','그 물건이 무엇을 하는지 이름에 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X30','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C6']::text[],'한 이야기의 분위기는 처음부터 끝까지 하나뿐이라고 여겨, 장면마다 인물의 상황과 마음이 바뀌면 분위기도 바뀌는 것을 놓친다','장면을 나누어 그 장면의 상황·마음부터 다시 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X31','kor',3,'u2',ARRAY['K3-2-u2-C11']::text[],'색이 주는 느낌을 생각하지 않거나 거꾸로 안다 — 빨강·노랑을 차가운 느낌, 파랑·청록을 따뜻한 느낌으로 여긴다','불과 햇볕은 무슨 색? 물과 얼음은 무슨 색?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X32','kor',3,'u2',ARRAY['K3-2-u2-C1','K3-2-u2-C6']::text[],'문장 끝 말투(-요·-ㅂ니다)나 문장 부호(?·!)와 상관없이 모든 문장을 같은 말투로 읽는다','문장이 어떻게 끝나는지, 어떤 부호가 붙었는지 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X33','kor',3,'u2',ARRAY['K3-2-u2-C4','K3-2-u2-C7']::text[],'묻고 답하기 놀이에서 글의 중요한 내용·장면과 상관없거나 글에 없는 것을 질문으로 만든다','그 질문의 답이 글에 있나? 중요한 장면인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X34','kor',3,'u2',ARRAY['K3-2-u2-C5']::text[],'같은 상황을 겪으면 누구나 같은 말과 행동을 하고 같은 마음이 든다고 여긴다(인물의 성격에 따라 다를 수 있음을 모름)','두 인물이 같은 일 앞에서 한 말을 나란히 놓고 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X36','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C7']::text[],'장면을 정리할 때 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 서로 가리지 못하고 엇갈린 칸에 넣는다','일어난 일? 따옴표 속 말과 움직임? 속으로 느낀 것?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#1','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C3',1,'mc','auto','『국어』 68쪽 횡단보도 그림이에요. 신호등에 켜진 사람 모양 그림과 숫자는 무엇을 나타내나요?',ARRAY['K3-2-u2-X07','K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 68쪽 횡단보도 그림이에요. 신호등에 켜진 사람 모양 그림과 숫자는 무엇을 나타내나요?","options":[{"t":"사람이 건너는 신호라는 것과 남은 시간","correct":true},{"t":"신호등을 예쁘게 꾸미려고 넣은 그림과 숫자","mis":"K3-2-u2-X07"},{"t":"지금까지 길을 건넌 사람의 수","mis":"K3-2-u2-X08"},{"t":"차가 지나가도 된다는 신호와 차의 빠르기","mis":"K3-2-u2-X15"}],"explanation":["사람 모양 그림은 사람이 건너도 된다는 신호예요.","숫자는 건널 수 있는 시간이 얼마나 남았는지 알려 줘요.","글자 없이도 멀리서 한눈에 알아보게 그림과 숫자를 썼어요."],"asset":{"type":"passage","lines":["[그림] 학교 앞 횡단보도 — 『국어』 68쪽","신호등: 사람 모양 그림과 숫자가 함께 켜져 있다.","바닥: 건너는 길 양쪽에 노란색 화살표가 그려져 있다.","노란색 화살표는 길을 건널 때 오른쪽으로 가라는 뜻이다."],"title":"횡단보도 근처의 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#2','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C3',1,'ox','auto','횡단보도 바닥의 노란색 화살표가 없어도 사람들은 모두 오른쪽으로 건너서 서로 부딪칠 일이 없어요.',ARRAY['K3-2-u2-X07']::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":1,"kind":"ox","stem":"횡단보도 바닥의 노란색 화살표가 없어도 사람들은 모두 오른쪽으로 건너서 서로 부딪칠 일이 없어요.","answer":"X","reason_options":[{"t":"화살표가 없으면 방향에 상관없이 건너게 되어 사람들끼리 부딪칠 수 있어요.","correct":true},{"t":"화살표는 바닥을 꾸미려고 그린 것이라 없어도 똑같아요.","mis":"K3-2-u2-X07"}],"mis":"K3-2-u2-X07","explanation":["노란색 화살표는 길을 건널 때 오른쪽으로 가라는 뜻이에요.","화살표가 없으면 저마다 아무 쪽으로나 건너게 돼요.","그래서 사람들끼리 부딪칠 수 있어요."],"asset":{"type":"passage","lines":["[그림] 학교 앞 횡단보도 — 『국어』 68쪽","신호등: 사람 모양 그림과 숫자가 함께 켜져 있다.","바닥: 건너는 길 양쪽에 노란색 화살표가 그려져 있다.","노란색 화살표는 길을 건널 때 오른쪽으로 가라는 뜻이다."],"title":"횡단보도 근처의 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#3','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',1,'mc','auto','『국어』 69쪽에서 ∨는 쉬어 읽는 표시예요. ∨∨(∨ 두 개를 이어 쓴 표시)는 무엇을 나타내나요?',ARRAY['K3-2-u2-X06','K3-2-u2-X02']::text[],false,'{"seq":3,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 69쪽에서 ∨는 쉬어 읽는 표시예요. ∨∨(∨ 두 개를 이어 쓴 표시)는 무엇을 나타내나요?","options":[{"t":"∨보다 더 길게 쉬어 읽는 표시","correct":true},{"t":"∨보다 더 짧게 쉬어 읽는 표시","mis":"K3-2-u2-X06"},{"t":"읽기를 그만 멈추고 끝내라는 표시","mis":"K3-2-u2-X06"},{"t":"그곳을 가장 큰 소리로 읽으라는 표시","mis":"K3-2-u2-X02"}],"explanation":["∨는 조금 쉬어 읽는 표시예요.","∨∨는 ∨보다 더 길게 쉬어 읽는 표시예요.","문장과 문장 사이에 ∨∨를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#4','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',1,'blank','auto','『국어』 72쪽 「글을 유창하게 읽는 방법」이에요. 「문장과 문장 사이는 (     ) 띄어 읽는다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X06','K3-2-u2-X05','K3-2-u2-X04']::text[],false,'{"seq":4,"concept":"K3-2-u2-C2","difficulty":1,"kind":"blank","stem":"『국어』 72쪽 「글을 유창하게 읽는 방법」이에요. 「문장과 문장 사이는 (     ) 띄어 읽는다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"조금 더 길게","correct":true},{"t":"쉬지 않고 이어서","mis":"K3-2-u2-X06"},{"t":"한 낱말마다","mis":"K3-2-u2-X05"},{"t":"아무 데서나","mis":"K3-2-u2-X04"}],"explanation":["한 문장이 끝나면 뜻이 한 번 매듭지어져요.","그래서 문장과 문장 사이는 조금 더 길게 쉬어요.","‘누가/무엇이’ 다음보다 더 길게 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#5','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'mc','auto','「나무」를 읽고 답해요. 글에서 나무로 만든다고 하지 않은 것은 어느 것인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":5,"concept":"K3-2-u2-C4","difficulty":2,"kind":"mc","stem":"「나무」를 읽고 답해요. 글에서 나무로 만든다고 하지 않은 것은 어느 것인가요?","options":[{"t":"콘크리트","correct":true},{"t":"가구","mis":"K3-2-u2-X15"},{"t":"종이","mis":"K3-2-u2-X15"},{"t":"악기","mis":"K3-2-u2-X15"}],"explanation":["가구, 살림 도구, 장난감, 종이, 악기는 나무로 만든다고 했어요.","「지금은 철근과 콘크리트로 집을 짓지만」이라고 했어요.","콘크리트는 나무로 만든 것이 아니에요."],"asset":{"type":"passage","lines":["우리 생활 주변에는 나무로 만든 물건이 많이 있습니다.","가구나 살림 도구, 장난감 같은 것입니다. 종이도 나무로 만듭니다.","나무로 악기도 만들 수 있습니다.","나무로 집도 만듭니다.","지금은 철근과 콘크리트로 집을 짓지만","예전에는 나무 없이는 집을 지을 수 없었습니다."],"title":"「나무」 앞부분 — 『국어』 70쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#6','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'sa','auto','「나무」에서 버드나무 껍질로 만든 약은 열을 내리고 무엇을 달래 준다고 했나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C4","difficulty":2,"kind":"sa","stem":"「나무」에서 버드나무 껍질로 만든 약은 열을 내리고 무엇을 달래 준다고 했나요? 한 낱말로 쓰세요.","answer":["통증"],"explanation":["버드나무 껍질로 만든 약을 설명한 줄을 찾아요.","「열을 내리고 통증을 달래 주는 약」이라고 했어요.","답은 「통증」이에요."],"asset":{"type":"passage","lines":["(간추림) 육계나무·헛개나무·가시오갈피는 껍질을 말려서 쓴다.","(간추림) 차나무·감나무·뽕나무는 잎을 말려서 차로 끓여 마신다.","(간추림) 버드나무 껍질로는 열을 내리고 통증을 달래 주는 약을,","은행나무잎으로는 피를 잘 돌게 하는 약을 만든다."],"title":"「나무」 가운데 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#7','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'match','auto','『국어』 72쪽 4번이에요. 친구들이 「나무」를 어떻게 읽었는지 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C4","difficulty":2,"kind":"match","stem":"『국어』 72쪽 4번이에요. 친구들이 「나무」를 어떻게 읽었는지 알맞게 이으세요.","pairs":[{"l":"“나무로 만든 집에서 잔 적이 있는데 여름인데도 정말 시원했어.”","r":"아는 점이나 관련 있는 경험과 비교하며 읽었다."},{"l":"“사람들이 먹는 과일의 종류에는 무엇이 있을까?”","r":"더 알고 싶거나 궁금한 점을 중심으로 읽었다."},{"l":"“길가에 은행나무를 왜 심었는지 알았어.”","r":"새롭게 안 점을 생각하며 읽었다."}],"mis":"K3-2-u2-X35","explanation":["전에 겪은 일과 견주면 「아는 점이나 관련 있는 경험」이에요.","「무엇이 있을까?」처럼 묻는 말은 「더 알고 싶거나 궁금한 점」이에요.","「알았어」는 이 글에서 「새롭게 안 점」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#8','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'mc','auto','「나무」를 녹음하고 다시 들어 보려고 해요. 녹음 시작 기호(●)를 누르고 글을 다 읽었어요. 다음에 할 일은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X09']::text[],false,'{"seq":8,"concept":"K3-2-u2-C4","difficulty":2,"kind":"mc","stem":"「나무」를 녹음하고 다시 들어 보려고 해요. 녹음 시작 기호(●)를 누르고 글을 다 읽었어요. 다음에 할 일은 무엇인가요?","options":[{"t":"정지 기호(■)를 눌러 녹음을 마친다","correct":true},{"t":"녹음한 시간이 몇 초인지만 보고 끝낸다","mis":"K3-2-u2-X01"},{"t":"친구 녹음과 견주어 누가 더 잘했는지 점수를 매긴다","mis":"K3-2-u2-X09"},{"t":"듣지 않고 바로 다른 글을 녹음한다","mis":"K3-2-u2-X09"}],"explanation":["①에서 읽기를 마쳤으면 ② 정지 기호(■)를 눌러요.","그다음 ③ 재생 기호(▶)로 들으며 어떻게 읽었는지 확인해요.","④ 아쉬운 부분을 찾아 ⑤ 다시 해 봐요."],"asset":{"type":"passage","lines":["① 녹음 시작 기호(●)를 누른 뒤 글을 유창하게 소리 내어 읽는다.","② 정지 기호(■)를 눌러서 녹음을 마친다.","③ 재생 기호(▶)를 누르고 자신이 어떻게 읽는지 확인한다.","④ 아쉬운 부분을 찾아 어떻게 읽어야 할지 생각한다.","⑤ 위 과정을 반복한다."],"title":"녹음하고 다시 듣는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#9','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',2,'error','auto','「가을 나들이에 주의합시다」를 읽고 친구들이 말했어요. 띄어 읽기를 알맞게 하지 않은 친구는 누구인가요?',ARRAY['K3-2-u2-X05','K3-2-u2-X04','K3-2-u2-X06']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"error","stem":"「가을 나들이에 주의합시다」를 읽고 친구들이 말했어요. 띄어 읽기를 알맞게 하지 않은 친구는 누구인가요?","options":[{"t":"윤호: 한 낱말을 읽을 때마다 모두 끊어서 쉬었어.","correct":true,"mis_target":"K3-2-u2-X05"},{"t":"고은: ‘누가/무엇이’ 다음에 조금 띄어 읽었어.","mis":"K3-2-u2-X04"},{"t":"혜윤: 문장과 문장 사이는 조금 더 길게 띄어 읽었어.","mis":"K3-2-u2-X06"}],"explanation":["고은이와 혜윤이는 『국어』 72쪽 방법대로 읽었어요.","한 낱말마다 끊으면 뜻이 흩어져 듣는 사람이 알아듣기 어려워요.","그래서 윤호의 읽기가 알맞지 않아요."],"asset":{"type":"passage","lines":["가을은 나들이하기에 좋은 계절입니다.","그러나 가을은 진드기가 급증하는 시기이기도 합니다.","나들이할 때에는 긴팔, 긴바지를 입어서 피부를 가려 주어야 합니다.","풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.","집에 돌아와서는 몸을 깨끗이 씻고 옷도 세탁합니다."],"title":"「가을 나들이에 주의합시다」 — 『국어활동』 22쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_basic#10','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',3,'mc','auto','『국어』 73쪽 「스스로 확인하면서 소리 내어 읽어 보기」에 있는 물음이 아닌 것은 어느 것인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X06','K3-2-u2-X01']::text[],false,'{"seq":10,"concept":"K3-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 73쪽 「스스로 확인하면서 소리 내어 읽어 보기」에 있는 물음이 아닌 것은 어느 것인가요?","options":[{"t":"친구보다 몇 초 더 빨리 읽었나요?","correct":true},{"t":"‘누가/무엇이’ 다음에 조금 띄어 읽을 수 있나요?","mis":"K3-2-u2-X04"},{"t":"문장과 문장 사이는 조금 더 길게 띄어 읽을 수 있나요?","mis":"K3-2-u2-X06"},{"t":"정확한 발음과 적절한 속도로 읽을 수 있나요?","mis":"K3-2-u2-X01"}],"explanation":["스스로 확인하는 물음은 띄어 읽기 두 가지와 발음·속도예요.","빠르기를 친구와 견주는 물음은 없어요.","점검은 다음에 더 잘 읽으려고 하는 일이에요."],"asset":{"type":"passage","lines":["‘누가/무엇이’ 다음에 조금 띄어 읽을 수 있나요?  ○○○","문장과 문장 사이는 조금 더 길게 띄어 읽을 수 있나요?  ○○○","정확한 발음과 적절한 속도로 읽을 수 있나요?  ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"스스로 확인하면서 소리 내어 읽어 보기 — 『국어』 73쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#1','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',2,'mc','auto','『국어』 69쪽 글의 둘째 문장을 ‘누가/무엇이’ 다음에 조금 띄어 읽었어요. 알맞게 표시한 것은 어느 것인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 69쪽 글의 둘째 문장을 ‘누가/무엇이’ 다음에 조금 띄어 읽었어요. 알맞게 표시한 것은 어느 것인가요?","options":[{"t":"주의 표지판은∨노란색 배경에∨진한 빨간색 선이 둘려 있습니다.","correct":true},{"t":"주의∨표지판은 노란색 배경에 진한 빨간색 선이 둘려 있습니다.","mis":"K3-2-u2-X04"},{"t":"주의∨표지판은∨노란색∨배경에∨진한∨빨간색∨선이∨둘려∨있습니다.","mis":"K3-2-u2-X05"},{"t":"주의 표지판은 노란색 배경에 진한 빨간색∨선이 둘려 있습니다.","mis":"K3-2-u2-X04"}],"explanation":["이 문장에서 ‘무엇이’에 해당하는 말은 「주의 표지판은」이에요.","그 다음에 조금 띄어 읽고, 뜻 덩어리마다 한 번 더 쉴 수 있어요.","덩어리 한가운데를 끊거나 낱말마다 끊지 않아요."],"asset":{"type":"passage","lines":["우리는 길을 걸을 때 주의 표지판을 자주 봅니다.","주의 표지판은 노란색 배경에 진한 빨간색 선이 둘려 있습니다.","그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.","오른쪽 주의 표지판은 “공사 중입니다. 조심히 지나가세요!”라는 뜻을 나타냅니다.","[그림] 세모난 노란 표지판 안에 땅을 파는 사람 모양"],"title":"『국어』 69쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#2','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C3',2,'mc','auto','『국어』 69쪽 ‘공사 중’ 주의 표지판은 노란색 배경에 빨간색 선을 둘렀어요. 이렇게 색을 쓴 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X07','K3-2-u2-X31']::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 69쪽 ‘공사 중’ 주의 표지판은 노란색 배경에 빨간색 선을 둘렀어요. 이렇게 색을 쓴 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"사람들이 주의할 점을 바로 파악할 수 있게 하려고","correct":true},{"t":"표지판을 알록달록하게 꾸미려고","mis":"K3-2-u2-X07"},{"t":"글씨를 쓰기 귀찮아서","mis":"K3-2-u2-X07"},{"t":"노란색과 빨간색은 차분하고 차가운 느낌을 주어서","mis":"K3-2-u2-X31"}],"explanation":["글에 「그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.」라고 했어요.","눈에 잘 띄는 색은 멀리서도 바쁠 때도 한눈에 보여요.","노랑·빨강은 따뜻하고 눈에 띄는 색이에요."],"asset":{"type":"passage","lines":["우리는 길을 걸을 때 주의 표지판을 자주 봅니다.","주의 표지판은 노란색 배경에 진한 빨간색 선이 둘려 있습니다.","그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.","오른쪽 주의 표지판은 “공사 중입니다. 조심히 지나가세요!”라는 뜻을 나타냅니다.","[그림] 세모난 노란 표지판 안에 땅을 파는 사람 모양"],"title":"『국어』 69쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#3','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',3,'ox','auto','나겸이는 「그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.」를 「사람들은」 뒤에서만 쉬었고, 한울이는 「사람들은」과 「주의할 점을」 뒤에서 쉬었어요. 둘 가운데 한 명은 반드시 틀렸어요.',ARRAY['K3-2-u2-X03']::text[],false,'{"seq":3,"concept":"K3-2-u2-C2","difficulty":3,"kind":"ox","stem":"나겸이는 「그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.」를 「사람들은」 뒤에서만 쉬었고, 한울이는 「사람들은」과 「주의할 점을」 뒤에서 쉬었어요. 둘 가운데 한 명은 반드시 틀렸어요.","answer":"X","reason_options":[{"t":"뜻이 달라지지 않으면 띄어 읽는 곳은 숨 쉬는 데 따라 조금씩 달라도 돼요.","correct":true},{"t":"쉬어 읽는 곳은 언제나 한 곳뿐이에요.","mis":"K3-2-u2-X03"}],"mis":"K3-2-u2-X03","explanation":["두 친구 모두 뜻 덩어리 끝에서 쉬었어요.","띄어 읽기는 글의 뜻을 바르게 이해하려고 하는 거예요.","뜻이 달라지지 않는 범위에서는 쉬는 곳이 조금 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#4','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',3,'mc','auto','「나무」에서 은행나무나 플라타너스를 길가에 가로수로 심는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":4,"concept":"K3-2-u2-C4","difficulty":3,"kind":"mc","stem":"「나무」에서 은행나무나 플라타너스를 길가에 가로수로 심는 까닭은 무엇인가요?","options":[{"t":"공해에 강하고 잎에 잔털이 있어 먼지를 잡아 주기 때문","correct":true},{"t":"가시가 있어 울타리 대신 쓸 수 있기 때문","mis":"K3-2-u2-X15"},{"t":"잎을 말려서 차로 끓여 마시기 때문","mis":"K3-2-u2-X15"},{"t":"열매로 잼을 만들어 먹기 때문","mis":"K3-2-u2-X08"}],"explanation":["가로수를 설명한 줄을 찾아 다시 읽어요.","「공해에 강하고 잎에 잔털이 있어 먼지를 잡아 주는」이라고 했어요.","울타리는 찔레나무·탱자나무, 차는 차나무·감나무·뽕나무 이야기예요."],"asset":{"type":"passage","lines":["(간추림) 사람이 먹는 나무 열매를 과일이라고 한다.","(간추림) 가시가 있는 찔레나무·탱자나무는 옛날부터 울타리로 썼다.","(간추림) 은행나무·플라타너스는 공해에 강하고 잎에 잔털이 있어","먼지를 잡아 주어 길가에 가로수로 심는다.","나무는 다른 나무와 풀, 온갖 동물과 어우러져 숲을 이룹니다."],"title":"「나무」 뒷부분 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#5','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',3,'sa','auto','「나무」에서 잎을 말려서 차로 끓여 마신다고 한 나무 가운데 하나를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u2-C4","difficulty":3,"kind":"sa","stem":"「나무」에서 잎을 말려서 차로 끓여 마신다고 한 나무 가운데 하나를 쓰세요.","answer":["차나무","감나무","뽕나무"],"explanation":["「잎을 말려서」라는 말이 있는 줄을 찾아요.","차나무, 감나무, 뽕나무 — 세 가지가 나와요.","껍질을 말려 쓰는 육계나무·헛개나무·가시오갈피와 헷갈리지 않아요."],"asset":{"type":"passage","lines":["(간추림) 육계나무·헛개나무·가시오갈피는 껍질을 말려서 쓴다.","(간추림) 차나무·감나무·뽕나무는 잎을 말려서 차로 끓여 마신다.","(간추림) 버드나무 껍질로는 열을 내리고 통증을 달래 주는 약을,","은행나무잎으로는 피를 잘 돌게 하는 약을 만든다."],"title":"「나무」 가운데 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#6','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',3,'mc','auto','「가시가 있는 찔레나무나 탱자나무는 옛날부터 돌담을 대신하는 울타리로 썼습니다.」는 ‘누가/무엇이’에 해당하는 말이 길어요. 알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":6,"concept":"K3-2-u2-C2","difficulty":3,"kind":"mc","stem":"「가시가 있는 찔레나무나 탱자나무는 옛날부터 돌담을 대신하는 울타리로 썼습니다.」는 ‘누가/무엇이’에 해당하는 말이 길어요. 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"가시가 있는∨찔레나무나 탱자나무는∨옛날부터 돌담을 대신하는 울타리로 썼습니다.","correct":true},{"t":"가시가∨있는 찔레나무나∨탱자나무는 옛날부터 돌담을 대신하는 울타리로 썼습니다.","mis":"K3-2-u2-X04"},{"t":"가시가 있는 찔레나무나 탱자나무는 옛날부터 돌담을 대신하는 울타리로∨썼습니다.","mis":"K3-2-u2-X04"},{"t":"가시가∨있는∨찔레나무나∨탱자나무는∨옛날부터∨돌담을∨대신하는∨울타리로∨썼습니다.","mis":"K3-2-u2-X05"}],"explanation":["‘무엇이’는 「가시가 있는 찔레나무나 탱자나무는」으로 길어요.","말이 길면 「가시가 있는」 뒤에서 한 번 더, 「탱자나무는」 뒤에서 조금 띄어요.","덩어리 가운데를 끊거나 낱말마다 끊지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#7','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C1',3,'mc','auto','짝과 문장 바꾸어 읽기 놀이를 해요. 친구가 「나무로 집도 만듭니다.」를 「나무로 집도 만듭니까?」로 바꾸어 말했어요. 「만듭니까?」를 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X32','K3-2-u2-X02','K3-2-u2-X01']::text[],false,'{"seq":7,"concept":"K3-2-u2-C1","difficulty":3,"kind":"mc","stem":"짝과 문장 바꾸어 읽기 놀이를 해요. 친구가 「나무로 집도 만듭니다.」를 「나무로 집도 만듭니까?」로 바꾸어 말했어요. 「만듭니까?」를 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"묻는 말이니 끝을 살짝 올려 묻는 말투로 읽는다","correct":true},{"t":"「만듭니다.」와 똑같이 끝을 내려 읽는다","mis":"K3-2-u2-X32"},{"t":"물음표가 있으면 가장 큰 소리로 읽는다","mis":"K3-2-u2-X02"},{"t":"물음표가 나오면 아주 빠르게 읽는다","mis":"K3-2-u2-X01"}],"explanation":["물음표(?)가 붙은 문장은 묻는 말이에요.","끝을 살짝 올려야 듣는 사람이 묻는 말인 줄 알아요.","짝은 다시 「나무로 집도 만듭니다.」라고 대답하며 번갈아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#8','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',4,'mc','auto','은솔이가 「나무」를 녹음해 들어 보니 「기둥, 대들보, 서까래」에서 자꾸 더듬었어요. 「녹음하고 다시 듣는 방법」대로라면 다음에 할 일은 무엇인가요?',ARRAY['K3-2-u2-X09','K3-2-u2-X01']::text[],false,'{"seq":8,"concept":"K3-2-u2-C4","difficulty":4,"kind":"mc","stem":"은솔이가 「나무」를 녹음해 들어 보니 「기둥, 대들보, 서까래」에서 자꾸 더듬었어요. 「녹음하고 다시 듣는 방법」대로라면 다음에 할 일은 무엇인가요?","options":[{"t":"더듬은 부분을 어떻게 읽을지 생각한 뒤 다시 녹음해 들어 본다","correct":true},{"t":"한 번 녹음했으니 점검을 끝낸다","mis":"K3-2-u2-X09"},{"t":"더듬은 곳을 세어 점수를 매기고 친구와 견준다","mis":"K3-2-u2-X09"},{"t":"어려운 낱말은 빼고 빨리 읽어 시간을 줄인다","mis":"K3-2-u2-X01"}],"explanation":["④ 아쉬운 부분을 찾아 어떻게 읽어야 할지 생각해요.","⑤ 그 과정을 반복하며 다시 녹음하고 들어요.","점검은 점수를 매기려는 것이 아니라 더 잘 읽으려는 거예요."],"asset":{"type":"passage","lines":["① 녹음 시작 기호(●)를 누른 뒤 글을 유창하게 소리 내어 읽는다.","② 정지 기호(■)를 눌러서 녹음을 마친다.","③ 재생 기호(▶)를 누르고 자신이 어떻게 읽는지 확인한다.","④ 아쉬운 부분을 찾아 어떻게 읽어야 할지 생각한다.","⑤ 위 과정을 반복한다."],"title":"녹음하고 다시 듣는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#9','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C1',4,'ox','auto','『국어』의 「글을 유창하게 읽는 방법」은 띄어 읽기뿐이라, 알맞은 목소리와 말투로 읽는 것은 유창하게 읽기와 상관이 없어요.',ARRAY['K3-2-u2-X05']::text[],false,'{"seq":9,"concept":"K3-2-u2-C1","difficulty":4,"kind":"ox","stem":"『국어』의 「글을 유창하게 읽는 방법」은 띄어 읽기뿐이라, 알맞은 목소리와 말투로 읽는 것은 유창하게 읽기와 상관이 없어요.","answer":"X","reason_options":[{"t":"정확한 발음과 적절한 속도, 알맞은 목소리와 말투로 읽는 것도 유창하게 읽는 방법이에요.","correct":true},{"t":"띄어 읽기만 정확하면 다른 것은 살피지 않아도 돼요.","mis":"K3-2-u2-X05"}],"mis":"K3-2-u2-X05","explanation":["띄어 읽기는 뜻을 바르게 전하려고 하는 거예요.","발음·속도·목소리·말투도 뜻이 잘 전해지게 도와줘요.","띄어 읽기에만 매달리면 글의 뜻을 놓칠 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L02_challenge#10','kor',3,2,'u2','L02','tb_g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',4,'essay','teacher','「나무」를 읽고 새롭게 안 내용을 한 문장으로 쓰세요. 문장은 「누가/무엇이」와 「어찌하다/어떠하다/무엇이다」의 짜임에 맞게 쓰고, 그 내용이 나온 부분도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C4","difficulty":4,"kind":"essay","stem":"「나무」를 읽고 새롭게 안 내용을 한 문장으로 쓰세요. 문장은 「누가/무엇이」와 「어찌하다/어떠하다/무엇이다」의 짜임에 맞게 쓰고, 그 내용이 나온 부분도 함께 쓰세요.","answer_guide":{"answer":"예: 감나무잎은 말려서 차로 끓여 마실 수 있다. — 「차나무, 감나무, 뽕나무는 잎을 말려서 차로 끓여 마십니다.」에서 알았다.","scoring_points":["새롭게 안 내용을 썼는가","「누가/무엇이」와 「어찌하다/어떠하다/무엇이다」 짜임에 맞는 한 문장인가","그 내용이 나온 부분을 글에서 찾아 썼는가"]},"explanation":["새롭게 안 점은 글에 쓰여 있는 것에서 찾아요.","문장의 짜임은 3학년 1학기에 배운 대로 써요.","나온 곳을 밝히면 친구도 확인할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 육계나무·헛개나무·가시오갈피는 껍질을 말려서 쓴다.","(간추림) 차나무·감나무·뽕나무는 잎을 말려서 차로 끓여 마신다.","(간추림) 버드나무 껍질로는 열을 내리고 통증을 달래 주는 약을,","은행나무잎으로는 피를 잘 돌게 하는 약을 만든다."],"title":"「나무」 가운데 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#1','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',1,'blank','auto','『국어』 81쪽이에요. 「장면에서 느껴지는 기분을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X11','K3-2-u2-X36','K3-2-u2-X32']::text[],false,'{"seq":1,"concept":"K3-2-u2-C5","difficulty":1,"kind":"blank","stem":"『국어』 81쪽이에요. 「장면에서 느껴지는 기분을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"분위기","correct":true},{"t":"인물의 마음","mis":"K3-2-u2-X11"},{"t":"인물이 처한 상황","mis":"K3-2-u2-X36"},{"t":"말투","mis":"K3-2-u2-X32"}],"explanation":["장면 전체에서 느껴지는 기분을 분위기라고 해요.","인물의 마음·상황·말과 행동을 모으면 분위기가 드러나요.","분위기를 알아야 그 장면을 살려 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#2','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',1,'mc','auto','『국어』 74~79쪽 「신기한 구슬」을 떠올려요. 강토에게 생긴 큰일은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":2,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"『국어』 74~79쪽 「신기한 구슬」을 떠올려요. 강토에게 생긴 큰일은 무엇인가요?","options":[{"t":"생일을 하루 앞두고 할아버지께서 큰 병이 나셨다","correct":true},{"t":"생일 선물로 받은 펭귄 인형을 잃어버렸다","mis":"K3-2-u2-X15"},{"t":"엄마가 큰 병원에 입원하셨다","mis":"K3-2-u2-X15"},{"t":"송이가 강토의 생일을 잊어버렸다","mis":"K3-2-u2-X15"}],"explanation":["「큰일은 엉뚱한 곳에서 터졌다」 다음 줄을 다시 읽어요.","생일 하루 앞, 할아버지가 큰 병이 나셨어요.","송이는 오히려 오빠 생일을 기억했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#3','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',1,'blank','auto','『국어』 81쪽 3번 (2)예요. 「인물이 처한 (     )을/를 떠올리며 실감 나게 읽는다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X11','K3-2-u2-X01','K3-2-u2-X02']::text[],false,'{"seq":3,"concept":"K3-2-u2-C6","difficulty":1,"kind":"blank","stem":"『국어』 81쪽 3번 (2)예요. 「인물이 처한 (     )을/를 떠올리며 실감 나게 읽는다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"상황","correct":true},{"t":"날씨","mis":"K3-2-u2-X11"},{"t":"빠르기","mis":"K3-2-u2-X01"},{"t":"목소리 크기","mis":"K3-2-u2-X02"}],"explanation":["인물이 어떤 일을 겪고 있는지 먼저 떠올려요.","그 상황이 떠오르면 실감 나게 읽을 수 있어요.","정리: 상황 — 실감 나게 · 말과 행동 — 표정과 몸짓 · 마음 — 목소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#4','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',1,'match','auto','장면의 분위기에 따라 글을 읽는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u2-C6","difficulty":1,"kind":"match","stem":"장면의 분위기에 따라 글을 읽는 방법을 알맞게 이으세요.","pairs":[{"l":"인물이 처한 상황","r":"떠올리며 실감 나게 읽는다."},{"l":"인물의 말이나 행동","r":"어울리는 표정과 몸짓으로 읽는다."},{"l":"인물의 마음","r":"잘 드러나는 목소리로 읽는다."}],"mis":"K3-2-u2-X12","explanation":["상황은 떠올리고, 말과 행동은 표정과 몸짓으로 살려요.","마음은 목소리에 담아요.","세 가지를 함께 살리면 장면의 분위기가 잘 느껴져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#5','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'mc','auto','『국어』 80쪽 3번 (1)의 장면이에요. 이 장면의 분위기로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":5,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"『국어』 80쪽 3번 (1)의 장면이에요. 이 장면의 분위기로 알맞은 것은 무엇인가요?","options":[{"t":"조용하고 우울하다","correct":true},{"t":"행복하고 즐겁다","mis":"K3-2-u2-X12"},{"t":"신비롭고 환상적이다","mis":"K3-2-u2-X12"},{"t":"시끄럽고 신난다","mis":"K3-2-u2-X12"}],"explanation":["할아버지가 편찮으시고, 생일인데 미역국도 없어요.","강토는 서운한 마음을 꾹 누르고 할아버지 안부를 물어요.","그래서 조용하고 우울한 분위기가 느껴져요."],"asset":{"type":"passage","lines":["다음 날 아침 강토는 일찍 일어나 집안 분위기를 살폈다.","엄마는 부스스한 얼굴로 아침상을 차리고 있었다.","(간추림) 케이크도 미역국도 없는 밥상 — 엄마는 생일을 잊은 듯했다.","(간추림) 강토는 서운한 마음을 꾹 누르고 엄마에게 물었다.","“엄마, 할아버지는 좀 어떠세요?”"],"title":"「신기한 구슬」 아침 장면 — 『국어』 80쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#6','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'mc','auto','같은 장면에서 「인물의 말이나 행동」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u2-X36','K3-2-u2-X11']::text[],false,'{"seq":6,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"같은 장면에서 「인물의 말이나 행동」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"강토: “엄마, 할아버지는 좀 어떠세요?”","correct":true},{"t":"강토의 생일을 하루 앞두고 할아버지께서 큰 병이 나셨다.","mis":"K3-2-u2-X36"},{"t":"강토: 할아버지가 걱정되면서도 생일을 잊은 엄마에게 서운한 마음","mis":"K3-2-u2-X36"},{"t":"다음 날 아침이라는 때","mis":"K3-2-u2-X11"}],"explanation":["따옴표 속 말과 몸의 움직임이 「말이나 행동」이에요.","할아버지가 큰 병이 나신 일은 「인물이 처한 상황」이에요.","걱정되고 서운한 것은 「인물의 마음」이에요."],"asset":{"type":"passage","lines":["다음 날 아침 강토는 일찍 일어나 집안 분위기를 살폈다.","엄마는 부스스한 얼굴로 아침상을 차리고 있었다.","(간추림) 케이크도 미역국도 없는 밥상 — 엄마는 생일을 잊은 듯했다.","(간추림) 강토는 서운한 마음을 꾹 누르고 엄마에게 물었다.","“엄마, 할아버지는 좀 어떠세요?”"],"title":"「신기한 구슬」 아침 장면 — 『국어』 80쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#7','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'ox','auto','미역국이라는 말을 듣고 강토의 눈물샘이 터진 까닭으로 답할 수 있는 것은 「서운했기 때문」 한 가지뿐이에요.',ARRAY['K3-2-u2-X10']::text[],false,'{"seq":7,"concept":"K3-2-u2-C5","difficulty":2,"kind":"ox","stem":"미역국이라는 말을 듣고 강토의 눈물샘이 터진 까닭으로 답할 수 있는 것은 「서운했기 때문」 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"「생일을 챙겨 주시는 할머니께 고마웠기 때문」처럼 글에서 까닭을 찾아 말하면 다른 답도 알맞아요.","correct":true},{"t":"마음을 묻는 물음에는 답이 하나뿐이라 다른 답은 틀려요.","mis":"K3-2-u2-X10"}],"mis":"K3-2-u2-X10","explanation":["『국어』 80쪽 2번 (2)의 예시 답은 두 가지예요.","미역국도 못 먹는 줄 알고 서운했다는 답, 할머니께 고마웠다는 답이에요.","글 속 까닭을 대면 서로 다른 답도 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#8','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',2,'mc','auto','강토가 열 살 생일을 손꼽아 기다리는 장면을 읽을 때 어울리는 목소리는 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X13']::text[],false,'{"seq":8,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"강토가 열 살 생일을 손꼽아 기다리는 장면을 읽을 때 어울리는 목소리는 무엇인가요?","options":[{"t":"들뜨고 밝은 목소리","correct":true},{"t":"낮고 어두운 목소리","mis":"K3-2-u2-X12"},{"t":"울먹이는 목소리","mis":"K3-2-u2-X12"},{"t":"가장 크고 빠른 목소리","mis":"K3-2-u2-X13"}],"explanation":["생일을 기다리는 강토의 마음은 설레요.","설레는 장면은 밝은 분위기예요.","할아버지가 편찮으신 장면은 어두운 분위기로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#9','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',2,'mc','auto','『국어활동』 23쪽이에요. ㉠ 장면에 어울리는 목소리를 보기에서 고르면 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":9,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"『국어활동』 23쪽이에요. ㉠ 장면에 어울리는 목소리를 보기에서 고르면 무엇인가요?","options":[{"t":"속상하다","correct":true},{"t":"명랑하다","mis":"K3-2-u2-X12"},{"t":"반갑다","mis":"K3-2-u2-X12"},{"t":"놀라다","mis":"K3-2-u2-X12"}],"explanation":["흥부가 다리가 부러진 제비를 보았어요.","「많이 아프겠구나」 하며 정성껏 치료해 주는 장면이에요.","슬프거나 속상한 목소리가 어울려요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_basic#10','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',3,'mc','auto','『국어』 81쪽 3번 (3)의 장면이에요. 분위기와 그렇게 느낀 까닭을 바르게 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X30','K3-2-u2-X10','K3-2-u2-X12']::text[],false,'{"seq":10,"concept":"K3-2-u2-C5","difficulty":3,"kind":"mc","stem":"『국어』 81쪽 3번 (3)의 장면이에요. 분위기와 그렇게 느낀 까닭을 바르게 말한 친구는 누구인가요?","options":[{"t":"서아: 행복하고 즐거워. 할아버지가 챙겨 두신 선물을 갑자기 받았으니까.","correct":true},{"t":"준호: 조용하고 우울해. 이 이야기는 처음부터 끝까지 그러니까.","mis":"K3-2-u2-X30"},{"t":"하린: 행복하고 즐거워. 다들 그렇게 골랐으니까.","mis":"K3-2-u2-X10"},{"t":"도윤: 무서워. 상자 속에 무엇이 들었는지 몰라서.","mis":"K3-2-u2-X12"}],"explanation":["할머니는 선물을 잊었다가 놀라고, 강토는 갑작스러운 선물에 감격해요.","그래서 행복하고 즐거운 분위기예요.","분위기는 장면마다 바뀌고, 까닭은 글에서 찾아요."],"asset":{"type":"passage","lines":["“아이고, 내 정신 좀 봐.”","선물이라는 말에 할머니가 무릎을 탁 치셨다.","(간추림) 할머니는 노란 보자기로 싼 작은 상자를 들고 나오셨다.","“그게 뭐예요?”","(간추림) 할아버지가 며칠 전 강토 생일 선물로 챙겨 두신 것이었다.","“생일 선물이요?”"],"title":"「신기한 구슬」 선물 장면 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#1','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',2,'mc','auto','제목 「신기한 구슬」에서 느껴지는 분위기를 ‘신기하다’와 비슷한 다른 말로 나타낸 것은 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":1,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"제목 「신기한 구슬」에서 느껴지는 분위기를 ‘신기하다’와 비슷한 다른 말로 나타낸 것은 무엇인가요?","options":[{"t":"신비롭다","correct":true},{"t":"쓸쓸하다","mis":"K3-2-u2-X12"},{"t":"답답하다","mis":"K3-2-u2-X12"},{"t":"지루하다","mis":"K3-2-u2-X12"}],"explanation":["‘신기하다’와 비슷한 분위기를 나타내는 말을 찾아요.","「환상적이다」, 「이상하다」, 「신비롭다」가 비슷해요.","분위기를 말할 때는 그렇게 느낀 까닭도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#2','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',2,'mc','auto','『국어활동』 23쪽 ㉡ 장면에 어울리는 목소리를 보기에서 고르면 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":2,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"『국어활동』 23쪽 ㉡ 장면에 어울리는 목소리를 보기에서 고르면 무엇인가요?","options":[{"t":"울먹이다","correct":true},{"t":"명랑하다","mis":"K3-2-u2-X12"},{"t":"놀라다","mis":"K3-2-u2-X12"},{"t":"반갑다","mis":"K3-2-u2-X12"}],"explanation":["다 나은 제비가 남쪽으로 떠나는 장면이에요.","정든 제비를 보내며 손을 흔드는 흥부의 마음은 아쉬워요.","울먹이는 목소리와 표정이 어울려요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#3','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'error','auto','친구들이 「신기한 구슬」의 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X30','K3-2-u2-X12']::text[],false,'{"seq":3,"concept":"K3-2-u2-C5","difficulty":3,"kind":"error","stem":"친구들이 「신기한 구슬」의 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하준: 이 이야기는 처음부터 끝까지 우울한 분위기 하나뿐이야.","correct":true,"mis_target":"K3-2-u2-X30"},{"t":"서윤: 생일 아침 밥상 장면은 조용하고 우울해.","mis":"K3-2-u2-X12"},{"t":"도윤: 할머니가 선물 상자를 꺼내 오신 장면은 행복하고 즐거워.","mis":"K3-2-u2-X12"}],"explanation":["강토의 상황과 마음은 장면마다 바뀌어요.","마음이 바뀌면 그 장면의 분위기도 바뀌어요.","그래서 「하나뿐」이라는 말은 알맞지 않아요."],"asset":{"type":"passage","lines":["① 강토는 열 살 생일을 손꼽아 기다렸다.","② 생일 하루 앞, 할아버지가 큰 병이 나셨다.","③ 생일 아침, 엄마는 생일을 잊은 듯했다.","④ 할머니가 오셔서 푸짐한 생일상을 차려 주셨다.","⑤ 할아버지 선물을 열어 보니 녹슨 쇠구슬이었다.","⑥ 툭 떨어뜨리자 구슬이 “뾰로롱!” 소리를 내며 빛났다."],"title":"「신기한 구슬」 간추린 흐름 — 『국어』 74~79쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#4','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'ox','auto','강토와 송이는 같은 집에서 같은 일을 겪었으니, 두 사람의 말과 행동, 마음도 똑같아야 해요.',ARRAY['K3-2-u2-X34']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":3,"kind":"ox","stem":"강토와 송이는 같은 집에서 같은 일을 겪었으니, 두 사람의 말과 행동, 마음도 똑같아야 해요.","answer":"X","reason_options":[{"t":"같은 상황에서도 인물의 성격에 따라 말이나 행동, 마음은 다를 수 있어요.","correct":true},{"t":"같은 일을 겪으면 누구나 똑같이 말하고 행동해요.","mis":"K3-2-u2-X34"}],"mis":"K3-2-u2-X34","explanation":["송이는 색종이 카드를 내밀며 「헤, 미안!」 하고 혀를 쏙 내밀었어요.","강토는 선물이 없어 야속했어요.","같은 상황에서도 인물마다 말·행동·마음이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#5','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',3,'mc','auto','「강토는 터덜터덜 힘없이 집을 나섰다.」에서 꾸며 주는 말 「터덜터덜」을 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X05','K3-2-u2-X13']::text[],false,'{"seq":5,"concept":"K3-2-u2-C6","difficulty":3,"kind":"mc","stem":"「강토는 터덜터덜 힘없이 집을 나섰다.」에서 꾸며 주는 말 「터덜터덜」을 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"힘이 빠진 느낌이 나게 느리고 무겁게 읽는다","correct":true},{"t":"신나게 통통 튀는 목소리로 읽는다","mis":"K3-2-u2-X12"},{"t":"꾸며 주는 말은 빼고 읽는다","mis":"K3-2-u2-X05"},{"t":"가장 큰 소리로 소리친다","mis":"K3-2-u2-X13"}],"explanation":["꾸며 주는 말은 장면의 상황을 강조해요.","「터덜터덜」은 힘없이 걷는 모습이에요.","느낌을 살려 느리고 무겁게 읽으면 장면이 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#6','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',3,'mc','auto','쇠구슬이 갑자기 「뾰로롱!」 소리를 내는 장면이에요. 느낌표가 붙은 「뾰로롱!」은 어떻게 읽으면 좋을까요?',ARRAY['K3-2-u2-X32','K3-2-u2-X12','K3-2-u2-X13']::text[],false,'{"seq":6,"concept":"K3-2-u2-C6","difficulty":3,"kind":"mc","stem":"쇠구슬이 갑자기 「뾰로롱!」 소리를 내는 장면이에요. 느낌표가 붙은 「뾰로롱!」은 어떻게 읽으면 좋을까요?","options":[{"t":"깜짝 놀란 느낌이 나게 맑고 생생하게 읽는다","correct":true},{"t":"느낌표는 신경 쓰지 않고 앞 문장과 똑같이 읽는다","mis":"K3-2-u2-X32"},{"t":"낮고 쓸쓸한 목소리로 천천히 읽는다","mis":"K3-2-u2-X12"},{"t":"들리지 않을 만큼 작게 속삭인다","mis":"K3-2-u2-X13"}],"explanation":["문장 부호는 그 역할에 어울리게 읽어요.","느낌표는 놀람이나 강한 느낌을 나타내요.","맑고 아름다운 소리를 떠올리며 생생하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#7','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'mc','auto','『국어』 81쪽 3번 (3)의 정리 표에서 「인물의 마음」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u2-X36']::text[],false,'{"seq":7,"concept":"K3-2-u2-C5","difficulty":3,"kind":"mc","stem":"『국어』 81쪽 3번 (3)의 정리 표에서 「인물의 마음」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"강토: 갑작스러운 선물에 감격하고 고마운 마음","correct":true},{"t":"할머니: “아이고, 내 정신 좀 봐.”","mis":"K3-2-u2-X36"},{"t":"할아버지께 예상치 못한 선물을 받았다.","mis":"K3-2-u2-X36"},{"t":"할머니가 무릎을 탁 치셨다.","mis":"K3-2-u2-X36"}],"explanation":["따옴표 속 말과 무릎을 친 일은 「말이나 행동」이에요.","선물을 받은 일은 「인물이 처한 상황」이에요.","감격하고 고마운 것은 「인물의 마음」이에요."],"asset":{"type":"passage","lines":["“아이고, 내 정신 좀 봐.”","선물이라는 말에 할머니가 무릎을 탁 치셨다.","(간추림) 할머니는 노란 보자기로 싼 작은 상자를 들고 나오셨다.","“그게 뭐예요?”","(간추림) 할아버지가 며칠 전 강토 생일 선물로 챙겨 두신 것이었다.","“생일 선물이요?”"],"title":"「신기한 구슬」 선물 장면 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#8','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',4,'mc','auto','「신기한 구슬」에서 강토의 마음이 바뀐 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":8,"concept":"K3-2-u2-C5","difficulty":4,"kind":"mc","stem":"「신기한 구슬」에서 강토의 마음이 바뀐 차례로 알맞은 것은 무엇인가요?","options":[{"t":"설렘 → 서운함 → 고마움 → 실망 → 놀라움","correct":true},{"t":"설렘 → 고마움 → 서운함 → 실망 → 놀라움","mis":"K3-2-u2-X15"},{"t":"서운함 → 설렘 → 실망 → 고마움 → 놀라움","mis":"K3-2-u2-X15"},{"t":"설렘 → 서운함 → 실망 → 고마움 → 놀라움","mis":"K3-2-u2-X15"}],"explanation":["생일을 기다리며 설렜다가, 할아버지가 아프시고 생일이 잊혀 서운했어요.","할머니의 생일상에 마음이 풀리고, 녹슨 쇠구슬에 실망했어요.","마지막에 「뾰로롱!」 소리에 놀랐어요 — 마음 따라 분위기도 바뀌어요."],"asset":{"type":"passage","lines":["① 강토는 열 살 생일을 손꼽아 기다렸다.","② 생일 하루 앞, 할아버지가 큰 병이 나셨다.","③ 생일 아침, 엄마는 생일을 잊은 듯했다.","④ 할머니가 오셔서 푸짐한 생일상을 차려 주셨다.","⑤ 할아버지 선물을 열어 보니 녹슨 쇠구슬이었다.","⑥ 툭 떨어뜨리자 구슬이 “뾰로롱!” 소리를 내며 빛났다."],"title":"「신기한 구슬」 간추린 흐름 — 『국어』 74~79쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#9','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',4,'mc','auto','『국어활동』 23쪽 ㉢ 장면에 어울리는 목소리와 그 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X10','K3-2-u2-X15']::text[],false,'{"seq":9,"concept":"K3-2-u2-C6","difficulty":4,"kind":"mc","stem":"『국어활동』 23쪽 ㉢ 장면에 어울리는 목소리와 그 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"반갑다 — 남쪽에 갔던 제비가 다시 날아왔으니까","correct":true},{"t":"울먹이다 — 제비가 남쪽으로 떠났으니까","mis":"K3-2-u2-X12"},{"t":"반갑다 — 밝게 읽기만 하면 다 잘 읽은 거니까","mis":"K3-2-u2-X10"},{"t":"놀라다 — 제비가 박씨를 떨어뜨렸으니까","mis":"K3-2-u2-X15"}],"explanation":["㉢은 봄이 되어 제비가 돌아온 장면이에요.","흥부와 아이들이 반가워 손을 흔들어요.","목소리를 고를 때는 그 장면에서 까닭을 찾아요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L03_challenge#10','kor',3,2,'u2','L03','tb_g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',4,'essay','teacher','「신기한 구슬」에서 강토가 녹슨 쇠구슬을 보고 실망하는 장면을 친구에게 읽어 준다고 생각해요. 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 하나씩 쓰고, 어떤 목소리와 표정으로 읽을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C6","difficulty":4,"kind":"essay","stem":"「신기한 구슬」에서 강토가 녹슨 쇠구슬을 보고 실망하는 장면을 친구에게 읽어 준다고 생각해요. 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 하나씩 쓰고, 어떤 목소리와 표정으로 읽을지 쓰세요.","answer_guide":{"answer":"예: 상황 — 하늘의 선물인 줄 알고 연 상자에 녹슨 쇠구슬이 들어 있었다. 말이나 행동 — “애걔, 이게 뭐야?” 하고 김빠진 듯 어깨가 처졌다. 마음 — 실망하고 할아버지에게 속은 것 같은 마음. 읽는 방법 — 힘이 빠진 목소리로 끝을 늘어지게 읽고, 입을 삐죽이는 표정을 짓는다.","scoring_points":["상황·말이나 행동·마음을 갈라 썼는가","목소리를 장면의 마음에 어울리게 정했는가","표정이나 몸짓을 말이나 행동에 어울리게 정했는가"]},"explanation":["세 칸을 먼저 정리하면 분위기가 보여요.","마음은 목소리에, 말과 행동은 표정과 몸짓에 담아요.","장면에 어울리면 읽는 방법은 친구와 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#1','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',1,'mc','auto','「박에스더」에서 에스더는 어디에서 누구를 보며 의사의 꿈을 키웠나요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C7","difficulty":1,"kind":"mc","stem":"「박에스더」에서 에스더는 어디에서 누구를 보며 의사의 꿈을 키웠나요?","options":[{"t":"보구녀관에서 환자들을 돌보는 로제타 선생님을 보며","correct":true},{"t":"외국의 큰 병원에서 남자 의사를 보며","mis":"K3-2-u2-X15"},{"t":"학교에서 위생을 가르치는 선생님을 보며","mis":"K3-2-u2-X15"},{"t":"콜레라에 걸린 이웃을 보며","mis":"K3-2-u2-X15"}],"explanation":["글 맨 앞 장면을 떠올려요.","보구녀관은 우리나라 최초의 여성 병원이에요.","로제타 선생님이 환자를 돌보는 모습을 보며 꿈을 키웠어요."],"asset":{"type":"passage","lines":["① 보구녀관에서 로제타 선생님을 보며 의사의 꿈을 키웠다.","② 밤낮으로 공부해 마침내 의사가 되었다.","③ 당나귀를 타고 왕진 가방을 들고 환자를 찾아 나섰다.","④ 1902년 콜레라 — 모두 피하는 환자를 찾아가 치료했다.","⑤ 고양이 그림 대신 깨끗한 물 마시기·손 씻기를 가르쳤다.","⑥ 에스더가 가는 곳은 금방 병원이 되었고 학교가 되었다."],"title":"「박에스더」 간추린 흐름 — 『국어』 82~85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#2','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',1,'sa','auto','묻고 답하기 놀이예요. 「박에스더는 한겨울에 무엇을 타고 환자를 보러 다녔나요?」에 답하세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u2-C7","difficulty":1,"kind":"sa","stem":"묻고 답하기 놀이예요. 「박에스더는 한겨울에 무엇을 타고 환자를 보러 다녔나요?」에 답하세요.","answer":["당나귀","당나귀를 타고","당나귀를 탔어요"],"explanation":["『국어』 86쪽에서 친구가 만든 질문이에요.","에스더는 당나귀를 타고 왕진 가방을 들고 다녔어요.","방울 소리 「딸랑딸랑」도 당나귀 방울 소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#3','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C8',1,'mc','auto','『국어』 86쪽 낱말 알기예요. 「다짐하다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":3,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 86쪽 낱말 알기예요. 「다짐하다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"결심하다","correct":true},{"t":"단결하다","mis":"K3-2-u2-X16"},{"t":"답장하다","mis":"K3-2-u2-X16"}],"explanation":["낱말이 들어간 줄에 넣어 보아요.","「건강하게 해 주겠다고 결심한 마음」 — 뜻이 통해요.","「다짐하다」는 마음을 굳게 정하는 거예요."],"asset":{"type":"passage","lines":["에스더는 사람들을 건강하게 해 주겠다고 다짐한 마음을","되새기며 쉬지 않고 치료했다."],"title":"『국어』 86쪽 낱말 알기","hi":["다짐한","되새기며","치료했다"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#4','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C8',1,'mc','auto','같은 문장에서 「되새기다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":4,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"같은 문장에서 「되새기다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"곱씹다","correct":true},{"t":"벗어나다","mis":"K3-2-u2-X16"},{"t":"말하다","mis":"K3-2-u2-X16"}],"explanation":["「다짐한 마음을 되새기며」를 다시 읽어요.","지난 마음을 거듭 떠올린다는 뜻이에요.","「곱씹다」를 넣어도 뜻이 통해요."],"asset":{"type":"passage","lines":["에스더는 사람들을 건강하게 해 주겠다고 다짐한 마음을","되새기며 쉬지 않고 치료했다."],"title":"『국어』 86쪽 낱말 알기","hi":["다짐한","되새기며","치료했다"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#5','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C8',2,'mc','auto','같은 문장에서 「치료하다」와 뜻이 비슷한 표현은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":5,"concept":"K3-2-u2-C8","difficulty":2,"kind":"mc","stem":"같은 문장에서 「치료하다」와 뜻이 비슷한 표현은 무엇인가요?","options":[{"t":"낫게 하다","correct":true},{"t":"활용하다","mis":"K3-2-u2-X16"},{"t":"풀어내다","mis":"K3-2-u2-X16"}],"explanation":["에스더는 의사예요.","아픈 사람을 「낫게 하는」 일을 했어요.","「쉬지 않고 낫게 했다」로 바꾸어도 뜻이 통해요."],"asset":{"type":"passage","lines":["에스더는 사람들을 건강하게 해 주겠다고 다짐한 마음을","되새기며 쉬지 않고 치료했다."],"title":"『국어』 86쪽 낱말 알기","hi":["다짐한","되새기며","치료했다"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#6','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','묻고 답하기 놀이 ①의 질문이에요. 「사람들이 집에 고양이 그림을 걸어 놓은 까닭은 무엇인가요?」 알맞은 답은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":6,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"묻고 답하기 놀이 ①의 질문이에요. 「사람들이 집에 고양이 그림을 걸어 놓은 까닭은 무엇인가요?」 알맞은 답은 무엇인가요?","options":[{"t":"고양이 그림을 걸어 놓으면 쥐가 무서운 병을 집으로 못 가지고 올 거라고 생각했기 때문","correct":true},{"t":"고양이를 기르는 집이 많았기 때문","mis":"K3-2-u2-X08"},{"t":"에스더가 고양이 그림을 걸라고 가르쳤기 때문","mis":"K3-2-u2-X15"},{"t":"고양이 그림이 집을 예쁘게 꾸며 주기 때문","mis":"K3-2-u2-X08"}],"explanation":["「콜레라는 쥐가 옮기는 병이래요.」 다음 말을 다시 읽어요.","고양이가 쥐를 잡으니 그림이 병을 막아 준다고 믿었어요.","에스더는 이런 믿음을 「미신」이라며 마음 아파했어요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#7','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','『국어』 87쪽 (1) 장면 정리에서 「인물이 처한 상황」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u2-X36']::text[],false,'{"seq":7,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"『국어』 87쪽 (1) 장면 정리에서 「인물이 처한 상황」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"많은 사람이 콜레라에 걸렸다.","correct":true},{"t":"박에스더: “고양이 그림은 왜 걸어 놓았나요?”","mis":"K3-2-u2-X36"},{"t":"사람들: 병에 걸릴까 봐 두려운 마음","mis":"K3-2-u2-X36"},{"t":"박에스더: 미신으로 건강을 지키려는 사람들이 안타까운 마음","mis":"K3-2-u2-X36"}],"explanation":["인물이 겪고 있는 일이 「인물이 처한 상황」이에요.","에스더의 물음은 「말이나 행동」, 두렵고 안타까운 것은 「마음」이에요.","세 칸을 가르면 장면이 또렷이 떠올라요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#8','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','같은 장면의 분위기로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":8,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"같은 장면의 분위기로 알맞은 것은 무엇인가요?","options":[{"t":"답답하고 혼란스럽다","correct":true},{"t":"행복하고 즐겁다","mis":"K3-2-u2-X12"},{"t":"신비롭고 환상적이다","mis":"K3-2-u2-X12"},{"t":"편안하고 느긋하다","mis":"K3-2-u2-X12"}],"explanation":["무서운 병이 돌고 사람들은 두려워해요.","병을 막는다며 고양이 그림을 거는 사람들 때문에 에스더는 안타까워요.","그래서 답답하고 혼란스러운 분위기예요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#9','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C9',2,'ox','auto','『국어』 89쪽에서 자신의 목표를 이루려고 노력한 인물을 조사할 때는 이순신이나 손기정처럼 이름난 위인만 골라야 해요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":9,"concept":"K3-2-u2-C9","difficulty":2,"kind":"ox","stem":"『국어』 89쪽에서 자신의 목표를 이루려고 노력한 인물을 조사할 때는 이순신이나 손기정처럼 이름난 위인만 골라야 해요.","answer":"X","reason_options":[{"t":"우리 반 친구나 이웃, 소방관·환경미화원처럼 둘레의 사람에게서도 배울 점을 찾을 수 있어요.","correct":true},{"t":"배울 점은 이름난 위인에게만 있어요.","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["예시 답에 「우리 반 유현민」을 조사한 친구가 있어요.","위인에게만 배울 점이 있는 것이 아니에요.","친구나 이웃 가운데 노력하는 사람을 찾아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_basic#10','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',3,'mc','auto','「박에스더」로 묻고 답하기 놀이를 해요. 글의 중요한 내용을 묻는 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X33']::text[],false,'{"seq":10,"concept":"K3-2-u2-C7","difficulty":3,"kind":"mc","stem":"「박에스더」로 묻고 답하기 놀이를 해요. 글의 중요한 내용을 묻는 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"에스더가 고양이 그림 대신 사람들에게 가르친 것은 무엇인가요?","correct":true},{"t":"에스더가 탄 당나귀의 이름은 무엇이었을까요?","mis":"K3-2-u2-X33"},{"t":"에스더는 아침에 몇 시에 일어났을까요?","mis":"K3-2-u2-X33"},{"t":"「딸랑딸랑」은 글에 몇 번 나오나요?","mis":"K3-2-u2-X33"}],"explanation":["질문은 글의 주요 내용과 장면을 중심으로 만들어요.","답이 글에 있어야 친구와 함께 확인할 수 있어요.","위생과 건강 상식을 가르친 일은 글의 중요한 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#1','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',2,'mc','auto','에스더가 콜레라를 막으려고 사람들에게 가르친 것이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"에스더가 콜레라를 막으려고 사람들에게 가르친 것이 아닌 것은 무엇인가요?","options":[{"t":"집에 고양이 그림을 걸어 둔다","correct":true},{"t":"깨끗한 물을 마신다","mis":"K3-2-u2-X15"},{"t":"손을 자주 씻는다","mis":"K3-2-u2-X15"},{"t":"오염된 물과 음식을 조심한다","mis":"K3-2-u2-X15"}],"explanation":["「고양이 그림은 콜레라를 막아 주지 못해요.」라고 했어요.","위생에 신경 쓰라며 깨끗한 물, 손 씻기를 가르쳤어요.","오염된 물과 음식이 병균을 옮길 수 있다고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#2','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C8',2,'blank','auto','「아직도 이런 (     )(으)로 건강을 지키려는 사람이 많다는 사실에 에스더는 마음이 아팠다.」 빈칸에 들어갈, ‘과학적이지 않다고 여겨지는 믿음’을 뜻하는 낱말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":2,"concept":"K3-2-u2-C8","difficulty":2,"kind":"blank","stem":"「아직도 이런 (     )(으)로 건강을 지키려는 사람이 많다는 사실에 에스더는 마음이 아팠다.」 빈칸에 들어갈, ‘과학적이지 않다고 여겨지는 믿음’을 뜻하는 낱말은 무엇인가요?","options":[{"t":"미신","correct":true},{"t":"위생","mis":"K3-2-u2-X16"},{"t":"왕진","mis":"K3-2-u2-X16"},{"t":"상식","mis":"K3-2-u2-X16"}],"explanation":["뜻풀이를 보고 문장에 넣어 보아요.","고양이 그림이 병을 막는다는 믿음은 과학적이지 않아요.","그런 믿음을 「미신」이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#3','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',3,'mc','auto','「봄바람이 살랑살랑 볼을 간지럽힐 때부터 함박눈이 소복소복 발밑에 쌓일 때까지」라는 표현으로 떠올릴 수 있는 장면은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":3,"concept":"K3-2-u2-C7","difficulty":3,"kind":"mc","stem":"「봄바람이 살랑살랑 볼을 간지럽힐 때부터 함박눈이 소복소복 발밑에 쌓일 때까지」라는 표현으로 떠올릴 수 있는 장면은 무엇인가요?","options":[{"t":"에스더가 봄부터 겨울까지 한 해 내내 쉬지 않고 환자를 찾아다니는 장면","correct":true},{"t":"에스더가 봄에는 꽃구경을, 겨울에는 눈싸움을 하는 장면","mis":"K3-2-u2-X08"},{"t":"하루 동안 날씨가 갑자기 여러 번 바뀌는 장면","mis":"K3-2-u2-X15"},{"t":"에스더가 추위를 피해 집에 머무는 장면","mis":"K3-2-u2-X15"}],"explanation":["봄바람과 함박눈은 계절을 떠올리게 해요.","봄부터 겨울까지, 땅끝에서 땅끝까지 다녔다는 뜻이에요.","장면을 떠올리면 에스더의 노력이 더 크게 느껴져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#4','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',3,'mc','auto','「저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.」를 장면을 떠올리며 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X13','K3-2-u2-X02']::text[],false,'{"seq":4,"concept":"K3-2-u2-C7","difficulty":3,"kind":"mc","stem":"「저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.」를 장면을 떠올리며 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두려움을 누르고 다짐하는 마음이 드러나게 차분하면서도 힘 있게 읽는다","correct":true},{"t":"신나고 장난스러운 목소리로 빠르게 읽는다","mis":"K3-2-u2-X12"},{"t":"무서운 마음만 드러나게 들리지 않을 만큼 작게 읽는다","mis":"K3-2-u2-X13"},{"t":"가장 크게 소리쳐 읽는다","mis":"K3-2-u2-X02"}],"explanation":["에스더는 두렵지만 환자를 치료하는 것이 자기 일이라고 말해요.","두려움과 굳은 마음이 함께 드러나야 해요.","마음이 드러나는 목소리로, 뜻은 또렷하게 읽어요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#5','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',3,'mc','auto','「박에스더」를 읽고 든 생각이나 느낌을 글의 내용과 이어서 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X10','K3-2-u2-X08']::text[],false,'{"seq":5,"concept":"K3-2-u2-C9","difficulty":3,"kind":"mc","stem":"「박에스더」를 읽고 든 생각이나 느낌을 글의 내용과 이어서 말한 친구는 누구인가요?","options":[{"t":"은우: 병을 무서워하지 않고 환자를 돌보는 모습이 존경스러웠어.","correct":true},{"t":"시아: 그냥 그랬어. 별 느낌 없었어.","mis":"K3-2-u2-X10"},{"t":"태오: 에스더가 콜레라에 걸려 오래 쉬었다는 게 슬펐어.","mis":"K3-2-u2-X08"},{"t":"라온: 다른 친구가 존경스럽다고 했으니 나도 그래.","mis":"K3-2-u2-X10"}],"explanation":["생각이나 느낌은 글의 어느 부분 때문인지 함께 말해요.","에스더가 콜레라에 걸렸다는 내용은 글에 없어요.","남의 말을 따르지 말고 내 마음이 움직인 곳을 말해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"병을 무서워하지 않고 환자를 돌보는 모습이 존경스러웠어."},{"who":"친구 2","text":"위생 교육을 받지 못한 사람들이 안타깝게 느껴졌어."},{"who":"친구 3","text":"로제타 선생님이 어떤 분인지 더 알고 싶어졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#6','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',3,'ox','auto','「박에스더」를 읽고 든 느낌은 「존경스럽다」 하나가 정답이고, 「안타깝다」나 「궁금하다」는 틀린 느낌이에요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":6,"concept":"K3-2-u2-C9","difficulty":3,"kind":"ox","stem":"「박에스더」를 읽고 든 느낌은 「존경스럽다」 하나가 정답이고, 「안타깝다」나 「궁금하다」는 틀린 느낌이에요.","answer":"X","reason_options":[{"t":"마음이 움직인 곳이 서로 달라 존경스러움·안타까움·궁금함처럼 느낌이 달라도 돼요.","correct":true},{"t":"글을 읽고 든 느낌에는 정답이 하나 있어요.","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["『국어』 88쪽 친구들의 느낌은 서로 달라요.","위생 교육을 못 받은 사람들이 안타까웠다는 친구도 있어요.","로제타 선생님이 궁금해졌다는 친구도 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"병을 무서워하지 않고 환자를 돌보는 모습이 존경스러웠어."},{"who":"친구 2","text":"위생 교육을 받지 못한 사람들이 안타깝게 느껴졌어."},{"who":"친구 3","text":"로제타 선생님이 어떤 분인지 더 알고 싶어졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#7','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',3,'match','auto','『국어』 89쪽 인물 모으기 활동이에요. 인물과 그 인물이 한 노력을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C9","difficulty":3,"kind":"match","stem":"『국어』 89쪽 인물 모으기 활동이에요. 인물과 그 인물이 한 노력을 알맞게 이으세요.","pairs":[{"l":"윤희순","r":"일제 강점기에 의병을 도움."},{"l":"이순신","r":"불리한 상황에서도 승리를 위해 노력함."},{"l":"손기정","r":"마라톤 실력을 키워 금메달을 땀."},{"l":"소방관 ○○○","r":"위험한 곳에서도 사람들을 살리려고 노력함."}],"mis":"K3-2-u2-X15","explanation":["모둠 친구들이 조사한 인물을 모은 활동이에요.","인물마다 목표를 이루려고 한 노력이 달라요.","이름난 위인뿐 아니라 소방관·환경미화원도 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#8','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',4,'mc','auto','「박에스더」의 장면을 일어난 차례로 바르게 놓은 것은 무엇인가요? ㉮ 당나귀를 타고 왕진을 다녔다. ㉯ 로제타 선생님을 보며 꿈을 키웠다. ㉰ 고양이 그림을 보고 위생을 가르쳤다. ㉱ 밤낮으로 공부해 의사가 되었다.',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":8,"concept":"K3-2-u2-C7","difficulty":4,"kind":"mc","stem":"「박에스더」의 장면을 일어난 차례로 바르게 놓은 것은 무엇인가요? ㉮ 당나귀를 타고 왕진을 다녔다. ㉯ 로제타 선생님을 보며 꿈을 키웠다. ㉰ 고양이 그림을 보고 위생을 가르쳤다. ㉱ 밤낮으로 공부해 의사가 되었다.","options":[{"t":"㉯ → ㉱ → ㉮ → ㉰","correct":true},{"t":"㉯ → ㉮ → ㉱ → ㉰","mis":"K3-2-u2-X15"},{"t":"㉱ → ㉯ → ㉮ → ㉰","mis":"K3-2-u2-X15"},{"t":"㉯ → ㉱ → ㉰ → ㉮","mis":"K3-2-u2-X15"}],"explanation":["꿈을 키우고, 공부해 의사가 된 다음에 왕진을 다녀요.","왕진을 다니다 콜레라가 돌 때 고양이 그림을 보았어요.","장면의 차례를 알면 흐름을 떠올리며 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#9','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',4,'essay','teacher','『국어』 88쪽 「자신과 관련짓기」예요. 자신의 꿈이나 목표를 이루려고 노력해 본 경험을 쓰고, 그때 든 기분과 「박에스더」에서 닮고 싶은 점을 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C9","difficulty":4,"kind":"essay","stem":"『국어』 88쪽 「자신과 관련짓기」예요. 자신의 꿈이나 목표를 이루려고 노력해 본 경험을 쓰고, 그때 든 기분과 「박에스더」에서 닮고 싶은 점을 함께 쓰세요.","answer_guide":{"answer":"예: 줄넘기 이단 뛰기를 하려고 날마다 저녁에 연습했다. 줄에 자꾸 걸려서 속상했지만 처음 성공했을 때 아주 뿌듯했다. 에스더가 두려워도 환자를 찾아간 것처럼 나도 어려워도 포기하지 않는 마음을 닮고 싶다.","scoring_points":["꿈이나 목표를 이루려고 노력한 경험을 썼는가","노력하는 동안 든 기분을 썼는가","「박에스더」에서 닮고 싶은 점을 글의 내용과 이어 썼는가"]},"explanation":["작아 보이는 일도 꿈이나 목표가 될 수 있어요.","노력할 때의 기분을 떠올리면 인물의 마음도 더 잘 보여요.","닮고 싶은 점은 글 속 장면과 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L05_challenge#10','kor',3,2,'u2','L05','tb_g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',4,'essay','teacher','「박에스더」에서 분위기가 잘 느껴지는 장면을 하나 골라 고른 까닭을 쓰고, 그 장면에서 인물의 마음을 짐작할 수 있는 부분과 어떤 목소리·표정으로 읽을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C7","difficulty":4,"kind":"essay","stem":"「박에스더」에서 분위기가 잘 느껴지는 장면을 하나 골라 고른 까닭을 쓰고, 그 장면에서 인물의 마음을 짐작할 수 있는 부분과 어떤 목소리·표정으로 읽을지 쓰세요.","answer_guide":{"answer":"예: 마을 사람들이 반갑게 손을 흔들어 에스더를 맞이하는 장면. 까닭 — 사람들이 기다리던 의사가 와서 기쁘고 따뜻한 분위기가 잘 느껴진다. 마음을 짐작할 부분 — “정말 반가워요, 선생님!” 읽는 방법 — 밝고 반가운 목소리로, 손을 흔드는 몸짓과 웃는 표정으로 읽는다.","scoring_points":["분위기가 잘 느껴지는 장면을 골라 까닭을 썼는가","인물의 마음을 짐작할 수 있는 부분을 글에서 찾아 썼는가","목소리·표정(몸짓)을 장면의 분위기에 어울리게 정했는가"]},"explanation":["장면 고르기 → 마음 찾기 → 읽기 계획 차례로 해요.","마음은 인물의 말이나 행동에서 찾아요.","분위기에 어울리는 목소리와 표정을 정하면 장면이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#1','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'mc','auto','양궁·배드민턴·태권도·탁구 같은 운동 종목을 글자 대신 그림 기호(픽토그램)로 나타내면 좋은 점은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X19','K3-2-u2-X07']::text[],false,'{"seq":1,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"양궁·배드민턴·태권도·탁구 같은 운동 종목을 글자 대신 그림 기호(픽토그램)로 나타내면 좋은 점은 무엇인가요?","options":[{"t":"글을 읽지 않아도 무엇을 나타내는지 한눈에 알 수 있다","correct":true},{"t":"그림이 많아져 보기 좋게 꾸며진다","mis":"K3-2-u2-X18"},{"t":"운동 규칙을 자세히 알 수 있다","mis":"K3-2-u2-X19"},{"t":"글자를 쓰지 않아도 되어 만들기 편하다","mis":"K3-2-u2-X07"}],"explanation":["픽토그램은 뜻하는 것의 모양을 그림으로 나타낸 기호예요.","배우지 않아도, 다른 나라 사람도 바로 알아볼 수 있어요.","자세한 규칙은 그림만으로 알기 어려워 글이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#2','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'mc','auto','「이름처럼 쓰는 숫자」에서 자동차마다 번호판이 다른 까닭은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":2,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 자동차마다 번호판이 다른 까닭은 무엇인가요?","options":[{"t":"자동차 주인이 누구인지 알기 위해","correct":true},{"t":"자동차를 예쁘게 꾸미기 위해","mis":"K3-2-u2-X08"},{"t":"자동차가 어디로 가는지 알기 위해","mis":"K3-2-u2-X15"},{"t":"자동차가 얼마나 빠른지 알기 위해","mis":"K3-2-u2-X08"}],"explanation":["『국어』 92쪽 2번 (1)의 물음이에요.","자동차 주인이 누구인지 알기 위해 차마다 다른 번호판을 달아요.","어디로 가는지 알려 주는 것은 버스 번호예요."],"asset":{"type":"passage","lines":["사람이나 물건이 많아지면 누가 누군지 헷갈릴 수 있습니다.","이럴 때 번호를 붙이면 쉽게 구별할 수 있어서 더 편리합니다.","(간추림) 자동차 번호판 — 자동차 주인이 누구인지 알려고 차마다 다르다.","(간추림) 버스 번호 — 출발지와 도착지에 따라 번호가 달라진다.","(간추림) 유선 전화번호 — 맨 앞자리는 지역 번호다.","(간추림) 주민 등록 번호 — 태어난 연도·날짜, 남녀가 담겨 있다."],"title":"「이름처럼 쓰는 숫자」 — 『국어』 90~91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#3','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'sa','auto','「이름처럼 쓰는 숫자」에서 유선 전화번호의 맨 앞자리는 무엇을 뜻하나요?','{}'::text[],false,'{"seq":3,"concept":"K3-2-u2-C10","difficulty":1,"kind":"sa","stem":"「이름처럼 쓰는 숫자」에서 유선 전화번호의 맨 앞자리는 무엇을 뜻하나요?","answer":["지역 번호","지역번호","지역 번호를 뜻합니다"],"explanation":["『국어』 92쪽 2번 (2)의 물음이에요.","유선 전화번호의 맨 앞자리는 지역 번호예요.","휴대 전화 번호는 사는 지역과 상관이 없어요."],"asset":{"type":"passage","lines":["유선 전화번호의 맨 앞자리는 지역 번호입니다.","지역에 따라 모두 번호가 다릅니다.","[그림] 지역마다 다른 색을 칠한 우리나라 지도","[말풍선] 서울 빼고 모두 세 자리 번호예요.","[말풍선] 휴대 전화 번호는 사는 지역과 상관이 없어."],"title":"「지역마다 다른 전화번호」 — 『국어』 91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#4','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'mc','auto','「이름처럼 쓰는 숫자」에서 주민 등록 번호로 알 수 있는 정보가 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":4,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 주민 등록 번호로 알 수 있는 정보가 아닌 것은 무엇인가요?","options":[{"t":"사는 동네","correct":true},{"t":"태어난 연도","mis":"K3-2-u2-X15"},{"t":"태어난 날짜","mis":"K3-2-u2-X15"},{"t":"남자인지 여자인지","mis":"K3-2-u2-X15"}],"explanation":["『국어』 92쪽 2번 (3)의 물음이에요.","태어난 연도와 날짜, 남자인지 여자인지가 담겨 있어요.","사는 동네는 글에 나오지 않아요."],"asset":{"type":"passage","lines":["사람이나 물건이 많아지면 누가 누군지 헷갈릴 수 있습니다.","이럴 때 번호를 붙이면 쉽게 구별할 수 있어서 더 편리합니다.","(간추림) 자동차 번호판 — 자동차 주인이 누구인지 알려고 차마다 다르다.","(간추림) 버스 번호 — 출발지와 도착지에 따라 번호가 달라진다.","(간추림) 유선 전화번호 — 맨 앞자리는 지역 번호다.","(간추림) 주민 등록 번호 — 태어난 연도·날짜, 남녀가 담겨 있다."],"title":"「이름처럼 쓰는 숫자」 — 『국어』 90~91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#5','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','『국어』 92쪽 글에서 서울 시내버스 번호의 첫 번째 번호와 두 번째 번호는 무엇을 가리키나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":5,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"『국어』 92쪽 글에서 서울 시내버스 번호의 첫 번째 번호와 두 번째 번호는 무엇을 가리키나요?","options":[{"t":"첫 번째는 출발지, 두 번째는 도착지","correct":true},{"t":"첫 번째는 도착지, 두 번째는 출발지","mis":"K3-2-u2-X15"},{"t":"첫 번째는 버스 색, 두 번째는 버스 크기","mis":"K3-2-u2-X08"},{"t":"첫 번째는 운전기사, 두 번째는 승객 수","mis":"K3-2-u2-X08"}],"explanation":["글 셋째·넷째 줄을 다시 읽어요.","첫 번째 번호는 출발지, 두 번째 번호는 도착지예요.","그래서 출발지와 도착지에 따라 번호가 달라져요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#6','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','그림 아래 말 「1번 지역에서 출발해서 2번 지역에 도착하는 버스예요.」를 지도와 이어 보면 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X20','K3-2-u2-X08']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"그림 아래 말 「1번 지역에서 출발해서 2번 지역에 도착하는 버스예요.」를 지도와 이어 보면 알 수 있는 것은 무엇인가요?","options":[{"t":"1211번 버스가 지도의 1번 지역에서 2번 지역으로 간다는 것","correct":true},{"t":"1211번 버스가 열두 번째로 만든 버스라는 것","mis":"K3-2-u2-X19"},{"t":"지도에 칠한 색은 아무 뜻이 없다는 것","mis":"K3-2-u2-X20"},{"t":"버스는 모두 초록색이라는 것","mis":"K3-2-u2-X08"}],"explanation":["버스 번호 앞 두 자리 「12」는 1번 지역 출발, 2번 지역 도착이에요.","지도에서 1번과 2번 지역의 자리를 찾아요.","글과 그림을 이어 보면 1211의 뜻을 알 수 있어요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#7','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'blank','auto','『국어』 92쪽 정리예요. 「글과 그림을 활용하여 설명할 때, 글은 중요한 내용을 (     ) 제시해요. 그림은 중요한 내용을 한눈에 파악할 수 있도록 나타내요.」',ARRAY['K3-2-u2-X19','K3-2-u2-X23']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":2,"kind":"blank","stem":"『국어』 92쪽 정리예요. 「글과 그림을 활용하여 설명할 때, 글은 중요한 내용을 (     ) 제시해요. 그림은 중요한 내용을 한눈에 파악할 수 있도록 나타내요.」","options":[{"t":"간략하게","correct":true},{"t":"되도록 길게","mis":"K3-2-u2-X19"},{"t":"알록달록하게","mis":"K3-2-u2-X23"},{"t":"그림 없이","mis":"K3-2-u2-X19"}],"explanation":["글은 그림만으로 알 수 없는 내용을 짧게 설명해요.","그림은 글로 설명하기 어려운 것을 한눈에 보여 줘요.","둘이 할 일을 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#8','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',2,'match','auto','『국어』 93쪽 4번이에요. 「이름처럼 쓰는 숫자」의 그림 표현과 그렇게 나타낸 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u2-C11","difficulty":2,"kind":"match","stem":"『국어』 93쪽 4번이에요. 「이름처럼 쓰는 숫자」의 그림 표현과 그렇게 나타낸 까닭을 알맞게 이으세요.","pairs":[{"l":"지도에서 지역마다 다른 색을 칠함","r":"서로 다른 지역임을 구별하려고"},{"l":"승용차 그림의 번호판을 크게 그림","r":"중요한 정보를 눈에 잘 띄게 하려고"},{"l":"버스를 실제 버스 모양으로 그림","r":"무엇을 설명하는지 바로 알아보게 하려고"}],"mis":"K3-2-u2-X20","explanation":["색은 서로 다른 것을 구별해 보여 줘요.","크기는 중요한 것을 눈에 띄게 해요.","모양은 무엇인지, 어느 쪽인지 바로 알게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#9','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',2,'ox','auto','승용차는 버스보다 작은데 그림에서 번호판을 크게 그렸으니 잘못 그린 그림이에요.',ARRAY['K3-2-u2-X20']::text[],false,'{"seq":9,"concept":"K3-2-u2-C11","difficulty":2,"kind":"ox","stem":"승용차는 버스보다 작은데 그림에서 번호판을 크게 그렸으니 잘못 그린 그림이에요.","answer":"X","reason_options":[{"t":"번호판이 설명하려는 중요한 내용이라 눈에 잘 띄게 일부러 크게 그렸어요.","correct":true},{"t":"그림 속 크기는 언제나 실제 크기와 똑같아야 해요.","mis":"K3-2-u2-X20"}],"mis":"K3-2-u2-X20","explanation":["『국어』 93쪽 「크기」 칸의 그림 표현이에요.","번호판을 보여 주려고 크게 그렸어요.","크기를 키우면 중요한 정보가 눈에 띄어요."],"asset":{"type":"passage","lines":["제목: 자동차마다 다른 자동차 번호판 (「자동차 번호판」만 다른 색)","자동차 주인이 누구인지 알기 위해 자동차마다 다른 번호판을 답니다.","[그림] 승용차 — 버스보다 작은 차인데 번호판 숫자는 크게 그림"],"title":"「이름처럼 쓰는 숫자」 첫 칸 — 『국어』 90쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_basic#10','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',3,'mc','auto','『국어』 92쪽 3번 (1)이에요. 글과 그림에서 가장 눈에 띄는 부분과 그 까닭을 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X24']::text[],false,'{"seq":10,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어』 92쪽 3번 (1)이에요. 글과 그림에서 가장 눈에 띄는 부분과 그 까닭을 알맞게 말한 것은 무엇인가요?","options":[{"t":"제목의 「버스 번호」와 버스를 똑같이 초록색으로 나타내어 무엇을 설명하는지 이어 보여 주니까","correct":true},{"t":"글의 첫 줄 — 맨 처음에 쓰여 있으니까","mis":"K3-2-u2-X18"},{"t":"지도 — 그림이 클수록 언제나 더 좋은 자료니까","mis":"K3-2-u2-X24"},{"t":"버스 — 예쁘게 꾸미려고 색칠했으니까","mis":"K3-2-u2-X18"}],"explanation":["같은 색을 쓰면 글과 그림이 같은 것을 말한다는 것을 알 수 있어요.","다양한 색과 숫자를 쓴 지도도 눈에 띄어요.","눈에 띄는 까닭은 꾸밈이 아니라 전하려는 내용에서 찾아요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#1','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',2,'mc','auto','「지역마다 다른 전화번호」에서 휴대 전화 번호에 대해 말한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":1,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"「지역마다 다른 전화번호」에서 휴대 전화 번호에 대해 말한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"사는 지역과 상관이 없다","correct":true},{"t":"맨 앞자리가 지역 번호다","mis":"K3-2-u2-X15"},{"t":"서울만 두 자리이고 나머지는 세 자리다","mis":"K3-2-u2-X15"},{"t":"주민 등록 번호와 똑같다","mis":"K3-2-u2-X08"}],"explanation":["지역 번호가 붙는 것은 유선 전화번호예요.","말풍선에 「휴대 전화 번호는 사는 지역과 상관이 없어.」라고 했어요.","「서울 빼고 모두 세 자리」도 유선 전화 지역 번호 이야기예요."],"asset":{"type":"passage","lines":["유선 전화번호의 맨 앞자리는 지역 번호입니다.","지역에 따라 모두 번호가 다릅니다.","[그림] 지역마다 다른 색을 칠한 우리나라 지도","[말풍선] 서울 빼고 모두 세 자리 번호예요.","[말풍선] 휴대 전화 번호는 사는 지역과 상관이 없어."],"title":"「지역마다 다른 전화번호」 — 『국어』 91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#2','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',2,'blank','auto','『국어』 93쪽 「크기」 칸이에요. 「(     )의 글자를 다른 글자보다 크게 표현했다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X22','K3-2-u2-X20']::text[],false,'{"seq":2,"concept":"K3-2-u2-C11","difficulty":2,"kind":"blank","stem":"『국어』 93쪽 「크기」 칸이에요. 「(     )의 글자를 다른 글자보다 크게 표현했다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"제목","correct":true},{"t":"설명","mis":"K3-2-u2-X22"},{"t":"번호판","mis":"K3-2-u2-X20"},{"t":"그림 아래 말","mis":"K3-2-u2-X22"}],"explanation":["글에서 가장 먼저 눈에 들어와야 할 것은 제목이에요.","제목 글자를 크게 하면 무엇을 설명하는지 바로 알아요.","글은 크기·색·글자 모양으로 중요한 곳을 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#3','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'mc','auto','「다니는 곳에 따라 다른 버스 번호」에서 그림을 보아야만 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":3,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"「다니는 곳에 따라 다른 버스 번호」에서 그림을 보아야만 알 수 있는 것은 무엇인가요?","options":[{"t":"1번 지역과 2번 지역이 지도에서 어디쯤 있는지","correct":true},{"t":"첫 번째 번호가 출발지를 가리킨다는 것","mis":"K3-2-u2-X19"},{"t":"버스는 출발지와 도착지에 따라 번호판이 달라진다는 것","mis":"K3-2-u2-X19"},{"t":"서울 시내버스를 설명한다는 것","mis":"K3-2-u2-X19"}],"explanation":["번호가 무엇을 가리키는지는 글에 있어요.","지역의 자리는 글에 없고 지도 그림에만 있어요.","글에만 있는 것, 그림에만 있는 것을 가려 보면 둘 다 필요한 까닭을 알아요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#4','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'mc','auto','「지역마다 다른 전화번호」 그림 지도에서 지역마다 다른 색을 칠하고 번호를 적은 까닭은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X23','K3-2-u2-X20']::text[],false,'{"seq":4,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"「지역마다 다른 전화번호」 그림 지도에서 지역마다 다른 색을 칠하고 번호를 적은 까닭은 무엇인가요?","options":[{"t":"지역마다 맨 앞자리 번호가 다르다는 것을 한눈에 구별해 보여 주려고","correct":true},{"t":"지도를 알록달록하게 꾸미려고","mis":"K3-2-u2-X18"},{"t":"색이 많을수록 좋은 자료라서","mis":"K3-2-u2-X23"},{"t":"지역의 넓이를 재어 보라고","mis":"K3-2-u2-X20"}],"explanation":["『국어』 93쪽 「모양」 칸 — 지도를 사용한 까닭이에요.","색이 다르면 지역끼리 구별돼요.","글로만 쓰면 어느 지역이 어디인지 한눈에 알기 어려워요."],"asset":{"type":"passage","lines":["유선 전화번호의 맨 앞자리는 지역 번호입니다.","지역에 따라 모두 번호가 다릅니다.","[그림] 지역마다 다른 색을 칠한 우리나라 지도","[말풍선] 서울 빼고 모두 세 자리 번호예요.","[말풍선] 휴대 전화 번호는 사는 지역과 상관이 없어."],"title":"「지역마다 다른 전화번호」 — 『국어』 91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#5','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',3,'mc','auto','『국어활동』 24쪽 더 알아보기 「색깔에 따라 느낌이 달라질 수 있어요」예요. 보통 따뜻한 느낌을 주는 색끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u2-X31']::text[],false,'{"seq":5,"concept":"K3-2-u2-C11","difficulty":3,"kind":"mc","stem":"『국어활동』 24쪽 더 알아보기 「색깔에 따라 느낌이 달라질 수 있어요」예요. 보통 따뜻한 느낌을 주는 색끼리 묶은 것은 무엇인가요?","options":[{"t":"빨강, 노랑","correct":true},{"t":"파랑, 청록","mis":"K3-2-u2-X31"},{"t":"파랑, 노랑","mis":"K3-2-u2-X31"},{"t":"청록, 빨강","mis":"K3-2-u2-X31"}],"explanation":["글자와 그림의 색깔에 따라 느낌이 달라져요.","보통 빨강과 노랑은 따뜻한 느낌을 줘요.","파랑과 청록은 차가운 느낌을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#6','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'mc','auto','『국어활동』 25쪽 유현민의 글과 그림이에요. 그림을 보아야 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 25쪽 유현민의 글과 그림이에요. 그림을 보아야 알 수 있는 것은 무엇인가요?","options":[{"t":"야구 선수가 되고 싶어 한다는 것","correct":true},{"t":"3학년 5반이라는 것","mis":"K3-2-u2-X19"},{"t":"조용히 있을 때가 많다는 것","mis":"K3-2-u2-X19"},{"t":"다양한 친구와 어울리기를 좋아한다는 것","mis":"K3-2-u2-X19"}],"explanation":["반, 성격, 하고 싶은 일은 글에 쓰여 있어요.","취미·음식·생일·혈액형·꿈·좋아하는 색은 그림에 있어요.","꿈이 야구 선수라는 것은 그림으로 알 수 있어요."],"asset":{"type":"passage","lines":["저는 3학년 5반 유현민입니다.","조용히 있을 때가 많지만 다양한 친구와 어울리기를 좋아합니다.","친구들에게 저를 알리고 학교생활을 즐겁게 하고 싶습니다.","[그림] 취미 — 책 읽기·그림 그리기 / 잘 먹는 음식 — 비빔밥","[그림] 생일 — 6월 2일 / 혈액형 — B형","[그림] 꿈 — 야구 선수 / 좋아하는 색깔 — 보라색"],"title":"유현민의 글과 그림 — 『국어활동』 25쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#7','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'mc','auto','『국어활동』 24쪽 1번이에요. 노란 우산을 쓴 아이가 비 오는 길을 혼자 걷는 그림에 어울리는 문장은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 24쪽 1번이에요. 노란 우산을 쓴 아이가 비 오는 길을 혼자 걷는 그림에 어울리는 문장은 무엇인가요?","options":[{"t":"우산에 빗방울이 후드득 떨어집니다.","correct":true},{"t":"별이 하늘에서 반짝입니다.","mis":"K3-2-u2-X19"},{"t":"낙엽이 울긋불긋합니다.","mis":"K3-2-u2-X19"},{"t":"사탕 세 개가 나란히 놓여 있습니다.","mis":"K3-2-u2-X19"}],"explanation":["그림 속 상황과 대상을 먼저 살펴요.","비, 우산, 혼자 걷는 아이가 보여요.","「차가운 비가 내립니다.」, 「아이 혼자 빗길을 걸어갑니다.」도 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#8','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',4,'mc','auto','『국어』 93쪽 활동지 예시예요. 「자동차마다 다른 자동차 번호판」 제목에서 색이 다른 부분을 크기도 크게 바꾸고 싶다고 했어요. 알맞은 까닭은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X19']::text[],false,'{"seq":8,"concept":"K3-2-u2-C11","difficulty":4,"kind":"mc","stem":"『국어』 93쪽 활동지 예시예요. 「자동차마다 다른 자동차 번호판」 제목에서 색이 다른 부분을 크기도 크게 바꾸고 싶다고 했어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"설명하려는 내용에 주목하도록 할 수 있기 때문","correct":true},{"t":"제목은 모든 글자를 똑같이 크게 써야 하기 때문","mis":"K3-2-u2-X23"},{"t":"글자가 크면 그림을 넣지 않아도 되기 때문","mis":"K3-2-u2-X19"},{"t":"색과 크기는 많이 바꿀수록 좋기 때문","mis":"K3-2-u2-X23"}],"explanation":["「자동차 번호판」이 이 칸에서 설명하려는 내용이에요.","그 부분을 색과 크기로 함께 강조하면 더 눈에 띄어요.","모두 크게 하면 무엇이 중요한지 보이지 않아요."],"asset":{"type":"passage","lines":["제목: 자동차마다 다른 자동차 번호판 (「자동차 번호판」만 다른 색)","자동차 주인이 누구인지 알기 위해 자동차마다 다른 번호판을 답니다.","[그림] 승용차 — 버스보다 작은 차인데 번호판 숫자는 크게 그림"],"title":"「이름처럼 쓰는 숫자」 첫 칸 — 『국어』 90쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#9','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',4,'essay','teacher','『국어활동』 25쪽 3번이에요. 자신을 글과 그림으로 소개한다면 글로 쓸 내용 하나와 그림으로 나타낼 내용 하나를 정해 각각 까닭을 쓰고, 크고 진한 글씨로 강조할 것도 하나 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C10","difficulty":4,"kind":"essay","stem":"『국어활동』 25쪽 3번이에요. 자신을 글과 그림으로 소개한다면 글로 쓸 내용 하나와 그림으로 나타낼 내용 하나를 정해 각각 까닭을 쓰고, 크고 진한 글씨로 강조할 것도 하나 쓰세요.","answer_guide":{"answer":"예: 글 — 소개하고 싶은 까닭(그림으로 나타내기 어려우니까). 그림 — 키우는 강아지와 좋아하는 과목인 체육(한눈에 보여 줄 수 있으니까). 강조 — 이름을 크고 진한 글씨로 쓴다.","scoring_points":["글로 쓸 내용과 까닭을 썼는가","그림으로 나타낼 내용과 까닭을 썼는가","크고 진한 글씨로 강조할 것을 정했는가"]},"explanation":["그림으로 나타내기 어려운 것은 글로 설명해요.","한눈에 보여 줄 수 있는 것은 그림으로 나타내요.","가장 중요한 것은 크고 진하게 써서 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L07_challenge#10','kor',3,2,'u2','L07','tb_g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',4,'essay','teacher','『국어』 93쪽 「자신이라면 어떻게 표현했을지 말해 봐요.」예요. 「다니는 곳에 따라 다른 버스 번호」를 내가 만든다면 색·크기·모양 가운데 하나를 골라 어떻게 바꾸어 표현할지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C11","difficulty":4,"kind":"essay","stem":"『국어』 93쪽 「자신이라면 어떻게 표현했을지 말해 봐요.」예요. 「다니는 곳에 따라 다른 버스 번호」를 내가 만든다면 색·크기·모양 가운데 하나를 골라 어떻게 바꾸어 표현할지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 모양 — 출발지에서 도착지까지 지도 위에 화살표를 그려 버스가 가는 길을 보여 주겠다. 까닭 — 1번 지역에서 2번 지역으로 간다는 것을 한눈에 알 수 있기 때문이다.","scoring_points":["색·크기·모양 가운데 하나를 골랐는가","어떻게 바꾸어 표현할지 구체적으로 썼는가","바꾼 표현이 전하려는 내용을 더 잘 보여 주는 까닭을 썼는가"]},"explanation":["색은 구별, 크기는 강조, 모양은 무엇인지·어느 쪽인지 알려 줘요.","바꾸는 까닭은 꾸밈이 아니라 전하려는 내용이에요.","같은 내용도 나타내는 방법은 여러 가지예요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#1','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',1,'mc','auto','태권도를 설명하는 글 ㉮에서 중요한 내용은 무엇인가요?',ARRAY['K3-2-u2-X21','K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C12","difficulty":1,"kind":"mc","stem":"태권도를 설명하는 글 ㉮에서 중요한 내용은 무엇인가요?","options":[{"t":"태권도의 기본자세에는 앞서기, 주춤서기, 앞굽이 서기 같은 것들이 있다","correct":true},{"t":"주춤서기를 할 때는 말을 타는 것처럼 다리를 넓게 벌린다","mis":"K3-2-u2-X21"},{"t":"태권도에서 매는 띠에는 오방색이 사용된다","mis":"K3-2-u2-X15"},{"t":"태권도를 하면 체력이 좋아진다","mis":"K3-2-u2-X15"}],"explanation":["글 ㉮는 첫 문장에서 「여러 가지 기본자세」를 말해요.","자세마다의 설명은 그 내용을 자세히 풀어 준 것이에요.","띠와 좋은 점은 글 ㉰·㉱의 내용이에요."],"asset":{"type":"passage","lines":["태권도에는 여러 가지 기본자세가 있다.","앞서기는 한쪽 발을 앞으로 내디딘 자세이다.","주춤서기는 말을 타는 것처럼 다리를 넓게 벌리고 무릎을 살짝 구부린 자세이다.","앞굽이 서기는 앞다리를 굽혀서 무게를 앞다리에 싣는 자세이다."],"title":"글 ㉮ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#2','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',1,'match','auto','『국어』 95쪽 (2)예요. 태권도 글과 그 글의 중요한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u2-C12","difficulty":1,"kind":"match","stem":"『국어』 95쪽 (2)예요. 태권도 글과 그 글의 중요한 내용을 알맞게 이으세요.","pairs":[{"l":"글 ㉮","r":"태권도의 기본자세"},{"l":"글 ㉯","r":"태권도의 기본 동작"},{"l":"글 ㉰","r":"태권도에서 매는 띠의 색"},{"l":"글 ㉱","r":"태권도를 하면 좋은 점"}],"mis":"K3-2-u2-X15","explanation":["글마다 첫 문장에 무엇을 설명할지가 드러나요.","㉮ 자세, ㉯ 동작, ㉰ 띠, ㉱ 좋은 점이에요.","중요한 내용을 알아야 발표 주제를 고를 수 있어요."],"asset":{"type":"passage","lines":["㉮ 기본자세 — 앞서기, 주춤서기, 앞굽이 서기","㉯ 기본 동작 — 손 기술(막기 셋)과 발 기술(차기 셋)","㉰ 띠의 색 — 흰·노랑·빨강·파랑·검정, 오방색, 실력 따라 바뀜","㉱ 좋은 점 — 체력, 집중력, 상대를 존중하는 마음"],"title":"태권도 글 ㉮~㉱ 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#3','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',1,'sa','auto','글 ㉰에서 태권도를 처음 시작할 때 매는 띠는 무슨 색인가요?','{}'::text[],false,'{"seq":3,"concept":"K3-2-u2-C12","difficulty":1,"kind":"sa","stem":"글 ㉰에서 태권도를 처음 시작할 때 매는 띠는 무슨 색인가요?","answer":["흰색","흰색 띠","흰 띠","하얀색","흰색이에요"],"explanation":["「보통 처음 시작할 때에는」이 들어간 줄을 찾아요.","처음 시작할 때에는 흰색 띠를 매요.","실력이 좋아지면 검은색 띠를 매요."],"asset":{"type":"passage","lines":["태권도에서 매는 띠의 색은 다양하다.","특히 흰색, 노란색, 빨간색, 파란색, 검은색이 주로 사용된다.","이 다섯 가지 색은 우리나라의 전통색인 오방색이다.","태권도 실력이 늘면 띠의 색도 바뀐다.","보통 처음 시작할 때에는 흰색 띠를 맨다. 실력이 좋아지면 검은색 띠를 맨다."],"title":"글 ㉰ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#4','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',1,'mc','auto','『국어』 96쪽에서 발표 자료를 만들 때 정리하는 네 칸이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":4,"concept":"K3-2-u2-C13","difficulty":1,"kind":"mc","stem":"『국어』 96쪽에서 발표 자료를 만들 때 정리하는 네 칸이 아닌 것은 무엇인가요?","options":[{"t":"발표할 날의 날씨","correct":true},{"t":"제목과 내용","mis":"K3-2-u2-X22"},{"t":"그림","mis":"K3-2-u2-X22"},{"t":"발표 자료 얼개 짜기","mis":"K3-2-u2-X22"}],"explanation":["네 칸은 제목과 내용 · 그림 · 색, 크기, 모양 · 발표 자료 얼개 짜기예요.","얼개를 먼저 짜면 무엇을 어디에 놓을지 정해져요.","날씨는 발표 자료를 만드는 칸이 아니에요."],"asset":{"type":"passage","lines":["제목과 내용 — 태권도의 기본자세","그림 — 태권도의 기본자세를 보여 주는 그림","색, 크기, 모양 — 제목: 파란색, 본문보다 크게 / 본문: 검은색, 제목보다 작게","얼개 — 맨 위 가운데에 제목(글자 크기 키우기·다른 색깔로)","얼개 — 가운데에 앞서기·주춤서기·앞굽이 서기 그림 셋","얼개 — 그림 아래 자세 이름과 설명(설명 글자는 작게, 간단하게)"],"title":"발표 자료를 만드는 방법 — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#5','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',2,'blank','auto','『국어』 96쪽 예시의 「색, 크기, 모양」 칸이에요. 「제목: 파란색, 본문보다 (     ) / 본문: 검은색, 제목보다 작게」',ARRAY['K3-2-u2-X22','K3-2-u2-X23']::text[],false,'{"seq":5,"concept":"K3-2-u2-C13","difficulty":2,"kind":"blank","stem":"『국어』 96쪽 예시의 「색, 크기, 모양」 칸이에요. 「제목: 파란색, 본문보다 (     ) / 본문: 검은색, 제목보다 작게」","options":[{"t":"크게","correct":true},{"t":"작게","mis":"K3-2-u2-X22"},{"t":"똑같이","mis":"K3-2-u2-X23"},{"t":"흐리게","mis":"K3-2-u2-X22"}],"explanation":["제목은 가장 먼저 눈에 들어와야 해요.","그래서 제목은 본문보다 크게, 다른 색으로 써요.","본문은 제목보다 작게, 검은색으로 써요."],"asset":{"type":"passage","lines":["제목과 내용 — 태권도의 기본자세","그림 — 태권도의 기본자세를 보여 주는 그림","색, 크기, 모양 — 제목: 파란색, 본문보다 크게 / 본문: 검은색, 제목보다 작게","얼개 — 맨 위 가운데에 제목(글자 크기 키우기·다른 색깔로)","얼개 — 가운데에 앞서기·주춤서기·앞굽이 서기 그림 셋","얼개 — 그림 아래 자세 이름과 설명(설명 글자는 작게, 간단하게)"],"title":"발표 자료를 만드는 방법 — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#6','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','일기 예보 자료에서 글 부분만 읽었을 때 든 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X08']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"일기 예보 자료에서 글 부분만 읽었을 때 든 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"날씨를 자세히 알 수 있었지만 한눈에 알아보기는 어려웠다","correct":true},{"t":"날씨를 한눈에 알 수 있었지만 자세한 내용은 몰랐다","mis":"K3-2-u2-X19"},{"t":"글만 있으면 그림은 하나도 필요 없다","mis":"K3-2-u2-X19"},{"t":"글이 길어서 날씨를 전혀 알 수 없었다","mis":"K3-2-u2-X08"}],"explanation":["글은 기온과 날씨 변화를 자세히 알려 줘요.","하지만 중요한 정보를 찾는 데 시간이 걸려요.","한눈에 알게 하는 것은 그림이 하는 일이에요."],"asset":{"type":"passage","lines":["이번 주말은 맑고 쾌청한 날씨가 예상됩니다.","금요일 오후부터 점차 하늘이 개면서 기온도 서서히 오르겠습니다.","토요일은 아침 최저 기온 6도, 낮 최고 기온이 19도입니다.","일요일은 최저 7도, 최고 18도로 예상되어","단풍을 감상하기에 좋은 날씨가 될 것으로 보입니다.","[그림] 토 해 그림 6·19 / 일 해 그림 7·18 (낮은 기온 파란 숫자, 높은 기온 빨간 숫자)"],"title":"글과 그림을 활용한 일기 예보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#7','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C10',2,'sa','auto','같은 일기 예보에서 토요일 낮 최고 기온은 몇 도인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":2,"kind":"sa","stem":"같은 일기 예보에서 토요일 낮 최고 기온은 몇 도인가요? 숫자만 쓰세요.","answer":["19"],"explanation":["「토요일은 아침 최저 기온 6도, 낮 최고 기온이 19도」라고 했어요.","그림에서는 높은 기온을 빨간 숫자로 나타냈어요.","글과 그림을 함께 보면 토요일과 일요일을 한눈에 견줄 수 있어요."],"asset":{"type":"passage","lines":["이번 주말은 맑고 쾌청한 날씨가 예상됩니다.","금요일 오후부터 점차 하늘이 개면서 기온도 서서히 오르겠습니다.","토요일은 아침 최저 기온 6도, 낮 최고 기온이 19도입니다.","일요일은 최저 7도, 최고 18도로 예상되어","단풍을 감상하기에 좋은 날씨가 될 것으로 보입니다.","[그림] 토 해 그림 6·19 / 일 해 그림 7·18 (낮은 기온 파란 숫자, 높은 기온 빨간 숫자)"],"title":"글과 그림을 활용한 일기 예보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#8','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C14',2,'mc','auto','『국어』 98쪽에서 친구들과 의견을 나누는 방법의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X25','K3-2-u2-X26']::text[],false,'{"seq":8,"concept":"K3-2-u2-C14","difficulty":2,"kind":"mc","stem":"『국어』 98쪽에서 친구들과 의견을 나누는 방법의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"자료를 알림판에 붙인다 → 친구 자료를 읽고 잘한 점을 붙임쪽지에 쓴다 → 친구 자료 옆에 붙인다","correct":true},{"t":"친구 자료를 읽고 잘못한 점만 붙임쪽지에 쓴다 → 자료를 알림판에 붙인다","mis":"K3-2-u2-X25"},{"t":"자료를 알림판에 붙인다 → 내 자료 앞에서만 기다린다","mis":"K3-2-u2-X26"},{"t":"붙임쪽지를 아무 곳에나 붙인다 → 자료를 알림판에 붙인다","mis":"K3-2-u2-X25"}],"explanation":["먼저 정리한 자료를 교실 알림판에 붙여요.","친구 자료를 읽고 잘한 점을 붙임쪽지에 써요.","그 쪽지를 친구 자료 옆에 붙여요."],"asset":{"type":"passage","lines":["① 정리한 자료를 교실 알림판에 붙인다.","② 친구가 정리한 자료를 읽고 잘한 점을 붙임쪽지에 쓴다.","③ 친구가 정리한 자료 옆에 붙임쪽지를 붙인다."],"title":"친구들과 의견을 나누는 방법 — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#9','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C14',2,'ox','auto','태권도 띠를 설명한 두 친구의 발표 자료가 배치가 서로 다르다면, 둘 가운데 하나는 잘못 만든 거예요.',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":9,"concept":"K3-2-u2-C14","difficulty":2,"kind":"ox","stem":"태권도 띠를 설명한 두 친구의 발표 자료가 배치가 서로 다르다면, 둘 가운데 하나는 잘못 만든 거예요.","answer":"X","reason_options":[{"t":"같은 내용을 설명하더라도 표현과 배치는 다를 수 있어요.","correct":true},{"t":"같은 내용이면 배치도 하나로 똑같아야 해요.","mis":"K3-2-u2-X24"}],"mis":"K3-2-u2-X24","explanation":["얼개를 짠 것을 보고 서로 이야기 나누어 보면 알 수 있어요.","전하려는 것이 잘 보이면 둘 다 알맞아요.","다른 점을 견주어 보면 내 자료를 보완할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_basic#10','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',3,'mc','auto','태권도 기본 동작의 순서를 발표 자료에 보여 주려고 해요. 알맞게 활용한 방법은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X22','K3-2-u2-X19']::text[],false,'{"seq":10,"concept":"K3-2-u2-C13","difficulty":3,"kind":"mc","stem":"태권도 기본 동작의 순서를 발표 자료에 보여 주려고 해요. 알맞게 활용한 방법은 무엇인가요?","options":[{"t":"동작마다 1, 2, 3 숫자를 붙여 순서를 나타낸다","correct":true},{"t":"모든 글자를 서로 다른 색으로 칠한다","mis":"K3-2-u2-X23"},{"t":"설명 글을 제목보다 크게 쓴다","mis":"K3-2-u2-X22"},{"t":"그림 없이 긴 글로만 쓴다","mis":"K3-2-u2-X19"}],"explanation":["동작의 순서는 숫자를 붙인 도형으로 나타낼 수 있어요.","숫자를 따라가면 무엇을 먼저 하는지 한눈에 보여요.","색과 크기는 전하려는 것이 눈에 띄게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#1','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',2,'mc','auto','내용 파악 질문 「태권도의 기본 동작에는 무슨 동작이 있나요?」의 답은 어느 글에서 찾을 수 있나요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"내용 파악 질문 「태권도의 기본 동작에는 무슨 동작이 있나요?」의 답은 어느 글에서 찾을 수 있나요?","options":[{"t":"글 ㉯","correct":true},{"t":"글 ㉮","mis":"K3-2-u2-X15"},{"t":"글 ㉰","mis":"K3-2-u2-X15"},{"t":"글 ㉱","mis":"K3-2-u2-X15"}],"explanation":["글마다 무엇을 설명하는지 먼저 떠올려요.","기본 동작(손 기술·발 기술)은 글 ㉯에 있어요.","자료를 읽고 질문을 주고받으면 내용을 확실히 알 수 있어요."],"asset":{"type":"passage","lines":["㉮ 기본자세 — 앞서기, 주춤서기, 앞굽이 서기","㉯ 기본 동작 — 손 기술(막기 셋)과 발 기술(차기 셋)","㉰ 띠의 색 — 흰·노랑·빨강·파랑·검정, 오방색, 실력 따라 바뀜","㉱ 좋은 점 — 체력, 집중력, 상대를 존중하는 마음"],"title":"태권도 글 ㉮~㉱ 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#2','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',2,'mc','auto','글 ㉱에서 「품새」는 무엇이라고 했나요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":2,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"글 ㉱에서 「품새」는 무엇이라고 했나요?","options":[{"t":"기본 동작과 기술을 자연스럽게 연결하는 연습","correct":true},{"t":"상대와 맞서 겨루는 경기","mis":"K3-2-u2-X16"},{"t":"띠의 색을 바꾸는 시험","mis":"K3-2-u2-X16"},{"t":"말을 타는 것처럼 서는 자세","mis":"K3-2-u2-X16"}],"explanation":["글 안에서 낱말의 뜻을 풀어 준 문장을 찾아요.","「품새는 기본 동작과 기술을 자연스럽게 연결하는 연습이다.」","상대와 맞서는 것은 겨루기예요."],"asset":{"type":"passage","lines":["태권도를 하면 좋은 점이 많다.","첫째, 발차기와 손동작을 할 때 여러 근육을 써서 체력이 좋아진다.","둘째, 품새에 집중해서 연습하므로 집중력이 높아진다.","품새는 기본 동작과 기술을 자연스럽게 연결하는 연습이다.","셋째, 겨루기를 하면서 상대를 존중하는 마음을 배우게 된다.","그래서 태권도를 하면 예절도 함께 익힐 수 있다."],"title":"글 ㉱ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#3','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',3,'mc','auto','처음 태권도를 배우는 1학년 동생들에게 「시작하면 어떤 띠를 매고 어떻게 바뀌는지」 알려 주려고 해요. 발표 자료에 넣을 내용으로 가장 알맞은 글은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":3,"concept":"K3-2-u2-C12","difficulty":3,"kind":"mc","stem":"처음 태권도를 배우는 1학년 동생들에게 「시작하면 어떤 띠를 매고 어떻게 바뀌는지」 알려 주려고 해요. 발표 자료에 넣을 내용으로 가장 알맞은 글은 무엇인가요?","options":[{"t":"글 ㉰","correct":true},{"t":"글 ㉯의 돌려차기 설명","mis":"K3-2-u2-X21"},{"t":"글 ㉮","mis":"K3-2-u2-X21"},{"t":"글 ㉱","mis":"K3-2-u2-X21"}],"explanation":["누구에게, 왜 알려 줄지부터 정해요.","띠의 색과 실력에 따라 바뀌는 것은 글 ㉰에 있어요.","목적과 상관없는 내용은 재미있어도 넣지 않아요."],"asset":{"type":"passage","lines":["㉮ 기본자세 — 앞서기, 주춤서기, 앞굽이 서기","㉯ 기본 동작 — 손 기술(막기 셋)과 발 기술(차기 셋)","㉰ 띠의 색 — 흰·노랑·빨강·파랑·검정, 오방색, 실력 따라 바뀜","㉱ 좋은 점 — 체력, 집중력, 상대를 존중하는 마음"],"title":"태권도 글 ㉮~㉱ 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#4','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',3,'mc','auto','『국어』 97쪽 「태권도에서 매는 띠의 색」 얼개에 맞게 놓은 것은 무엇인가요?',ARRAY['K3-2-u2-X22','K3-2-u2-X19','K3-2-u2-X23']::text[],false,'{"seq":4,"concept":"K3-2-u2-C13","difficulty":3,"kind":"mc","stem":"『국어』 97쪽 「태권도에서 매는 띠의 색」 얼개에 맞게 놓은 것은 무엇인가요?","options":[{"t":"맨 위 가운데에 제목을 크게, 그 아래 띠 그림 다섯, 그림들 위에 오방색이라는 짧은 글","correct":true},{"t":"맨 위에 긴 설명 글, 맨 아래에 작은 제목","mis":"K3-2-u2-X22"},{"t":"띠 그림 없이 다섯 가지 색 이름만 길게 쓴 글","mis":"K3-2-u2-X19"},{"t":"제목·그림·설명을 모두 같은 크기로 섞어 놓은 것","mis":"K3-2-u2-X23"}],"explanation":["얼개 짜기에서 제목은 가운데에 크게 써요.","띠 그림 다섯이 가운데 자리를 차지해요.","오방색이라는 내용은 그림들 위에 간단하게 써요."],"asset":{"type":"passage","lines":["제목과 내용 — 태권도에서 매는 띠의 색","그림 — 흰 띠·노란 띠·빨간 띠·파란 띠·검은 띠","얼개 — 제목을 가운데에 크게 쓴다.","얼개 — 띠 그림들 위에 오방색이 사용된다는 내용을 간단하게 글로 쓴다."],"title":"발표할 내용 정리 예시 — 『국어』 97쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#5','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',3,'mc','auto','태권도에서 매는 띠의 색을 글씨로 쓸 때 색을 알맞게 활용한 방법은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X22','K3-2-u2-X23']::text[],false,'{"seq":5,"concept":"K3-2-u2-C13","difficulty":3,"kind":"mc","stem":"태권도에서 매는 띠의 색을 글씨로 쓸 때 색을 알맞게 활용한 방법은 무엇인가요?","options":[{"t":"「노란색」은 노란 글씨로, 「파란색」은 파란 글씨로 쓴다","correct":true},{"t":"모든 띠 이름을 빨간 글씨로 쓴다","mis":"K3-2-u2-X20"},{"t":"띠 이름은 아주 작고 흐리게 쓴다","mis":"K3-2-u2-X22"},{"t":"띠 이름마다 알록달록한 테두리를 여러 겹 두른다","mis":"K3-2-u2-X23"}],"explanation":["띠의 색을 글씨 색으로 바꾸면 한눈에 구별돼요.","색은 서로 다른 것을 구별해 보여 줘요.","꾸밈을 많이 할수록 좋은 것은 아니에요."],"asset":{"type":"passage","lines":["태권도에서 매는 띠의 색은 다양하다.","특히 흰색, 노란색, 빨간색, 파란색, 검은색이 주로 사용된다.","이 다섯 가지 색은 우리나라의 전통색인 오방색이다.","태권도 실력이 늘면 띠의 색도 바뀐다.","보통 처음 시작할 때에는 흰색 띠를 맨다. 실력이 좋아지면 검은색 띠를 맨다."],"title":"글 ㉰ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#6','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',3,'mc','auto','돌려차기처럼 몸이 움직이는 방향을 발표 자료에서 보여 주려면 어떻게 하면 좋을까요?',ARRAY['K3-2-u2-X20','K3-2-u2-X19']::text[],false,'{"seq":6,"concept":"K3-2-u2-C13","difficulty":3,"kind":"mc","stem":"돌려차기처럼 몸이 움직이는 방향을 발표 자료에서 보여 주려면 어떻게 하면 좋을까요?","options":[{"t":"몸의 움직임을 화살표로 그려 방향을 보여 준다","correct":true},{"t":"제목 글자를 가장 크게 쓴다","mis":"K3-2-u2-X20"},{"t":"방향은 그림 대신 긴 글로만 쓴다","mis":"K3-2-u2-X19"},{"t":"강조하고 싶은 낱말마다 밑줄을 긋는다","mis":"K3-2-u2-X20"}],"explanation":["화살표 같은 모양은 어느 쪽인지 알려 줘요.","몸이 움직이는 방향은 글보다 그림으로 한눈에 보여요.","밑줄과 굵은 글씨는 강조하고 싶은 문장에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#7','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C14',3,'mc','auto','친구 발표 자료 옆에 붙일 붙임쪽지로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":7,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"친구 발표 자료 옆에 붙일 붙임쪽지로 가장 알맞은 것은 무엇인가요?","options":[{"t":"띠 색을 그림으로 먼저 보여 주어 한눈에 알 수 있었어. 제목을 조금 더 크게 쓰면 더 눈에 띌 것 같아.","correct":true},{"t":"글씨가 삐뚤빼뚤해. 다시 만들어.","mis":"K3-2-u2-X25"},{"t":"무조건 최고야!","mis":"K3-2-u2-X25"},{"t":"내 자료가 더 잘 만들었어.","mis":"K3-2-u2-X25"}],"explanation":["눈에 잘 띄는 부분을 살펴보고 잘한 점을 찾아요.","더 잘 보이게 할 방법도 함께 말해 주면 도움이 돼요.","친구의 의견을 존중하며 반응해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#8','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',4,'mc','auto','『국어』 99쪽 「글과 그림을 활용해 잘 발표했는지 스스로 확인해 봅시다.」에 있는 물음이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X21','K3-2-u2-X22','K3-2-u2-X23']::text[],false,'{"seq":8,"concept":"K3-2-u2-C13","difficulty":4,"kind":"mc","stem":"『국어』 99쪽 「글과 그림을 활용해 잘 발표했는지 스스로 확인해 봅시다.」에 있는 물음이 아닌 것은 무엇인가요?","options":[{"t":"그림을 되도록 많이 넣었나요?","correct":true},{"t":"중심 내용이 잘 드러나도록 글을 정리했나요?","mis":"K3-2-u2-X21"},{"t":"글과 그림을 서로 어울리게 배치했나요?","mis":"K3-2-u2-X22"},{"t":"색, 크기, 모양을 내용에 따라 적절히 활용했나요?","mis":"K3-2-u2-X23"}],"explanation":["스스로 확인하는 물음은 세 가지예요.","중심 내용 · 글과 그림의 배치 · 색, 크기, 모양이에요.","그림의 개수가 많다고 잘 만든 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#9','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',4,'essay','teacher','태권도에 대해 더 알아보고 싶은 점을 질문 하나로 만들고, 그 답을 어디에서 찾을지와 발표 자료에서 글로 쓸지 그림으로 보일지 정해 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C12","difficulty":4,"kind":"essay","stem":"태권도에 대해 더 알아보고 싶은 점을 질문 하나로 만들고, 그 답을 어디에서 찾을지와 발표 자료에서 글로 쓸지 그림으로 보일지 정해 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 질문 — 태권도의 겨루기는 어떤 규칙으로 할까? 찾을 곳 — 도서관의 태권도 책이나 태권도장 사범님께 여쭈어 본다. 나타내기 — 점수를 얻는 곳은 그림으로 보여 주고, 규칙은 글로 짧게 쓴다. 몸의 어디를 차는지는 그림이 한눈에 보이기 때문이다.","scoring_points":["더 알아보고 싶은 점을 질문으로 만들었는가","답을 찾을 곳(책·인터넷·사람)을 정했는가","글로 쓸지 그림으로 보일지 까닭과 함께 정했는가"]},"explanation":["자료를 읽고 더 알고 싶은 점을 질문으로 만들어요.","책, 인터넷, 둘레 사람에게서 답을 찾을 수 있어요.","자세한 것은 글, 한눈에 보일 것은 그림으로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L08_challenge#10','kor',3,2,'u2','L08','tb_g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',4,'essay','teacher','설명하고 싶은 음식을 하나 정해요. 발표 자료의 「제목과 내용」·「그림」·「색, 크기, 모양」·「얼개」를 한 줄씩 계획해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C13","difficulty":4,"kind":"essay","stem":"설명하고 싶은 음식을 하나 정해요. 발표 자료의 「제목과 내용」·「그림」·「색, 크기, 모양」·「얼개」를 한 줄씩 계획해 쓰세요.","answer_guide":{"answer":"예: 제목과 내용 — 비빔밥 만드는 방법(재료 준비 → 밥 위에 나물 올리기 → 비비기). 그림 — 차례마다 그릇 그림 셋. 색, 크기, 모양 — 제목은 주황색으로 크게, 차례는 1·2·3 숫자 동그라미로. 얼개 — 맨 위 가운데 제목, 가운데 그림 셋을 왼쪽에서 오른쪽으로, 그림 아래 짧은 설명.","scoring_points":["제목과 내용을 정했는가","그림과 색·크기·모양을 내용에 맞게 정했는가","제목·그림·설명의 자리를 얼개로 짰는가"]},"explanation":["제목은 전하려는 중심 내용이 드러나게 간결하게 정해요.","색·크기·모양은 전하려는 것이 눈에 띄게 써요.","얼개를 먼저 짜면 글과 그림을 어울리게 놓을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#1','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',1,'mc','auto','『국어』 100쪽 「글과 그림을 활용해 짧은 이야기 소개하기」에서 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u2-X21','K3-2-u2-X26','K3-2-u2-X23']::text[],false,'{"seq":1,"concept":"K3-2-u2-C15","difficulty":1,"kind":"mc","stem":"『국어』 100쪽 「글과 그림을 활용해 짧은 이야기 소개하기」에서 가장 먼저 할 일은 무엇인가요?","options":[{"t":"소개하고 싶은 짧은 이야기를 정한다","correct":true},{"t":"그림부터 아무거나 고른다","mis":"K3-2-u2-X21"},{"t":"친구 발표 때 내 차례만 준비한다","mis":"K3-2-u2-X26"},{"t":"발표 자료를 꾸밀 색부터 정한다","mis":"K3-2-u2-X23"}],"explanation":["① 소개하고 싶은 짧은 이야기 정하기가 먼저예요.","② 소개할 때 활용할 그림 선택하기가 다음이에요.","③ 친구들에게 짧은 이야기를 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#2','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',1,'mc','auto','짧은 이야기를 소개할 때 활용할 그림으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X21']::text[],false,'{"seq":2,"concept":"K3-2-u2-C15","difficulty":1,"kind":"mc","stem":"짧은 이야기를 소개할 때 활용할 그림으로 알맞은 것은 무엇인가요?","options":[{"t":"이야기의 흐름에서 중요하거나 감동적인 장면을 나타낸 그림","correct":true},{"t":"이야기와 상관없이 가장 알록달록한 그림","mis":"K3-2-u2-X23"},{"t":"인물이 아주 작게 나온 아무 그림","mis":"K3-2-u2-X21"},{"t":"표지에 있는 그림이면 무엇이든","mis":"K3-2-u2-X21"}],"explanation":["그림은 이야기의 중요한 장면을 보여 주려고 골라요.","감동적인 부분을 그림으로 보여 주면 친구들이 잘 기억해요.","어떤 차례로 글과 그림을 보여 줄지도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#3','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',1,'mc','auto','‘것’, ‘수’를 바르게 띄어 쓴 문장은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":3,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"‘것’, ‘수’를 바르게 띄어 쓴 문장은 무엇인가요?","options":[{"t":"가을이 온 것을 느낄 수 있습니다.","correct":true},{"t":"가을이 온것을 느낄수 있습니다.","mis":"K3-2-u2-X27"},{"t":"가을이 온 것을 느낄수 있습니다.","mis":"K3-2-u2-X27"},{"t":"가을이 온것을 느낄 수 있습니다.","mis":"K3-2-u2-X27"}],"explanation":["‘것’, ‘수’는 다른 말에 기대어 쓰는 말이에요.","그래서 앞말과 띄어 써요 — 「온 것」, 「느낄 수」.","『국어』 104쪽 「단풍 구경」에 나온 문장이에요."],"asset":{"type":"passage","lines":["단풍이 든 산에 오르면 우리는 가을이 온 것을 느낄 수 있습니다.","붉은 것, 노란 것, 그리고 계속해서 푸른 것까지.","알록달록 가을 풍경을 구경하다 보면 시간 가는 줄 모릅니다.","날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","가을을 오래 느낄 수 있으면 좋겠습니다."],"title":"「단풍 구경」 — 『국어』 104쪽","hi":["온 것","느낄 수","붉은 것","노란 것","푸른 것","가는 줄","된 줄"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#4','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',1,'ox','auto','「줄넘기」의 ‘줄’도 ‘것·수·줄’의 ‘줄’이니 「줄 넘기」로 띄어 써야 해요.',ARRAY['K3-2-u2-X28']::text[],false,'{"seq":4,"concept":"K3-2-u2-C16","difficulty":1,"kind":"ox","stem":"「줄넘기」의 ‘줄’도 ‘것·수·줄’의 ‘줄’이니 「줄 넘기」로 띄어 써야 해요.","answer":"X","reason_options":[{"t":"줄넘기는 한 낱말이라 붙여 써요. 모든 ‘것·수·줄’을 띄어 쓰는 것은 아니에요.","correct":true},{"t":"‘줄’이라는 글자가 나오면 언제나 띄어 써요.","mis":"K3-2-u2-X28"}],"mis":"K3-2-u2-X28","explanation":["「가는 줄」의 ‘줄’은 다른 말에 기대어 쓰여 띄어 써요.","줄넘기, 수요일처럼 한 낱말 속에 든 ‘줄’, ‘수’는 붙여 써요.","문장에서 어떤 뜻으로 쓰였는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#5','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C17',2,'mc','auto','『국어』 104쪽 2번이에요. 스탠드의 특징이 드러나는 새 이름으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":5,"concept":"K3-2-u2-C17","difficulty":2,"kind":"mc","stem":"『국어』 104쪽 2번이에요. 스탠드의 특징이 드러나는 새 이름으로 알맞은 것은 무엇인가요?","options":[{"t":"끄덕끄덕등","correct":true},{"t":"동글이","mis":"K3-2-u2-X29"},{"t":"푸른나무","mis":"K3-2-u2-X29"},{"t":"씽씽이","mis":"K3-2-u2-X29"}],"explanation":["스탠드는 빛을 내고, 목이 움직여요.","「끄덕끄덕」은 목이 움직이는 모습, 「등」은 빛을 내는 것을 나타내요.","「책짝꿍」처럼 책 읽을 때 쓰는 특징을 살린 이름도 있어요."],"asset":{"type":"passage","lines":["[그림] 책상 위 스탠드 — 『국어』 104쪽","사물의 특징: 빛을 낸다. · 목이 움직인다. · 주로 책을 읽을 때 쓰인다."],"title":"사물의 특징이 드러나도록 새로운 이름 짓기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#6','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',2,'blank','auto','「단풍 구경」이에요. 「알록달록 가을 풍경을 구경하다 보면 시간 (     ) 모릅니다.」 빈칸에 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":6,"concept":"K3-2-u2-C16","difficulty":2,"kind":"blank","stem":"「단풍 구경」이에요. 「알록달록 가을 풍경을 구경하다 보면 시간 (     ) 모릅니다.」 빈칸에 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"가는 줄","correct":true},{"t":"가는줄","mis":"K3-2-u2-X27"},{"t":"가 는줄","mis":"K3-2-u2-X27"}],"explanation":["‘줄’은 다른 말에 기대어 쓰는 말이에요.","앞말 「가는」과 띄어 써서 「가는 줄」이라고 써요.","「된 줄 압니다」도 같은 까닭으로 띄어 써요."],"asset":{"type":"passage","lines":["단풍이 든 산에 오르면 우리는 가을이 온 것을 느낄 수 있습니다.","붉은 것, 노란 것, 그리고 계속해서 푸른 것까지.","알록달록 가을 풍경을 구경하다 보면 시간 가는 줄 모릅니다.","날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","가을을 오래 느낄 수 있으면 좋겠습니다."],"title":"「단풍 구경」 — 『국어』 104쪽","hi":["온 것","느낄 수","붉은 것","노란 것","푸른 것","가는 줄","된 줄"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#7','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',2,'mc','auto','『국어』 101쪽 「관심 있는 직업 발표하기」예요. 가수를 소개하는 발표 자료에서 그림으로 나타내기에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":7,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"『국어』 101쪽 「관심 있는 직업 발표하기」예요. 가수를 소개하는 발표 자료에서 그림으로 나타내기에 알맞은 것은 무엇인가요?","options":[{"t":"노래할 때의 모습을 마이크와 음표로","correct":true},{"t":"가수가 하는 일을 자세히 풀어 쓴 설명","mis":"K3-2-u2-X19"},{"t":"가수를 소개하고 싶은 까닭","mis":"K3-2-u2-X19"},{"t":"가수에게 하고 싶은 질문","mis":"K3-2-u2-X19"}],"explanation":["한눈에 보여 줄 수 있는 모습은 그림으로 나타내요.","가수가 하는 일은 글로 자세히 써요.","글과 그림이 할 일을 나누면 발표가 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#8','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C1',2,'mc','auto','『국어』 103쪽 「스스로 확인하기」예요. 글을 유창하게 소리 내어 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X12','K3-2-u2-X02']::text[],false,'{"seq":8,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어』 103쪽 「스스로 확인하기」예요. 글을 유창하게 소리 내어 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"글의 분위기에 어울리는 목소리와 말투로 읽는다","correct":true},{"t":"정확한 발음으로 무조건 빠르게 읽는다","mis":"K3-2-u2-X01"},{"t":"슬픈 이야기도 밝은 목소리로 읽는다","mis":"K3-2-u2-X12"},{"t":"처음부터 끝까지 가장 큰 소리로 읽는다","mis":"K3-2-u2-X02"}],"explanation":["적절한 부분에서 띄어 가며 읽는 것도 알맞아요.","발음이 정확해도 「무조건 빠르게」는 알맞지 않아요.","슬픈 이야기는 분위기에 어울리는 목소리로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#9','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',2,'ox','auto','『국어』 103쪽 「생활 속으로」예요. 발표를 들을 때는 발표자의 말만 들으면 되고, 함께 보여 주는 그림은 보지 않아도 돼요.',ARRAY['K3-2-u2-X18']::text[],false,'{"seq":9,"concept":"K3-2-u2-C15","difficulty":2,"kind":"ox","stem":"『국어』 103쪽 「생활 속으로」예요. 발표를 들을 때는 발표자의 말만 들으면 되고, 함께 보여 주는 그림은 보지 않아도 돼요.","answer":"X","reason_options":[{"t":"발표를 들을 때 그림에도 집중하면 내용을 더 잘 이해할 수 있어요.","correct":true},{"t":"그림은 꾸미려고 넣은 것이라 안 봐도 돼요.","mis":"K3-2-u2-X18"}],"mis":"K3-2-u2-X18","explanation":["글과 그림을 함께 보면 내용을 더 잘 이해해요.","글을 읽을 때도 함께 있는 그림을 꼼꼼히 살펴요.","발표할 때는 글과 그림을 활용해 더 이해하기 쉽게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_basic#10','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',3,'mc','auto','‘수’와 ‘줄’이 들어간 문장이에요. 띄어쓰기가 바른 문장은 무엇인가요?',ARRAY['K3-2-u2-X28','K3-2-u2-X27']::text[],false,'{"seq":10,"concept":"K3-2-u2-C16","difficulty":3,"kind":"mc","stem":"‘수’와 ‘줄’이 들어간 문장이에요. 띄어쓰기가 바른 문장은 무엇인가요?","options":[{"t":"수요일에 줄넘기를 할 수 있어요.","correct":true},{"t":"수 요일에 줄 넘기를 할 수 있어요.","mis":"K3-2-u2-X28"},{"t":"수요일에 줄넘기를 할수 있어요.","mis":"K3-2-u2-X27"},{"t":"수요일에 줄넘기를 할 수있어요.","mis":"K3-2-u2-X27"}],"explanation":["「할 수」의 ‘수’는 다른 말에 기대어 쓰여 앞말과 띄어 써요.","뒷말 「있어요」와도 띄어 써요.","수요일, 줄넘기처럼 한 낱말 속의 ‘수’, ‘줄’은 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#1','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',2,'mc','auto','『국어』 104쪽에서 「온 것」, 「느낄 수」, 「가는 줄」의 ‘것·수·줄’을 앞말과 띄어 쓰는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":1,"concept":"K3-2-u2-C16","difficulty":2,"kind":"mc","stem":"『국어』 104쪽에서 「온 것」, 「느낄 수」, 「가는 줄」의 ‘것·수·줄’을 앞말과 띄어 쓰는 까닭은 무엇인가요?","options":[{"t":"다른 말에 기대어 쓰는 말이라서","correct":true},{"t":"글자가 하나라서 앞말에 붙여 쓰는 말이라서","mis":"K3-2-u2-X27"},{"t":"뒷말과 붙여 쓰는 말이라서","mis":"K3-2-u2-X27"},{"t":"문장 끝에 올 때만 띄어 쓰는 말이라서","mis":"K3-2-u2-X27"}],"explanation":["‘것’, ‘수’, ‘줄’은 혼자 쓰이지 못하고 다른 말에 기대어 쓰여요.","그런 말은 앞말과 띄어 써요.","여러 문장을 살펴보며 띄어 쓰는 방법을 익혀요."],"asset":{"type":"passage","lines":["단풍이 든 산에 오르면 우리는 가을이 온 것을 느낄 수 있습니다.","붉은 것, 노란 것, 그리고 계속해서 푸른 것까지.","알록달록 가을 풍경을 구경하다 보면 시간 가는 줄 모릅니다.","날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","가을을 오래 느낄 수 있으면 좋겠습니다."],"title":"「단풍 구경」 — 『국어』 104쪽","hi":["온 것","느낄 수","붉은 것","노란 것","푸른 것","가는 줄","된 줄"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#2','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C17',2,'mc','auto','친구가 스탠드에 「책짝꿍」이라는 이름을 지었어요. 이 이름에서 드러나는 사물의 특징은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":2,"concept":"K3-2-u2-C17","difficulty":2,"kind":"mc","stem":"친구가 스탠드에 「책짝꿍」이라는 이름을 지었어요. 이 이름에서 드러나는 사물의 특징은 무엇인가요?","options":[{"t":"주로 책을 읽을 때 쓰인다","correct":true},{"t":"목이 움직인다","mis":"K3-2-u2-X29"},{"t":"빛을 낸다","mis":"K3-2-u2-X29"},{"t":"물을 담는다","mis":"K3-2-u2-X29"}],"explanation":["이름에 들어 있는 낱말을 살펴요.","「책」과 「짝꿍」 — 책 읽을 때 늘 곁에 있는 것이에요.","이름만 듣고 원래 사물을 알아맞힐 수 있으면 잘 지은 이름이에요."],"asset":{"type":"passage","lines":["[그림] 책상 위 스탠드 — 『국어』 104쪽","사물의 특징: 빛을 낸다. · 목이 움직인다. · 주로 책을 읽을 때 쓰인다."],"title":"사물의 특징이 드러나도록 새로운 이름 짓기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#3','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',3,'error','auto','「단풍 구경」을 공책에 옮겨 썼어요. 띄어쓰기를 잘못한 친구는 누구인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":3,"concept":"K3-2-u2-C16","difficulty":3,"kind":"error","stem":"「단풍 구경」을 공책에 옮겨 썼어요. 띄어쓰기를 잘못한 친구는 누구인가요?","options":[{"t":"지민: 붉은것, 노란것, 그리고 계속해서 푸른것까지.","correct":true,"mis_target":"K3-2-u2-X27"},{"t":"수아: 날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","mis":"K3-2-u2-X27"},{"t":"도현: 가을을 오래 느낄 수 있으면 좋겠습니다.","mis":"K3-2-u2-X27"}],"explanation":["「붉은 것」, 「노란 것」, 「푸른 것」으로 띄어 써야 해요.","‘것’은 다른 말에 기대어 쓰는 말이에요.","수아와 도현이는 ‘줄’, ‘수’를 바르게 띄어 썼어요."],"asset":{"type":"passage","lines":["단풍이 든 산에 오르면 우리는 가을이 온 것을 느낄 수 있습니다.","붉은 것, 노란 것, 그리고 계속해서 푸른 것까지.","알록달록 가을 풍경을 구경하다 보면 시간 가는 줄 모릅니다.","날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","가을을 오래 느낄 수 있으면 좋겠습니다."],"title":"「단풍 구경」 — 『국어』 104쪽","hi":["온 것","느낄 수","붉은 것","노란 것","푸른 것","가는 줄","된 줄"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#4','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',3,'mc','auto','「공을 가지고 하는 운동 — 축구」에서 그림으로 표현하기에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":4,"concept":"K3-2-u2-C15","difficulty":3,"kind":"mc","stem":"「공을 가지고 하는 운동 — 축구」에서 그림으로 표현하기에 알맞은 것은 무엇인가요?","options":[{"t":"전반전과 후반전 경기 시간(90분)을 나타내는 시계","correct":true},{"t":"「상대편의 골에 공을 넣는 운동입니다.」라는 설명","mis":"K3-2-u2-X19"},{"t":"공을 많이 넣는 팀이 이긴다는 규칙 문장","mis":"K3-2-u2-X19"},{"t":"축구를 소개하고 싶은 까닭","mis":"K3-2-u2-X19"}],"explanation":["예시에서는 그림으로 90분을 나타내는 시계를 골랐어요.","두 팀 22명이 운동장 안에 있는 모습도 그림으로 보여 줘요.","어떤 운동인지 알려 주는 설명은 글로 써요."],"asset":{"type":"passage","lines":["축구는 손과 팔을 공에 대지 않고 발을 사용해서","상대편의 골에 공을 넣는 운동입니다.","공을 많이 넣는 팀이 이깁니다.","전반전과 후반전이 있으며, 경기 시간은 90분입니다.","한 팀은 총 11명으로 이루어져 있습니다."],"title":"공을 가지고 하는 운동 — 축구 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#5','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',3,'mc','auto','우리 반에서 할 실천 활동을 새로 정해요. 이 단원에서 배운 내용을 실천하는 활동으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":5,"concept":"K3-2-u2-C15","difficulty":3,"kind":"mc","stem":"우리 반에서 할 실천 활동을 새로 정해요. 이 단원에서 배운 내용을 실천하는 활동으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"받아쓰기 점수 겨루기","correct":true},{"t":"소개하고 싶은 물건을 설명하는 글을 유창하게 읽기","mis":"K3-2-u2-X21"},{"t":"올림픽 종목을 글과 그림으로 표현하기","mis":"K3-2-u2-X21"},{"t":"관심 있는 직업을 글과 그림으로 발표하기","mis":"K3-2-u2-X21"}],"explanation":["이 단원은 유창하게 읽기와 글과 그림으로 발표하기를 배웠어요.","실천 활동은 단원에서 배운 것과 이어져야 해요.","받아쓰기 겨루기는 이 단원의 배움과 거리가 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#6','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C2',3,'mc','auto','호랑이 모양 지우개를 소개하는 글의 셋째 문장을 알맞게 띄어 읽은 것은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":6,"concept":"K3-2-u2-C2","difficulty":3,"kind":"mc","stem":"호랑이 모양 지우개를 소개하는 글의 셋째 문장을 알맞게 띄어 읽은 것은 무엇인가요?","options":[{"t":"동물원에서∨엄마께서∨생일 선물로∨호랑이 모양의 지우개를∨사 주셨습니다.","correct":true},{"t":"동물원에서 엄마께서 생일∨선물로 호랑이∨모양의 지우개를 사∨주셨습니다.","mis":"K3-2-u2-X04"},{"t":"동물원에서∨엄마께서∨생일∨선물로∨호랑이∨모양의∨지우개를∨사∨주셨습니다.","mis":"K3-2-u2-X05"},{"t":"동물원에서 엄마께서 생일 선물로 호랑이 모양의 지우개를 사 주셨습니다.","mis":"K3-2-u2-X04"}],"explanation":["‘누가’에 해당하는 「엄마께서」 다음에 조금 띄어 읽어요.","「생일 선물로」, 「호랑이 모양의 지우개를」처럼 뜻 덩어리로 묶어요.","덩어리 가운데를 끊거나 낱말마다 끊지 않아요."],"asset":{"type":"passage","lines":["제가 소개하고 싶은 물건은 호랑이 모양의 지우개입니다.","우리 가족은 제 생일에 동물원에 갔습니다.","동물원에서 엄마께서 생일 선물로 호랑이 모양의 지우개를 사 주셨습니다.","항상 제 필통 안에 호랑이 모양 지우개는 같이 있습니다."],"title":"소개하고 싶은 물건을 설명하는 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#7','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',3,'ox','auto','친구가 관심 있는 직업을 발표할 때는 다음 차례인 내 발표를 준비하는 것이 친구 발표를 듣는 것보다 더 중요해요.',ARRAY['K3-2-u2-X26']::text[],false,'{"seq":7,"concept":"K3-2-u2-C15","difficulty":3,"kind":"ox","stem":"친구가 관심 있는 직업을 발표할 때는 다음 차례인 내 발표를 준비하는 것이 친구 발표를 듣는 것보다 더 중요해요.","answer":"X","reason_options":[{"t":"친구 발표를 끝까지 듣고 친구에 대해 새롭게 안 점을 이야기해요.","correct":true},{"t":"내 차례만 잘하면 돼요.","mis":"K3-2-u2-X26"}],"mis":"K3-2-u2-X26","explanation":["발표는 생각과 느낌을 나누는 일이에요.","다른 친구의 발표를 듣고 새롭게 안 점을 말해요.","서로 긍정적인 반응을 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#8','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',4,'mc','auto','「나는 자전거를 탈줄 안다. 내일은 더 멀리 갈수 있을것 같다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u2-X27','K3-2-u2-X28']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":4,"kind":"mc","stem":"「나는 자전거를 탈줄 안다. 내일은 더 멀리 갈수 있을것 같다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"나는 자전거를 탈 줄 안다. 내일은 더 멀리 갈 수 있을 것 같다.","correct":true},{"t":"나는 자전거를 탈 줄 안다. 내일은 더 멀리 갈수 있을 것 같다.","mis":"K3-2-u2-X27"},{"t":"나는 자전거를 탈줄 안다. 내일은 더 멀리 갈 수 있을것 같다.","mis":"K3-2-u2-X27"},{"t":"나는 자전 거를 탈 줄 안다. 내일은 더 멀리 갈 수 있을 것 같다.","mis":"K3-2-u2-X28"}],"explanation":["‘줄’, ‘수’, ‘것’이 다른 말에 기대어 쓰인 곳을 찾아요.","「탈 줄」, 「갈 수」, 「있을 것」으로 앞말과 띄어 써요.","「자전거」는 한 낱말이라 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#9','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C17',4,'essay','teacher','둘레에 있는 사물을 하나 골라 특징을 세 가지 쓰고, 그 특징이 드러나는 새로운 이름을 지어 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C17","difficulty":4,"kind":"essay","stem":"둘레에 있는 사물을 하나 골라 특징을 세 가지 쓰고, 그 특징이 드러나는 새로운 이름을 지어 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 사물 — 리모컨. 특징 — 멀리서 텔레비전을 켜고 끈다, 단추가 많다, 손에 쥘 만큼 작다. 새 이름 — 멀리켜개. 까닭 — 멀리서 켜고 끄는 일을 하는 특징이 이름에 드러나기 때문이다.","scoring_points":["사물의 특징을 세 가지 썼는가","특징이 드러나는 새 이름을 지었는가","이름에 어떤 특징이 드러나는지 까닭을 썼는가"]},"explanation":["먼저 사물의 생김새와 하는 일을 살펴요.","그 특징과 어울리는 낱말로 새 이름을 지어요.","친구가 이름만 듣고 사물을 맞힐 수 있는지 확인해 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_L11_challenge#10','kor',3,2,'u2','L11','tb_g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',4,'essay','teacher','소개하고 싶은 짧은 이야기를 하나 정해 제목과 소개하고 싶은 까닭, 활용할 그림(장면), 글과 그림을 보여 줄 차례를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C15","difficulty":4,"kind":"essay","stem":"소개하고 싶은 짧은 이야기를 하나 정해 제목과 소개하고 싶은 까닭, 활용할 그림(장면), 글과 그림을 보여 줄 차례를 쓰세요.","answer_guide":{"answer":"예: 제목 — 「전우치전」. 까닭 — 도술로 어려운 사람을 돕는 장면이 신나서 친구들도 좋아할 것 같다. 그림 — 전우치가 구름을 타고 나타나는 장면. 차례 — 제목과 인물 그림을 먼저 보여 주고, 중요한 장면 그림을 보이며 줄거리를 유창하게 읽는다.","scoring_points":["이야기 제목과 소개하고 싶은 까닭을 썼는가","흐름에서 중요하거나 감동적인 장면을 그림으로 골랐는가","글과 그림을 보여 줄 차례를 썼는가"]},"explanation":["감명 깊었던 이야기를 골라 까닭을 정해요.","이야기의 흐름에서 중요한 장면을 그림으로 보여 줘요.","글과 그림을 어떤 차례로 보여 줄지 미리 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#1','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C2',1,'mc','auto','띄어 읽기 표시 ∨는 무엇을 나타내나요?',ARRAY['K3-2-u2-X06','K3-2-u2-X02','K3-2-u2-X01']::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"띄어 읽기 표시 ∨는 무엇을 나타내나요?","options":[{"t":"조금 쉬어 읽는 곳","correct":true},{"t":"아주 길게 쉬고 다음 줄로 넘어가는 곳","mis":"K3-2-u2-X06"},{"t":"목소리를 크게 높이는 곳","mis":"K3-2-u2-X02"},{"t":"빠르게 이어 읽는 곳","mis":"K3-2-u2-X01"}],"explanation":["∨는 쉬어 읽는 표시예요.","∨∨는 ∨보다 더 길게 쉬어 읽는 표시예요.","알맞게 띄어 읽으면 뜻이 잘 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#2','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C3',1,'mc','auto','『국어』 67쪽 「생각 열기」예요. 자전거 전용 도로 표지판을 발표하는 친구가 내용을 잘 전달하려고 한 일은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X07']::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 67쪽 「생각 열기」예요. 자전거 전용 도로 표지판을 발표하는 친구가 내용을 잘 전달하려고 한 일은 무엇인가요?","options":[{"t":"그림을 보여 주면서 또박또박 유창하게 읽었다","correct":true},{"t":"그림 없이 가장 빠르게 말했다","mis":"K3-2-u2-X01"},{"t":"친구들이 듣든 말든 가장 큰 소리로 외쳤다","mis":"K3-2-u2-X02"},{"t":"표지판을 꾸미는 방법을 이야기했다","mis":"K3-2-u2-X07"}],"explanation":["친구들은 「그림을 보여 주면서 발표하니까 이해가 잘돼.」라고 했어요.","「발표 내용을 또박또박 말하는구나.」라고도 했어요.","이 단원에서 유창하게 읽기와 글과 그림으로 발표하기를 배워요."],"asset":{"type":"speech","turns":[{"who":"발표자","text":"자전거 전용 도로 표지판은 자전거만 다닐 수 있도록 만든 길에서 볼 수 있습니다."},{"who":"친구 1","text":"그림을 보여 주면서 발표하니까 이해가 잘돼."},{"who":"친구 2","text":"발표 내용을 또박또박 말하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#3','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C4',1,'mc','auto','「나무」에서 커다란 통나무로 만든다고 한 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"mc","stem":"「나무」에서 커다란 통나무로 만든다고 한 것은 무엇인가요?","options":[{"t":"기둥, 대들보, 서까래","correct":true},{"t":"가구, 장난감, 종이","mis":"K3-2-u2-X15"},{"t":"잼, 즙, 차","mis":"K3-2-u2-X15"},{"t":"울타리, 가로수, 숲","mis":"K3-2-u2-X15"}],"explanation":["나무로 집을 짓는 이야기를 다시 읽어요.","커다란 통나무로는 기둥, 대들보, 서까래를 만들어요.","나무를 다듬어 문, 창, 마룻바닥도 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#4','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C5',1,'mc','auto','「신기한 구슬」에서 할아버지께서 편찮으신 장면에서 느껴지는 분위기는 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에서 할아버지께서 편찮으신 장면에서 느껴지는 분위기는 무엇인가요?","options":[{"t":"어둡고 무겁다","correct":true},{"t":"밝고 신난다","mis":"K3-2-u2-X12"},{"t":"신비롭고 환상적이다","mis":"K3-2-u2-X12"},{"t":"시끄럽고 들뜬다","mis":"K3-2-u2-X12"}],"explanation":["할아버지가 갑자기 큰 병이 나셨어요.","엄마 아빠는 허둥지둥 시골로 내려가셨어요.","집안 분위기가 먹구름이 드리운 것처럼 무겁게 가라앉았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#5','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C6',1,'sa','auto','『국어활동』 23쪽이에요. ㉣ 장면에 어울리는 목소리를 보기에서 골라 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u2-C6","difficulty":1,"kind":"sa","stem":"『국어활동』 23쪽이에요. ㉣ 장면에 어울리는 목소리를 보기에서 골라 쓰세요.","answer":["놀라다"],"explanation":["제비가 박씨 하나를 떨어뜨려 주었어요.","뜻밖의 일이라 흥부는 깜짝 놀랐어요.","놀란 목소리와 표정으로 읽어요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#6','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C8',1,'mc','auto','「신기한 구슬」에 나온 「삽시간」의 뜻은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":6,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에 나온 「삽시간」의 뜻은 무엇인가요?","options":[{"t":"매우 짧은 시간","correct":true},{"t":"아주 오랜 시간","mis":"K3-2-u2-X16"},{"t":"점심 먹는 시간","mis":"K3-2-u2-X16"},{"t":"밤늦은 시간","mis":"K3-2-u2-X16"}],"explanation":["『국어』 74쪽 낱말 풀이를 보아요.","「삽시간에 집안 분위기가 … 가라앉았다」 — 순식간에 바뀌었다는 뜻이에요.","뜻을 문장에 넣어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#7','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C10',1,'mc','auto','「이름처럼 쓰는 숫자」에서 사람이나 물건에 번호를 붙이면 좋은 점은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X08']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 사람이나 물건에 번호를 붙이면 좋은 점은 무엇인가요?","options":[{"t":"쉽게 구별할 수 있어서 더 편리하다","correct":true},{"t":"번호가 많을수록 보기 좋다","mis":"K3-2-u2-X18"},{"t":"이름을 아예 쓰지 않아도 된다","mis":"K3-2-u2-X08"},{"t":"물건의 값을 알 수 있다","mis":"K3-2-u2-X08"}],"explanation":["사람이나 물건이 많아지면 누가 누군지 헷갈릴 수 있어요.","번호를 붙이면 쉽게 구별할 수 있어요.","그래서 이름처럼 숫자를 써요."],"asset":{"type":"passage","lines":["사람이나 물건이 많아지면 누가 누군지 헷갈릴 수 있습니다.","이럴 때 번호를 붙이면 쉽게 구별할 수 있어서 더 편리합니다.","(간추림) 자동차 번호판 — 자동차 주인이 누구인지 알려고 차마다 다르다.","(간추림) 버스 번호 — 출발지와 도착지에 따라 번호가 달라진다.","(간추림) 유선 전화번호 — 맨 앞자리는 지역 번호다.","(간추림) 주민 등록 번호 — 태어난 연도·날짜, 남녀가 담겨 있다."],"title":"「이름처럼 쓰는 숫자」 — 『국어』 90~91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#8','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C16',1,'mc','auto','‘것’이 들어간 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"‘것’이 들어간 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"소풍 때 먹을 것을 챙겼어요.","correct":true},{"t":"소풍 때 먹을것을 챙겼어요.","mis":"K3-2-u2-X27"},{"t":"소풍 때 먹 을것을 챙겼어요.","mis":"K3-2-u2-X27"},{"t":"소풍 때 먹을것 을 챙겼어요.","mis":"K3-2-u2-X27"}],"explanation":["‘것’은 다른 말에 기대어 쓰는 말이에요.","앞말과 띄어 「먹을 것」이라고 써요.","「온 것」, 「붉은 것」도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#9','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',2,'mc','auto','『국어활동』 22쪽이에요. 「가을 나들이에 주의합시다」를 읽고 고은이가 한 말에 맞는 읽기 방법은 무엇인가요?',ARRAY['K3-2-u2-X06','K3-2-u2-X05','K3-2-u2-X01']::text[],false,'{"seq":9,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 22쪽이에요. 「가을 나들이에 주의합시다」를 읽고 고은이가 한 말에 맞는 읽기 방법은 무엇인가요?","options":[{"t":"‘누가/무엇이’ 다음에 조금 띄어 읽기","correct":true},{"t":"문장과 문장 사이는 조금 더 길게 띄어 읽기","mis":"K3-2-u2-X06"},{"t":"한 낱말마다 끊어 읽기","mis":"K3-2-u2-X05"},{"t":"쉬지 않고 빠르게 읽기","mis":"K3-2-u2-X01"}],"explanation":["고은이는 「‘누가/무엇이’ 다음에 조금 띄어 읽었어.」라고 했어요.","승우는 그 말이 길면 한 번 더, 혜윤이는 문장 사이를 더 길게 띄어 읽었어요.","세 친구 모두 유창하게 읽었어요."],"asset":{"type":"speech","turns":[{"who":"고은","text":"‘누가/무엇이’ 다음에 조금 띄어 읽었어."},{"who":"승우","text":"‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽었어."},{"who":"혜윤","text":"문장과 문장 사이는 조금 더 길게 띄어 읽었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#10','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',2,'mc','auto','『국어활동』 22쪽 더 알아보기 「글쓴이의 말투를 파악해요」예요. ‘요’로 끝나는 문장은 어떻게 읽나요?',ARRAY['K3-2-u2-X32','K3-2-u2-X02','K3-2-u2-X01']::text[],false,'{"seq":10,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 22쪽 더 알아보기 「글쓴이의 말투를 파악해요」예요. ‘요’로 끝나는 문장은 어떻게 읽나요?","options":[{"t":"실제로 말하듯이 읽는다","correct":true},{"t":"‘-ㅂ니다’와 똑같은 말투로 읽는다","mis":"K3-2-u2-X32"},{"t":"가장 큰 소리로 읽는다","mis":"K3-2-u2-X02"},{"t":"빠르게 넘어간다","mis":"K3-2-u2-X01"}],"explanation":["문장이 어떻게 끝나는지 확인해요.","‘요’로 끝나는 문장은 실제로 말하듯이 읽어요.","‘-ㅂ니다’로 끝나는 문장은 조금 더 공손하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#11','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C5',2,'match','auto','「신기한 구슬」 아침 장면을 정리해요. 칸 이름과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"match","stem":"「신기한 구슬」 아침 장면을 정리해요. 칸 이름과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"인물이 처한 상황","r":"생일을 하루 앞두고 할아버지께서 큰 병이 나셨다."},{"l":"인물의 말이나 행동","r":"엄마: 부스스한 얼굴로 아침상을 차리고 있다."},{"l":"인물의 마음","r":"엄마: 할아버지가 걱정되는 마음"}],"mis":"K3-2-u2-X36","explanation":["일어난 일은 「상황」이에요.","얼굴과 움직임, 따옴표 속 말은 「말이나 행동」이에요.","속으로 느끼는 것은 「마음」이에요."],"asset":{"type":"passage","lines":["다음 날 아침 강토는 일찍 일어나 집안 분위기를 살폈다.","엄마는 부스스한 얼굴로 아침상을 차리고 있었다.","(간추림) 케이크도 미역국도 없는 밥상 — 엄마는 생일을 잊은 듯했다.","(간추림) 강토는 서운한 마음을 꾹 누르고 엄마에게 물었다.","“엄마, 할아버지는 좀 어떠세요?”"],"title":"「신기한 구슬」 아침 장면 — 『국어』 80쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#12','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C7',2,'sa','auto','「박에스더」에서 1902년에 크게 유행한 병은 무엇인가요?','{}'::text[],false,'{"seq":12,"concept":"K3-2-u2-C7","difficulty":2,"kind":"sa","stem":"「박에스더」에서 1902년에 크게 유행한 병은 무엇인가요?","answer":["콜레라"],"explanation":["「1902년에는 … 크게 유행했다.」를 찾아요.","콜레라는 제대로 치료받지 못하면 목숨을 잃을 수도 있는 병이에요.","사람들은 병이 옮을까 봐 환자 근처에도 가지 않으려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#13','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C11',2,'mc','auto','발표 자료에서 「크기」를 활용하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X23']::text[],false,'{"seq":13,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"발표 자료에서 「크기」를 활용하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"중요한 것을 눈에 띄게 하려고","correct":true},{"t":"서로 다른 것을 구별하려고","mis":"K3-2-u2-X20"},{"t":"어느 쪽으로 가는지 알려 주려고","mis":"K3-2-u2-X20"},{"t":"모든 것을 크게 해야 좋아서","mis":"K3-2-u2-X23"}],"explanation":["크기는 중요한 것을 눈에 띄게 해요.","색은 구별하게 하고, 화살표 같은 모양은 쪽을 알려 줘요.","모두 크게 하면 무엇이 중요한지 보이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#14','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C12',2,'mc','auto','태권도 글 ㉯에서 손 기술로 나온 것이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"태권도 글 ㉯에서 손 기술로 나온 것이 아닌 것은 무엇인가요?","options":[{"t":"앞 차기","correct":true},{"t":"얼굴 막기","mis":"K3-2-u2-X15"},{"t":"몸통막기","mis":"K3-2-u2-X15"},{"t":"아래 막기","mis":"K3-2-u2-X15"}],"explanation":["손 기술은 막기 세 가지예요.","얼굴 막기, 몸통막기, 아래 막기예요.","앞 차기는 발 기술이에요."],"asset":{"type":"passage","lines":["태권도의 기본 동작에는 손과 발을 쓰는 기술이 있다.","손 기술: 얼굴을 막는 얼굴 막기, 몸을 막는 몸통막기, 아래쪽을 막는 아래 막기","발 기술: 무릎을 올려 앞으로 차는 앞 차기, 몸을 돌려서 차는 돌려차기,","옆으로 차는 옆 차기"],"title":"글 ㉯ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#15','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C13',2,'mc','auto','발표 자료 얼개를 짤 때 제목은 어디에 놓으면 좋을까요?',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":15,"concept":"K3-2-u2-C13","difficulty":2,"kind":"mc","stem":"발표 자료 얼개를 짤 때 제목은 어디에 놓으면 좋을까요?","options":[{"t":"맨 위 가운데에 크게","correct":true},{"t":"맨 아래 구석에 작게","mis":"K3-2-u2-X22"},{"t":"그림 사이사이에 나누어","mis":"K3-2-u2-X22"},{"t":"설명 글보다 작게 아무 데나","mis":"K3-2-u2-X22"}],"explanation":["제목은 가장 먼저 눈에 들어와야 해요.","그래서 맨 위 가운데에 크게 써요.","『국어』 96·97쪽 예시도 그렇게 짰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#16','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C15',2,'mc','auto','『국어』 101쪽 「관심 있는 직업 발표하기」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"『국어』 101쪽 「관심 있는 직업 발표하기」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"관심 있는 직업 생각하기 → 소개하는 발표 자료 만들기 → 글과 그림을 활용하여 발표하기","correct":true},{"t":"발표하기 → 직업 생각하기 → 발표 자료 만들기","mis":"K3-2-u2-X22"},{"t":"발표 자료 만들기 → 발표하기 → 직업 생각하기","mis":"K3-2-u2-X22"},{"t":"직업 생각하기 → 발표하기 → 발표 자료 만들기","mis":"K3-2-u2-X22"}],"explanation":["먼저 관심 있는 직업을 생각해요.","글과 그림으로 소개하는 발표 자료를 만들어요.","친구들 앞에서 글과 그림을 활용해 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#17','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C4',3,'mc','auto','「장면을 떠올리며 유창하게 글을 읽었는지 확인해 봅시다.」에 있는 물음이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X12','K3-2-u2-X01']::text[],false,'{"seq":17,"concept":"K3-2-u2-C4","difficulty":3,"kind":"mc","stem":"「장면을 떠올리며 유창하게 글을 읽었는지 확인해 봅시다.」에 있는 물음이 아닌 것은 무엇인가요?","options":[{"t":"친구보다 더 큰 소리로 읽었나요?","correct":true},{"t":"알맞은 부분에서 적절히 띄어 읽었나요?","mis":"K3-2-u2-X04"},{"t":"장면의 분위기에 어울리는 목소리와 말투로 읽었나요?","mis":"K3-2-u2-X12"},{"t":"정확한 발음으로 또박또박 읽었나요?","mis":"K3-2-u2-X01"}],"explanation":["확인할 내용은 띄어 읽기, 분위기에 어울리는 목소리와 말투, 정확한 발음이에요.","소리 크기를 친구와 견주는 물음은 없어요.","잘했다고 생각하는 만큼 ●를 색칠해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#18','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C6',3,'error','auto','「신기한 구슬」을 분위기를 살려 읽은 친구들이에요. 알맞지 않게 읽은 친구는 누구인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"error","stem":"「신기한 구슬」을 분위기를 살려 읽은 친구들이에요. 알맞지 않게 읽은 친구는 누구인가요?","options":[{"t":"정우: 할아버지가 편찮으신 아침 장면을 웃으면서 신나게 읽었어.","correct":true,"mis_target":"K3-2-u2-X12"},{"t":"예린: 생일을 기다리는 장면을 들뜬 목소리로 읽었어.","mis":"K3-2-u2-X12"},{"t":"하람: 선물을 받는 장면을 기쁘고 놀란 목소리로 읽었어.","mis":"K3-2-u2-X12"}],"explanation":["장면의 분위기에 맞는 목소리로 읽어야 해요.","아침 장면은 조용하고 우울한 분위기예요.","웃으며 신나게 읽으면 장면과 엇갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#19','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C9',3,'mc','auto','『국어』 89쪽 「세상과 연결하기」에서 목표를 이루려고 노력한 인물을 조사하는 방법으로 나온 것이 아닌 것은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X17']::text[],false,'{"seq":19,"concept":"K3-2-u2-C9","difficulty":3,"kind":"mc","stem":"『국어』 89쪽 「세상과 연결하기」에서 목표를 이루려고 노력한 인물을 조사하는 방법으로 나온 것이 아닌 것은 무엇인가요?","options":[{"t":"이름만 듣고 짐작해서 쓰기","correct":true},{"t":"인터넷에서 찾아보기","mis":"K3-2-u2-X08"},{"t":"책이나 자료에서 찾아보기","mis":"K3-2-u2-X08"},{"t":"주변 사람들에게 질문하기","mis":"K3-2-u2-X17"}],"explanation":["인터넷, 책이나 자료, 주변 사람에게 묻기 — 세 가지 방법이 나와요.","조사한 내용과 출처를 함께 적어요.","짐작한 것은 조사한 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#20','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C10',3,'mc','auto','일기 예보를 글과 그림으로 함께 나타내면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X18']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"일기 예보를 글과 그림으로 함께 나타내면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"토요일과 일요일의 날씨를 한눈에 견주고 자세한 내용도 알 수 있다","correct":true},{"t":"글을 읽지 않아도 모든 내용을 정확히 알 수 있다","mis":"K3-2-u2-X19"},{"t":"그림을 넣어 자료가 예뻐진다","mis":"K3-2-u2-X18"},{"t":"그림 하나로 충분하니 글은 빼도 된다","mis":"K3-2-u2-X19"}],"explanation":["그림은 날씨를 한눈에 보여 줘요.","글은 기온과 날씨 변화를 자세히 알려 줘요.","함께 보면 글의 내용을 더 잘 이해할 수 있어요."],"asset":{"type":"passage","lines":["이번 주말은 맑고 쾌청한 날씨가 예상됩니다.","금요일 오후부터 점차 하늘이 개면서 기온도 서서히 오르겠습니다.","토요일은 아침 최저 기온 6도, 낮 최고 기온이 19도입니다.","일요일은 최저 7도, 최고 18도로 예상되어","단풍을 감상하기에 좋은 날씨가 될 것으로 보입니다.","[그림] 토 해 그림 6·19 / 일 해 그림 7·18 (낮은 기온 파란 숫자, 높은 기온 빨간 숫자)"],"title":"글과 그림을 활용한 일기 예보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#21','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C14',3,'mc','auto','친구가 같은 「태권도의 기본자세」를 나와 다른 배치로 만들었어요. 의견을 나누는 태도로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X24','K3-2-u2-X25']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"친구가 같은 「태권도의 기본자세」를 나와 다른 배치로 만들었어요. 의견을 나누는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"전하려는 것이 잘 보이면 다르게 만들어도 알맞다고 보고 잘한 점을 찾는다","correct":true},{"t":"글이 더 많은 쪽이 더 잘 만든 것이라고 말한다","mis":"K3-2-u2-X24"},{"t":"그림이 더 큰 쪽이 더 잘 만든 것이라고 말한다","mis":"K3-2-u2-X24"},{"t":"나와 다르니 고치라고 말한다","mis":"K3-2-u2-X25"}],"explanation":["같은 내용이라도 표현과 배치가 다를 수 있어요.","글이 많거나 그림이 크다고 더 나은 것은 아니에요.","다른 점을 견주어 보며 잘한 점을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#22','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C17',3,'error','auto','친구들이 사물의 특징이 드러나게 새 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":22,"concept":"K3-2-u2-C17","difficulty":3,"kind":"error","stem":"친구들이 사물의 특징이 드러나게 새 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"하윤: 우산 — 「반짝별」","correct":true,"mis_target":"K3-2-u2-X29"},{"t":"지호: 스탠드 — 「끄덕끄덕등」","mis":"K3-2-u2-X29"},{"t":"민서: 스탠드 — 「책짝꿍」","mis":"K3-2-u2-X29"}],"explanation":["새 이름에는 사물의 생김새나 하는 일이 드러나야 해요.","「반짝별」에는 비를 막는 우산의 특징이 드러나지 않아요.","「끄덕끄덕등」, 「책짝꿍」은 스탠드의 특징이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#23','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C6',4,'essay','teacher','「신기한 구슬」에서 분위기가 잘 느껴지는 장면을 하나 골라 까닭을 쓰고, 그 장면을 유창하게 읽을 방법(띄어 읽기·목소리나 말투·표정이나 몸짓)을 계획해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u2-C6","difficulty":4,"kind":"essay","stem":"「신기한 구슬」에서 분위기가 잘 느껴지는 장면을 하나 골라 까닭을 쓰고, 그 장면을 유창하게 읽을 방법(띄어 읽기·목소리나 말투·표정이나 몸짓)을 계획해 쓰세요.","answer_guide":{"answer":"예: 장면 — 할머니가 할아버지의 선물 상자를 꺼내 오신 장면. 까닭 — 서운했던 강토가 갑작스러운 선물에 감격해 행복한 분위기가 잘 느껴진다. 띄어 읽기 — 문장과 문장 사이는 조금 더 길게 쉰다. 목소리 — 「생일 선물이요?」는 놀라고 반가운 목소리로 끝을 올린다. 표정 — 눈을 크게 뜨고 상자를 받쳐 드는 몸짓을 한다.","scoring_points":["분위기가 잘 느껴지는 장면과 고른 까닭을 썼는가","유창하게 읽는 방법(띄어 읽기)을 썼는가","장면의 분위기에 어울리는 목소리·말투와 표정·몸짓을 썼는가"]},"explanation":["먼저 이야기에서 핵심 장면을 골라요.","장면의 맥락을 보고 분위기를 파악해요.","띄어 읽기와 목소리·표정을 함께 계획하면 유창하고 실감 나게 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#24','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C13',4,'essay','teacher','설명하고 싶은 음식을 하나 정해 조사한 내용을 세 가지 쓰고, 그 가운데 글로 쓸 것과 그림으로 보일 것을 정해 얼개를 짜 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C13","difficulty":4,"kind":"essay","stem":"설명하고 싶은 음식을 하나 정해 조사한 내용을 세 가지 쓰고, 그 가운데 글로 쓸 것과 그림으로 보일 것을 정해 얼개를 짜 쓰세요.","answer_guide":{"answer":"예: 음식 — 떡국. 조사한 내용 — 설날에 먹는다, 가래떡을 얇게 썰어 끓인다, 한 살 더 먹는다는 뜻이 있다. 글 — 설날에 먹는 까닭과 뜻. 그림 — 떡국 한 그릇과 가래떡을 써는 모습. 얼개 — 맨 위 가운데 「떡국」 제목을 크게, 가운데 떡국 그림, 그림 아래 짧은 설명.","scoring_points":["설명하고 싶은 음식과 조사한 내용 세 가지를 썼는가","글로 쓸 것과 그림으로 보일 것을 알맞게 갈랐는가","제목·그림·설명의 자리를 얼개로 짰는가"]},"explanation":["설명할 대상을 정하고 내용을 모아요.","자세한 것은 글로, 한눈에 보일 것은 그림으로 나누어요.","얼개를 짜면 내용을 보기 쉽게 정리할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_a#25','kor',3,2,'u2','','tb_g3_2_kor_u2_review_a','unit_review','K3-2-u2-C7',4,'mc','auto','「박에스더」로 묻고 답하기 놀이를 해요. 친구가 「사람들이 에스더에게 “선생님은 콜레라가 무섭지도 않으세요?”라고 물은 까닭은 무엇인가요?」라고 물었어요. 알맞은 답은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":25,"concept":"K3-2-u2-C7","difficulty":4,"kind":"mc","stem":"「박에스더」로 묻고 답하기 놀이를 해요. 친구가 「사람들이 에스더에게 “선생님은 콜레라가 무섭지도 않으세요?”라고 물은 까닭은 무엇인가요?」라고 물었어요. 알맞은 답은 무엇인가요?","options":[{"t":"험한 곳을 제 발로 찾아가는 에스더가 고마우면서도 걱정스러웠기 때문","correct":true},{"t":"에스더가 콜레라에 걸려 있었기 때문","mis":"K3-2-u2-X08"},{"t":"에스더를 마을에 오지 못하게 하려고","mis":"K3-2-u2-X15"},{"t":"콜레라가 무서운 병이 아니라서","mis":"K3-2-u2-X15"}],"explanation":["물음 바로 앞 문장을 찾아요.","「사람들은 험한 곳을 제 발로 찾아가는 에스더가 고마우면서도 걱정스러웠다.」","답을 한 뒤에는 질문한 친구와 글을 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#1','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C2',1,'blank','auto','「글을 유창하게 읽는 방법」이에요. 「‘누가/무엇이’ (     )에 조금 띄어 읽는다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":1,"kind":"blank","stem":"「글을 유창하게 읽는 방법」이에요. 「‘누가/무엇이’ (     )에 조금 띄어 읽는다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"다음","correct":true},{"t":"앞","mis":"K3-2-u2-X04"},{"t":"가운데","mis":"K3-2-u2-X04"},{"t":"글자마다","mis":"K3-2-u2-X05"}],"explanation":["‘누가/무엇이’에 해당하는 말이 끝나는 곳에서 쉬어요.","「주의 표지판은∨」처럼 그 말 다음에 조금 띄어 읽어요.","덩어리 가운데를 끊지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#2','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C3',1,'sa','auto','『국어』 68쪽 횡단보도의 노란색 화살표는 길을 건널 때 어느 쪽으로 가라는 뜻인가요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":1,"kind":"sa","stem":"『국어』 68쪽 횡단보도의 노란색 화살표는 길을 건널 때 어느 쪽으로 가라는 뜻인가요? 한 낱말로 쓰세요.","answer":["오른쪽","오른쪽으로"],"explanation":["노란색 화살표는 오른쪽을 가리켜요.","모두 오른쪽으로 건너면 서로 부딪치지 않아요.","글자 없이도 화살표 모양으로 한눈에 알 수 있어요."],"asset":{"type":"passage","lines":["[그림] 학교 앞 횡단보도 — 『국어』 68쪽","신호등: 사람 모양 그림과 숫자가 함께 켜져 있다.","바닥: 건너는 길 양쪽에 노란색 화살표가 그려져 있다.","노란색 화살표는 길을 건널 때 오른쪽으로 가라는 뜻이다."],"title":"횡단보도 근처의 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#3','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C4',1,'sa','auto','「나무」에서 은행나무잎으로 만든 약은 무엇을 잘 돌게 한다고 했나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"sa","stem":"「나무」에서 은행나무잎으로 만든 약은 무엇을 잘 돌게 한다고 했나요? 한 낱말로 쓰세요.","answer":["피"],"explanation":["은행나무잎이 나오는 줄을 찾아요.","「피를 잘 돌게 하는 약」이라고 했어요.","버드나무 껍질로는 열을 내리고 통증을 달래 주는 약을 만들어요."],"asset":{"type":"passage","lines":["(간추림) 육계나무·헛개나무·가시오갈피는 껍질을 말려서 쓴다.","(간추림) 차나무·감나무·뽕나무는 잎을 말려서 차로 끓여 마신다.","(간추림) 버드나무 껍질로는 열을 내리고 통증을 달래 주는 약을,","은행나무잎으로는 피를 잘 돌게 하는 약을 만든다."],"title":"「나무」 가운데 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#4','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',1,'mc','auto','「신기한 구슬」에서 강토가 생일을 손꼽아 기다리는 장면의 분위기는 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에서 강토가 생일을 손꼽아 기다리는 장면의 분위기는 무엇인가요?","options":[{"t":"밝고 설렌다","correct":true},{"t":"조용하고 우울하다","mis":"K3-2-u2-X12"},{"t":"답답하고 혼란스럽다","mis":"K3-2-u2-X12"},{"t":"무섭고 떨린다","mis":"K3-2-u2-X12"}],"explanation":["강토의 가슴속에는 생일 선물에 대한 희망이 환하게 밝혀졌어요.","뭔가 큰일이 벌어질 것만 같은 예감도 들었어요.","그래서 밝고 설레는 분위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#5','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C6',1,'sa','auto','『국어활동』 23쪽이에요. 봄이 되어 제비가 다시 날아온 장면에 어울리는 목소리를 보기에서 골라 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u2-C6","difficulty":1,"kind":"sa","stem":"『국어활동』 23쪽이에요. 봄이 되어 제비가 다시 날아온 장면에 어울리는 목소리를 보기에서 골라 쓰세요.","answer":["반갑다"],"explanation":["남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","흥부와 아이들이 손을 흔들었어요.","반가운 목소리와 표정으로 읽어요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#6','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C8',1,'mc','auto','「신기한 구슬」에 나온 「처량했다」의 뜻은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":6,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에 나온 「처량했다」의 뜻은 무엇인가요?","options":[{"t":"초라하고 가여웠다","correct":true},{"t":"기쁘고 자랑스러웠다","mis":"K3-2-u2-X16"},{"t":"시원하고 상쾌했다","mis":"K3-2-u2-X16"},{"t":"바쁘고 정신없었다","mis":"K3-2-u2-X16"}],"explanation":["『국어』 75쪽 낱말 풀이를 보아요.","미역국도 못 얻어먹는 신세가 처량했다고 했어요.","서운하고 초라한 강토의 마음이 담긴 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#7','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C10',1,'mc','auto','「이름처럼 쓰는 숫자」에서 학교에서 줄을 설 때 번호가 있으면 좋은 점은 무엇인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 학교에서 줄을 설 때 번호가 있으면 좋은 점은 무엇인가요?","options":[{"t":"순서를 알기 쉽다","correct":true},{"t":"줄이 더 길어진다","mis":"K3-2-u2-X15"},{"t":"키를 알 수 있다","mis":"K3-2-u2-X08"},{"t":"줄을 서지 않아도 된다","mis":"K3-2-u2-X08"}],"explanation":["『국어』 90쪽 첫 부분의 예예요.","번호가 있으면 순서를 알기 쉬워요.","책에 번호를 붙이면 바꿔 읽을 때 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#8','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C16',1,'mc','auto','‘수’가 들어간 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"‘수’가 들어간 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"내일은 운동장에 갈 수 있어요.","correct":true},{"t":"내일은 운동장에 갈수 있어요.","mis":"K3-2-u2-X27"},{"t":"내일은 운동장에 갈 수있어요.","mis":"K3-2-u2-X27"},{"t":"내일은 운동장에 갈수있어요.","mis":"K3-2-u2-X27"}],"explanation":["‘수’는 다른 말에 기대어 쓰는 말이에요.","앞말·뒷말과 띄어 「갈 수 있어요」라고 써요.","「느낄 수 있습니다」도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#9','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C1',2,'mc','auto','『국어활동』 22쪽에서 「가을 나들이에 주의합시다」를 유창하게 읽은 친구를 모두 고르면 누구인가요?',ARRAY['K3-2-u2-X03']::text[],false,'{"seq":9,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 22쪽에서 「가을 나들이에 주의합시다」를 유창하게 읽은 친구를 모두 고르면 누구인가요?","options":[{"t":"고은, 승우, 혜윤","correct":true},{"t":"고은","mis":"K3-2-u2-X03"},{"t":"승우, 혜윤","mis":"K3-2-u2-X03"},{"t":"아무도 없다","mis":"K3-2-u2-X03"}],"explanation":["세 친구는 서로 다른 띄어 읽기 방법을 말했어요.","모두 『국어』 72쪽 「글을 유창하게 읽는 방법」에 있는 것이에요.","방법이 달라도 모두 알맞게 읽었어요."],"asset":{"type":"speech","turns":[{"who":"고은","text":"‘누가/무엇이’ 다음에 조금 띄어 읽었어."},{"who":"승우","text":"‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽었어."},{"who":"혜윤","text":"문장과 문장 사이는 조금 더 길게 띄어 읽었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#10','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C1',2,'mc','auto','『국어활동』 22쪽 더 알아보기예요. ‘-ㅂ니다’로 끝나는 문장은 어떻게 읽나요?',ARRAY['K3-2-u2-X32','K3-2-u2-X12','K3-2-u2-X13']::text[],false,'{"seq":10,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 22쪽 더 알아보기예요. ‘-ㅂ니다’로 끝나는 문장은 어떻게 읽나요?","options":[{"t":"조금 더 공손하게 읽는다","correct":true},{"t":"‘요’로 끝나는 문장과 똑같이 읽는다","mis":"K3-2-u2-X32"},{"t":"장난스럽게 읽는다","mis":"K3-2-u2-X12"},{"t":"아주 작게 속삭인다","mis":"K3-2-u2-X13"}],"explanation":["문장 끝 말투를 살펴요.","‘-ㅂ니다’로 끝나는 문장은 조금 더 공손하게 읽어요.","‘요’로 끝나는 문장은 실제로 말하듯이 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#11','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',2,'match','auto','「박에스더」 콜레라 장면을 정리해요. 칸 이름과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"match","stem":"「박에스더」 콜레라 장면을 정리해요. 칸 이름과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"인물이 처한 상황","r":"많은 사람이 콜레라에 걸렸다."},{"l":"인물의 말이나 행동","r":"사람들: 고양이 그림을 걸어 놓았다."},{"l":"인물의 마음","r":"사람들: 병에 걸릴까 봐 두려운 마음"}],"mis":"K3-2-u2-X36","explanation":["콜레라가 돈 것은 「상황」이에요.","고양이 그림을 건 것은 「행동」이에요.","두려운 것은 「마음」이에요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#12','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C7',2,'sa','auto','「박에스더」에서 사람들은 콜레라를 어떤 동물이 옮기는 병이라고 믿었나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u2-C7","difficulty":2,"kind":"sa","stem":"「박에스더」에서 사람들은 콜레라를 어떤 동물이 옮기는 병이라고 믿었나요? 한 낱말로 쓰세요.","answer":["쥐"],"explanation":["「콜레라는 쥐가 옮기는 병이래요.」라는 말이 있어요.","그래서 쥐를 잡는 고양이 그림을 걸었어요.","에스더는 위생에 신경 쓰라고 가르쳤어요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#13','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C11',2,'mc','auto','발표 자료에서 「색」을 활용하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X23']::text[],false,'{"seq":13,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"발표 자료에서 「색」을 활용하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 것을 구별해 보여 주려고","correct":true},{"t":"그림을 그리지 않아도 되게 하려고","mis":"K3-2-u2-X19"},{"t":"글자 수를 줄이려고","mis":"K3-2-u2-X19"},{"t":"색이 많을수록 잘 만든 자료라서","mis":"K3-2-u2-X23"}],"explanation":["지도에서 지역마다 다른 색을 칠한 것을 떠올려요.","색이 다르면 서로 다른 것이 한눈에 구별돼요.","색도 전하려는 것이 잘 보이게 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#14','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C12',2,'mc','auto','태권도 글 ㉯에서 「몸을 돌려서 차는」 발 기술은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"태권도 글 ㉯에서 「몸을 돌려서 차는」 발 기술은 무엇인가요?","options":[{"t":"돌려차기","correct":true},{"t":"앞 차기","mis":"K3-2-u2-X15"},{"t":"옆 차기","mis":"K3-2-u2-X15"},{"t":"아래 막기","mis":"K3-2-u2-X15"}],"explanation":["발 기술 세 가지를 다시 읽어요.","무릎을 올려 앞으로 차는 앞 차기, 몸을 돌려서 차는 돌려차기예요.","옆으로 차는 것은 옆 차기예요."],"asset":{"type":"passage","lines":["태권도의 기본 동작에는 손과 발을 쓰는 기술이 있다.","손 기술: 얼굴을 막는 얼굴 막기, 몸을 막는 몸통막기, 아래쪽을 막는 아래 막기","발 기술: 무릎을 올려 앞으로 차는 앞 차기, 몸을 돌려서 차는 돌려차기,","옆으로 차는 옆 차기"],"title":"글 ㉯ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#15','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C13',2,'mc','auto','『국어』 96쪽 예시 얼개에서 그림 아래 설명 글자는 어떻게 쓰라고 했나요?',ARRAY['K3-2-u2-X22','K3-2-u2-X19','K3-2-u2-X23']::text[],false,'{"seq":15,"concept":"K3-2-u2-C13","difficulty":2,"kind":"mc","stem":"『국어』 96쪽 예시 얼개에서 그림 아래 설명 글자는 어떻게 쓰라고 했나요?","options":[{"t":"작게 하고 내용을 간단하게","correct":true},{"t":"제목보다 크게","mis":"K3-2-u2-X22"},{"t":"길고 자세하게 빽빽이","mis":"K3-2-u2-X19"},{"t":"여러 색으로 알록달록하게","mis":"K3-2-u2-X23"}],"explanation":["설명 글자 크기는 작게 해요.","내용은 간단하게 써요.","제목·그림·설명의 크기가 달라야 무엇이 중요한지 보여요."],"asset":{"type":"passage","lines":["제목과 내용 — 태권도의 기본자세","그림 — 태권도의 기본자세를 보여 주는 그림","색, 크기, 모양 — 제목: 파란색, 본문보다 크게 / 본문: 검은색, 제목보다 작게","얼개 — 맨 위 가운데에 제목(글자 크기 키우기·다른 색깔로)","얼개 — 가운데에 앞서기·주춤서기·앞굽이 서기 그림 셋","얼개 — 그림 아래 자세 이름과 설명(설명 글자는 작게, 간단하게)"],"title":"발표 자료를 만드는 방법 — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#16','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C15',2,'mc','auto','물건 소개 글 예시에서 호랑이 모양 지우개를 소개하고 싶은 까닭은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X10']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"물건 소개 글 예시에서 호랑이 모양 지우개를 소개하고 싶은 까닭은 무엇인가요?","options":[{"t":"생일 선물로 받은 물건이기 때문에","correct":true},{"t":"가장 비싼 물건이기 때문에","mis":"K3-2-u2-X08"},{"t":"친구가 소개하라고 해서","mis":"K3-2-u2-X10"},{"t":"지우개가 가장 크기 때문에","mis":"K3-2-u2-X08"}],"explanation":["「소개하고 싶은 까닭은 무엇인가요?」의 예시 답이에요.","생일에 동물원에서 엄마께서 사 주셨어요.","소개하는 까닭을 밝히면 듣는 사람이 더 관심을 가져요."],"asset":{"type":"passage","lines":["제가 소개하고 싶은 물건은 호랑이 모양의 지우개입니다.","우리 가족은 제 생일에 동물원에 갔습니다.","동물원에서 엄마께서 생일 선물로 호랑이 모양의 지우개를 사 주셨습니다.","항상 제 필통 안에 호랑이 모양 지우개는 같이 있습니다."],"title":"소개하고 싶은 물건을 설명하는 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#17','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C4',3,'mc','auto','「녹음하고 다시 듣는 방법」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X09']::text[],false,'{"seq":17,"concept":"K3-2-u2-C4","difficulty":3,"kind":"mc","stem":"「녹음하고 다시 듣는 방법」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"녹음 시작 → 정지 → 재생하며 확인 → 아쉬운 부분 찾기 → 다시 하기","correct":true},{"t":"재생 → 녹음 시작 → 정지 → 끝","mis":"K3-2-u2-X09"},{"t":"녹음 시작 → 정지 → 끝","mis":"K3-2-u2-X09"},{"t":"녹음 시작 → 재생하며 확인 → 정지 → 끝","mis":"K3-2-u2-X09"}],"explanation":["① 녹음 시작 기호(●)를 누르고 읽어요.","② 정지 기호(■) → ③ 재생 기호(▶)로 들으며 확인해요.","④ 아쉬운 부분을 찾아 ⑤ 반복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#18','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C6',3,'error','auto','흥부와 제비 장면을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X30','K3-2-u2-X12']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"error","stem":"흥부와 제비 장면을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"소율: 흥부 이야기는 처음부터 끝까지 반가운 목소리로만 읽어야 해.","correct":true,"mis_target":"K3-2-u2-X30"},{"t":"지후: 제비가 떠날 때는 울먹이는 목소리로 읽었어.","mis":"K3-2-u2-X12"},{"t":"나연: 박씨를 떨어뜨릴 때는 놀란 목소리로 읽었어.","mis":"K3-2-u2-X12"}],"explanation":["장면마다 인물의 상황과 마음이 달라요.","그래서 장면마다 어울리는 목소리도 달라요.","한 가지 목소리로만 읽으면 분위기가 살지 않아요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#19','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C9',3,'mc','auto','「박에스더」를 읽고 생각을 나누어요. 인물이 살았던 때와 업적을 이어서 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X10']::text[],false,'{"seq":19,"concept":"K3-2-u2-C9","difficulty":3,"kind":"mc","stem":"「박에스더」를 읽고 생각을 나누어요. 인물이 살았던 때와 업적을 이어서 말한 친구는 누구인가요?","options":[{"t":"세아: 여자 의사가 드물던 때에 여자 환자들을 돌본 점이 대단해.","correct":true},{"t":"도진: 에스더는 아마 노래도 잘했을 거야.","mis":"K3-2-u2-X08"},{"t":"유나: 다른 친구들이 대단하다니 나도 그래.","mis":"K3-2-u2-X10"},{"t":"채원: 그냥 별로였어.","mis":"K3-2-u2-X10"}],"explanation":["생각을 나눌 때는 시대 배경, 말과 행동, 업적 등에 대해 말해요.","남자 의사에게 진료받기 어려운 여자 환자가 많던 때였어요.","글에 없는 짐작이나 까닭 없는 말은 나누기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#20','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C10',3,'mc','auto','『국어활동』 25쪽 유현민 소개에서 글을 읽어야 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 25쪽 유현민 소개에서 글을 읽어야 알 수 있는 것은 무엇인가요?","options":[{"t":"친구들에게 자신을 알리고 학교생활을 즐겁게 하고 싶어 한다는 것","correct":true},{"t":"생일이 6월 2일이라는 것","mis":"K3-2-u2-X19"},{"t":"비빔밥을 잘 먹는다는 것","mis":"K3-2-u2-X19"},{"t":"좋아하는 색깔이 보라색이라는 것","mis":"K3-2-u2-X19"}],"explanation":["하고 싶은 마음이나 성격은 그림으로 나타내기 어려워요.","그래서 글로 썼어요.","생일, 음식, 색깔은 그림에 있어요."],"asset":{"type":"passage","lines":["저는 3학년 5반 유현민입니다.","조용히 있을 때가 많지만 다양한 친구와 어울리기를 좋아합니다.","친구들에게 저를 알리고 학교생활을 즐겁게 하고 싶습니다.","[그림] 취미 — 책 읽기·그림 그리기 / 잘 먹는 음식 — 비빔밥","[그림] 생일 — 6월 2일 / 혈액형 — B형","[그림] 꿈 — 야구 선수 / 좋아하는 색깔 — 보라색"],"title":"유현민의 글과 그림 — 『국어활동』 25쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#21','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C14',3,'mc','auto','「친구들의 발표 자료를 보고 어떤 생각이나 느낌이 들었나요?」에 알맞게 대답한 것은 무엇인가요?',ARRAY['K3-2-u2-X25','K3-2-u2-X24']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"「친구들의 발표 자료를 보고 어떤 생각이나 느낌이 들었나요?」에 알맞게 대답한 것은 무엇인가요?","options":[{"t":"기본 동작을 그림으로 먼저 보여 주고 글로 설명해 주어서 잘 이해할 수 있었어.","correct":true},{"t":"색이 별로야.","mis":"K3-2-u2-X25"},{"t":"내 것이 더 좋아.","mis":"K3-2-u2-X25"},{"t":"다 똑같아 보여.","mis":"K3-2-u2-X24"}],"explanation":["잘한 점을 구체적으로 말해요.","무엇 때문에 이해가 잘되었는지 까닭을 함께 말해요.","다른 사람의 의견을 존중하며 반응해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#22','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C17',3,'mc','auto','「끄덕끄덕등」이라는 이름에 드러난 스탠드의 특징 두 가지는 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":22,"concept":"K3-2-u2-C17","difficulty":3,"kind":"mc","stem":"「끄덕끄덕등」이라는 이름에 드러난 스탠드의 특징 두 가지는 무엇인가요?","options":[{"t":"목이 움직인다, 빛을 낸다","correct":true},{"t":"주로 책을 읽을 때 쓰인다, 빛을 낸다","mis":"K3-2-u2-X29"},{"t":"목이 움직인다, 물을 담는다","mis":"K3-2-u2-X29"},{"t":"소리를 낸다, 바퀴가 있다","mis":"K3-2-u2-X29"}],"explanation":["「끄덕끄덕」은 목이 움직이는 모습을 흉내 낸 말이에요.","「등」은 빛을 내는 물건이에요.","책을 읽을 때 쓰이는 특징은 「책짝꿍」에 드러나요."],"asset":{"type":"passage","lines":["[그림] 책상 위 스탠드 — 『국어』 104쪽","사물의 특징: 빛을 낸다. · 목이 움직인다. · 주로 책을 읽을 때 쓰인다."],"title":"사물의 특징이 드러나도록 새로운 이름 짓기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#23','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',4,'essay','teacher','「박에스더」에서 사람들이 반갑게 손을 흔들어 에스더를 맞이하는 장면을 읽어요. 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 정리하고, 앞의 콜레라 장면과 분위기가 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u2-C5","difficulty":4,"kind":"essay","stem":"「박에스더」에서 사람들이 반갑게 손을 흔들어 에스더를 맞이하는 장면을 읽어요. 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 정리하고, 앞의 콜레라 장면과 분위기가 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 상황 — 산골 마을에 의사 에스더가 당나귀를 타고 찾아왔다. 말이나 행동 — 사람들: “정말 반가워요, 선생님!” 하며 손을 흔들었다. 마음 — 기다리던 의사가 와서 반갑고 고마운 마음. 분위기 — 콜레라 장면은 답답하고 혼란스러웠지만 이 장면은 밝고 따뜻하다.","scoring_points":["상황·말이나 행동·마음을 갈라 정리했는가","이 장면의 분위기를 썼는가","콜레라 장면과 분위기가 달라진 점을 견주어 썼는가"]},"explanation":["세 칸을 정리하면 분위기가 드러나요.","같은 이야기라도 장면마다 분위기가 바뀌어요.","분위기가 바뀌면 읽는 목소리도 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#24','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C15',4,'essay','teacher','『국어』 99쪽 「더 나아가기」예요. 「올림픽에서 볼 수 있는 운동을 소개하고 싶어.」처럼 글과 그림으로 정리하고 싶은 내용을 하나 정해, 글로 쓸 것과 그림으로 나타낼 것, 색·크기·모양 활용을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C15","difficulty":4,"kind":"essay","stem":"『국어』 99쪽 「더 나아가기」예요. 「올림픽에서 볼 수 있는 운동을 소개하고 싶어.」처럼 글과 그림으로 정리하고 싶은 내용을 하나 정해, 글로 쓸 것과 그림으로 나타낼 것, 색·크기·모양 활용을 쓰세요.","answer_guide":{"answer":"예: 내용 — 양궁 소개. 글 — 화살을 쏘아 과녁의 가운데에 가까울수록 점수가 높다는 규칙. 그림 — 과녁과 활을 쏘는 선수의 모습. 색·크기·모양 — 과녁의 가운데 노란 칸을 크게 그리고 점수 숫자를 굵게 쓴다.","scoring_points":["정리하고 싶은 내용을 정했는가","글로 쓸 것과 그림으로 나타낼 것을 알맞게 갈랐는가","색·크기·모양을 내용에 맞게 활용했는가"]},"explanation":["비빔밥 만드는 방법, 환경 보호 주장, 올림픽 운동 소개처럼 주제는 여러 가지예요.","글과 그림이 할 일을 나누어요.","색·크기·모양은 전하려는 것이 눈에 띄게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_b#25','kor',3,2,'u2','','tb_g3_2_kor_u2_review_b','unit_review','K3-2-u2-C7',4,'essay','teacher','「박에스더」로 묻고 답하기 놀이를 할 질문을 두 개 만들어요. 하나는 글의 주요 내용을, 하나는 장면의 분위기를 묻는 질문으로 만들고 각각 답도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u2-C7","difficulty":4,"kind":"essay","stem":"「박에스더」로 묻고 답하기 놀이를 할 질문을 두 개 만들어요. 하나는 글의 주요 내용을, 하나는 장면의 분위기를 묻는 질문으로 만들고 각각 답도 쓰세요.","answer_guide":{"answer":"예: 내용 — 에스더가 콜레라를 막으려고 가르친 것은 무엇인가요? (깨끗한 물을 마시고 손을 자주 씻는 것) 분위기 — 사람들이 고양이 그림을 걸어 놓은 장면은 어떤 분위기인가요? (답답하고 혼란스럽다)","scoring_points":["글의 주요 내용을 묻는 질문을 만들었는가","장면의 분위기를 묻는 질문을 만들었는가","두 질문의 답을 글에서 찾아 바르게 썼는가"]},"explanation":["질문은 글의 주요 내용과 장면의 분위기를 중심으로 만들어요.","답이 글에 있어야 친구와 함께 확인할 수 있어요.","번갈아 묻고 답하면 내용을 잘 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#1','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C2',1,'ox','auto','‘누가/무엇이’에 해당하는 말이 길면 그 안에서 한 번 더 띄어 읽을 수 있어요.',ARRAY['K3-2-u2-X04']::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":1,"kind":"ox","stem":"‘누가/무엇이’에 해당하는 말이 길면 그 안에서 한 번 더 띄어 읽을 수 있어요.","answer":"O","reason_options":[{"t":"‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽어요.","correct":true},{"t":"‘누가/무엇이’ 다음에는 절대 쉬지 않아요.","mis":"K3-2-u2-X04"}],"mis":"K3-2-u2-X04","explanation":["『국어』 72·73쪽 「글을 유창하게 읽는 방법」에 있어요.","「가시가 있는∨찔레나무나 탱자나무는∨」처럼 읽어요.","뜻 덩어리가 길면 숨을 고르며 한 번 더 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#2','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C3',1,'mc','auto','『국어』 69쪽 글에서 주의 표지판은 어떤 색으로 되어 있다고 했나요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 69쪽 글에서 주의 표지판은 어떤 색으로 되어 있다고 했나요?","options":[{"t":"노란색 배경에 진한 빨간색 선","correct":true},{"t":"파란색 배경에 하얀색 선","mis":"K3-2-u2-X15"},{"t":"검은색 배경에 초록색 선","mis":"K3-2-u2-X15"},{"t":"하얀색 배경에 파란색 선","mis":"K3-2-u2-X15"}],"explanation":["둘째 문장을 다시 읽어요.","「노란색 배경에 진한 빨간색 선이 둘려 있습니다.」","그래서 사람들은 주의할 점을 바로 파악할 수 있어요."],"asset":{"type":"passage","lines":["우리는 길을 걸을 때 주의 표지판을 자주 봅니다.","주의 표지판은 노란색 배경에 진한 빨간색 선이 둘려 있습니다.","그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.","오른쪽 주의 표지판은 “공사 중입니다. 조심히 지나가세요!”라는 뜻을 나타냅니다.","[그림] 세모난 노란 표지판 안에 땅을 파는 사람 모양"],"title":"『국어』 69쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#3','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C4',1,'blank','auto','「나무」에서 「사람이 먹는 나무 열매를 (     )(이)라고 합니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"blank","stem":"「나무」에서 「사람이 먹는 나무 열매를 (     )(이)라고 합니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"과일","correct":true},{"t":"채소","mis":"K3-2-u2-X15"},{"t":"곡식","mis":"K3-2-u2-X15"},{"t":"나물","mis":"K3-2-u2-X15"}],"explanation":["나무는 열매를 맺어요.","그 가운데 사람이 먹는 열매를 과일이라고 해요.","과일은 그냥 먹기도 하고 잼이나 즙으로 먹기도 해요."],"asset":{"type":"passage","lines":["(간추림) 사람이 먹는 나무 열매를 과일이라고 한다.","(간추림) 가시가 있는 찔레나무·탱자나무는 옛날부터 울타리로 썼다.","(간추림) 은행나무·플라타너스는 공해에 강하고 잎에 잔털이 있어","먼지를 잡아 주어 길가에 가로수로 심는다.","나무는 다른 나무와 풀, 온갖 동물과 어우러져 숲을 이룹니다."],"title":"「나무」 뒷부분 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#4','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C5',1,'mc','auto','「신기한 구슬」에서 할머니가 푸짐한 생일상을 차려 주신 장면의 분위기는 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에서 할머니가 푸짐한 생일상을 차려 주신 장면의 분위기는 무엇인가요?","options":[{"t":"따뜻하고 기쁘다","correct":true},{"t":"어둡고 무겁다","mis":"K3-2-u2-X12"},{"t":"답답하고 혼란스럽다","mis":"K3-2-u2-X12"},{"t":"쓸쓸하고 외롭다","mis":"K3-2-u2-X12"}],"explanation":["미역국, 조기구이, 계란말이까지 생일상이 푸짐했어요.","서운했던 강토의 마음이 스르르 풀렸어요.","그래서 따뜻하고 기쁜 분위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#5','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C6',1,'sa','auto','『국어활동』 23쪽이에요. 다 나은 제비가 남쪽으로 떠나는 장면에 어울리는 목소리를 보기에서 골라 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u2-C6","difficulty":1,"kind":"sa","stem":"『국어활동』 23쪽이에요. 다 나은 제비가 남쪽으로 떠나는 장면에 어울리는 목소리를 보기에서 골라 쓰세요.","answer":["울먹이다"],"explanation":["정든 제비가 떠나요.","흥부는 날아가는 제비를 향해 손을 흔들어 주었어요.","아쉬워 울먹이는 목소리로 읽어요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#6','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C8',1,'mc','auto','「신기한 구슬」에 나온 「야속했다」의 뜻은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":6,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에 나온 「야속했다」의 뜻은 무엇인가요?","options":[{"t":"언짢고 섭섭했다","correct":true},{"t":"고맙고 반가웠다","mis":"K3-2-u2-X16"},{"t":"무섭고 떨렸다","mis":"K3-2-u2-X16"},{"t":"졸리고 피곤했다","mis":"K3-2-u2-X16"}],"explanation":["『국어』 77쪽 낱말 풀이를 보아요.","색종이 카드 한 장만 내미는 송이가 야속했어요.","자기는 송이 생일에 펭귄 인형을 선물했기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#7','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C10',1,'mc','auto','「이름처럼 쓰는 숫자」에서 책에 번호를 붙이면 좋은 점은 무엇인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X01']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 책에 번호를 붙이면 좋은 점은 무엇인가요?","options":[{"t":"친구들과 바꿔 읽을 때 헷갈리지 않는다","correct":true},{"t":"책이 더 두꺼워진다","mis":"K3-2-u2-X08"},{"t":"책을 빨리 읽게 된다","mis":"K3-2-u2-X01"},{"t":"책 내용을 몰라도 된다","mis":"K3-2-u2-X08"}],"explanation":["『국어』 90쪽 첫 부분의 예예요.","책에도 번호를 붙이면 바꿔 읽을 때 헷갈리지 않아요.","번호는 구별하려고 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#8','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C16',1,'mc','auto','‘줄’이 두 번 나오는 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K3-2-u2-X27','K3-2-u2-X28']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"‘줄’이 두 번 나오는 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"동생은 줄넘기를 할 줄 알아요.","correct":true},{"t":"동생은 줄넘기를 할줄 알아요.","mis":"K3-2-u2-X27"},{"t":"동생은 줄 넘기를 할 줄 알아요.","mis":"K3-2-u2-X28"},{"t":"동생은 줄 넘기를 할줄 알아요.","mis":"K3-2-u2-X28"}],"explanation":["「할 줄」의 ‘줄’은 다른 말에 기대어 쓰여 띄어 써요.","「줄넘기」는 한 낱말이라 붙여 써요.","모든 ‘줄’을 띄어 쓰는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#9','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C2',2,'mc','auto','「가을 나들이에 주의합시다」의 「풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.」를 알맞게 띄어 읽은 것은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"mc","stem":"「가을 나들이에 주의합시다」의 「풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.」를 알맞게 띄어 읽은 것은 무엇인가요?","options":[{"t":"풀 위에 앉을 때에는∨돗자리를 사용하면∨진드기를 피할 수 있습니다.","correct":true},{"t":"풀∨위에 앉을∨때에는 돗자리를∨사용하면 진드기를 피할∨수 있습니다.","mis":"K3-2-u2-X04"},{"t":"풀∨위에∨앉을∨때에는∨돗자리를∨사용하면∨진드기를∨피할∨수∨있습니다.","mis":"K3-2-u2-X05"},{"t":"풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.","mis":"K3-2-u2-X04"}],"explanation":["뜻 덩어리 「풀 위에 앉을 때에는」 다음에서 쉬어요.","「돗자리를 사용하면」 다음에서도 쉬어요.","덩어리 가운데나 낱말마다 끊지 않아요."],"asset":{"type":"passage","lines":["가을은 나들이하기에 좋은 계절입니다.","그러나 가을은 진드기가 급증하는 시기이기도 합니다.","나들이할 때에는 긴팔, 긴바지를 입어서 피부를 가려 주어야 합니다.","풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.","집에 돌아와서는 몸을 깨끗이 씻고 옷도 세탁합니다."],"title":"「가을 나들이에 주의합시다」 — 『국어활동』 22쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#10','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C1',2,'ox','auto','「진드기를 피해서 안전하게 가을 나들이를 합시다.」와 「진드기를 조심해요.」는 끝이 달라도 똑같은 말투로 읽어야 해요.',ARRAY['K3-2-u2-X32']::text[],false,'{"seq":10,"concept":"K3-2-u2-C1","difficulty":2,"kind":"ox","stem":"「진드기를 피해서 안전하게 가을 나들이를 합시다.」와 「진드기를 조심해요.」는 끝이 달라도 똑같은 말투로 읽어야 해요.","answer":"X","reason_options":[{"t":"문장이 어떻게 끝나는지에 따라 말투를 달리해 읽어요.","correct":true},{"t":"문장 끝이 달라도 말투는 언제나 같아요.","mis":"K3-2-u2-X32"}],"mis":"K3-2-u2-X32","explanation":["『국어활동』 22쪽 더 알아보기에 나와요.","‘요’로 끝나면 말하듯이, ‘-ㅂ니다’나 「합시다」처럼 끝나면 조금 더 공손하게 읽어요.","말투를 살리면 글쓴이의 뜻이 잘 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#11','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C5',2,'mc','auto','「신기한 구슬」 선물 장면에서 「인물의 말이나 행동」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u2-X36','K3-2-u2-X30']::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"「신기한 구슬」 선물 장면에서 「인물의 말이나 행동」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"강토: “그게 뭐예요?”","correct":true},{"t":"할아버지께 예상치 못한 선물을 받았다.","mis":"K3-2-u2-X36"},{"t":"할머니: 선물을 잊어서 놀란 마음","mis":"K3-2-u2-X36"},{"t":"행복하고 즐겁다.","mis":"K3-2-u2-X30"}],"explanation":["따옴표 속 말은 「말이나 행동」이에요.","선물을 받은 일은 「상황」, 놀란 것은 「마음」이에요.","「행복하고 즐겁다」는 그 장면의 「분위기」예요."],"asset":{"type":"passage","lines":["“아이고, 내 정신 좀 봐.”","선물이라는 말에 할머니가 무릎을 탁 치셨다.","(간추림) 할머니는 노란 보자기로 싼 작은 상자를 들고 나오셨다.","“그게 뭐예요?”","(간추림) 할아버지가 며칠 전 강토 생일 선물로 챙겨 두신 것이었다.","“생일 선물이요?”"],"title":"「신기한 구슬」 선물 장면 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#12','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C7',2,'mc','auto','「박에스더」의 끝부분에서 에스더가 가는 곳은 금방 무엇이 되었다고 했나요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":12,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「박에스더」의 끝부분에서 에스더가 가는 곳은 금방 무엇이 되었다고 했나요?","options":[{"t":"병원이 되었고 학교가 되었다","correct":true},{"t":"시장이 되었고 놀이터가 되었다","mis":"K3-2-u2-X15"},{"t":"도서관이 되었고 공원이 되었다","mis":"K3-2-u2-X15"},{"t":"빈집이 되었다","mis":"K3-2-u2-X15"}],"explanation":["에스더는 환자를 치료하고 위생과 건강 상식도 가르쳤어요.","그래서 가는 곳마다 병원이 되고 학교가 되었어요.","사람들 얼굴에 건강한 웃음꽃이 피어났어요."],"asset":{"type":"passage","lines":["① 보구녀관에서 로제타 선생님을 보며 의사의 꿈을 키웠다.","② 밤낮으로 공부해 마침내 의사가 되었다.","③ 당나귀를 타고 왕진 가방을 들고 환자를 찾아 나섰다.","④ 1902년 콜레라 — 모두 피하는 환자를 찾아가 치료했다.","⑤ 고양이 그림 대신 깨끗한 물 마시기·손 씻기를 가르쳤다.","⑥ 에스더가 가는 곳은 금방 병원이 되었고 학교가 되었다."],"title":"「박에스더」 간추린 흐름 — 『국어』 82~85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#13','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C11',2,'mc','auto','발표 자료에서 화살표 같은 「모양」을 활용하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X18']::text[],false,'{"seq":13,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"발표 자료에서 화살표 같은 「모양」을 활용하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"움직이는 방향이나 어느 쪽인지 알려 주려고","correct":true},{"t":"글자를 크게 보이려고","mis":"K3-2-u2-X20"},{"t":"자료를 알록달록하게 꾸미려고","mis":"K3-2-u2-X18"},{"t":"서로 다른 지역의 색을 바꾸려고","mis":"K3-2-u2-X20"}],"explanation":["화살표는 방향을 알려 줘요.","몸이 움직이는 방향, 버스가 가는 쪽을 보여 줄 수 있어요.","꾸밈이 아니라 전하려는 내용 때문에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#14','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C12',2,'mc','auto','태권도 글 ㉰에서 태권도 띠에 주로 쓰이는 다섯 가지 색을 무엇이라고 했나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X31','K3-2-u2-X08']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"태권도 글 ㉰에서 태권도 띠에 주로 쓰이는 다섯 가지 색을 무엇이라고 했나요?","options":[{"t":"우리나라의 전통색인 오방색","correct":true},{"t":"무지개색","mis":"K3-2-u2-X15"},{"t":"차가운 색","mis":"K3-2-u2-X31"},{"t":"세계 여러 나라의 국기 색","mis":"K3-2-u2-X08"}],"explanation":["흰색, 노란색, 빨간색, 파란색, 검은색이에요.","이 다섯 가지 색은 우리나라의 전통색인 오방색이에요.","실력이 늘면 띠의 색도 바뀌어요."],"asset":{"type":"passage","lines":["태권도에서 매는 띠의 색은 다양하다.","특히 흰색, 노란색, 빨간색, 파란색, 검은색이 주로 사용된다.","이 다섯 가지 색은 우리나라의 전통색인 오방색이다.","태권도 실력이 늘면 띠의 색도 바뀐다.","보통 처음 시작할 때에는 흰색 띠를 맨다. 실력이 좋아지면 검은색 띠를 맨다."],"title":"글 ㉰ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#15','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C13',2,'mc','auto','태권도의 손 기술과 발 기술을 함께 발표하려고 해요. 친구가 생각한 배치 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X22','K3-2-u2-X21']::text[],false,'{"seq":15,"concept":"K3-2-u2-C13","difficulty":2,"kind":"mc","stem":"태권도의 손 기술과 발 기술을 함께 발표하려고 해요. 친구가 생각한 배치 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"손 기술은 왼쪽, 발 기술은 오른쪽에 따로 정리한다","correct":true},{"t":"손 기술과 발 기술을 한 줄에 섞어 쓴다","mis":"K3-2-u2-X22"},{"t":"제목 없이 그림만 가득 붙인다","mis":"K3-2-u2-X22"},{"t":"발 기술만 크게 쓰고 손 기술은 빼다","mis":"K3-2-u2-X21"}],"explanation":["내용을 무리 지어 자리를 나누면 한눈에 견줄 수 있어요.","손 기술은 왼쪽, 발 기술은 오른쪽에 정리할 수 있어요.","배치는 얼개를 짜며 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#16','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C15',2,'mc','auto','「공을 가지고 하는 운동 — 축구」에서 글로 표현하기에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"「공을 가지고 하는 운동 — 축구」에서 글로 표현하기에 알맞은 것은 무엇인가요?","options":[{"t":"상대편의 골에 공을 넣는 운동이라는 설명","correct":true},{"t":"두 팀 22명이 운동장 안에 있는 모습","mis":"K3-2-u2-X19"},{"t":"경기 시간 90분을 나타내는 시계","mis":"K3-2-u2-X19"},{"t":"공을 차는 발 모양","mis":"K3-2-u2-X19"}],"explanation":["예시에서는 어떤 운동인지 알려 주는 설명을 글로 쓰기로 했어요.","「상대편의 골에 공을 넣는 운동입니다.」, 「발을 사용하는 운동입니다.」","모습과 시간은 그림으로 보여 줘요."],"asset":{"type":"passage","lines":["축구는 손과 팔을 공에 대지 않고 발을 사용해서","상대편의 골에 공을 넣는 운동입니다.","공을 많이 넣는 팀이 이깁니다.","전반전과 후반전이 있으며, 경기 시간은 90분입니다.","한 팀은 총 11명으로 이루어져 있습니다."],"title":"공을 가지고 하는 운동 — 축구 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#17','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C1',3,'error','auto','『국어』 103쪽 「스스로 확인하기」에서 친구들이 유창하게 읽는 방법이라며 색칠한 것이에요. 잘못 색칠한 친구는 누구인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X04','K3-2-u2-X14']::text[],false,'{"seq":17,"concept":"K3-2-u2-C1","difficulty":3,"kind":"error","stem":"『국어』 103쪽 「스스로 확인하기」에서 친구들이 유창하게 읽는 방법이라며 색칠한 것이에요. 잘못 색칠한 친구는 누구인가요?","options":[{"t":"민재: 슬픈 이야기도 밝은 목소리로 읽는다.","correct":true,"mis_target":"K3-2-u2-X12"},{"t":"수진: 적절한 부분에서 띄어 가며 읽는다.","mis":"K3-2-u2-X04"},{"t":"하율: 글의 분위기에 어울리는 목소리와 말투로 읽는다.","mis":"K3-2-u2-X14"}],"explanation":["알맞은 것은 띄어 가며 읽기와 분위기에 어울리는 목소리·말투예요.","슬픈 이야기는 분위기에 어울리게 읽어요.","「정확한 발음으로 무조건 빠르게」도 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#18','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C6',3,'ox','auto','두 친구가 같은 장면을 서로 다른 목소리로 읽었어요. 둘 다 장면의 분위기에 어울린다면 두 친구 모두 알맞게 읽은 거예요.',ARRAY['K3-2-u2-X14']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"ox","stem":"두 친구가 같은 장면을 서로 다른 목소리로 읽었어요. 둘 다 장면의 분위기에 어울린다면 두 친구 모두 알맞게 읽은 거예요.","answer":"O","reason_options":[{"t":"장면에 어울리면 읽는 방법은 사람마다 달라도 돼요.","correct":true},{"t":"분위기를 살려 읽는 방법은 하나뿐이에요.","mis":"K3-2-u2-X14"}],"mis":"K3-2-u2-X14","explanation":["분위기를 살려 읽는 방법은 여러 가지예요.","상황과 맥락에 어울리면 서로 달라도 돼요.","친구의 읽기에서 배울 점도 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#19','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C9',3,'essay','teacher','우리 반 친구나 이웃 가운데 목표를 이루려고 노력하는 사람을 한 명 떠올려, 그 사람이 한 노력과 내가 배우고 싶은 점을 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"K3-2-u2-C9","difficulty":3,"kind":"essay","stem":"우리 반 친구나 이웃 가운데 목표를 이루려고 노력하는 사람을 한 명 떠올려, 그 사람이 한 노력과 내가 배우고 싶은 점을 쓰세요.","answer_guide":{"answer":"예: 우리 반 유현민 — 조용하지만 친구들과 어울리려고 먼저 인사를 건네고 학급 신문의 어린이 소개에도 나섰다. 나도 쑥스러워도 먼저 다가가는 용기를 배우고 싶다.","scoring_points":["둘레의 사람을 한 명 정했는가","그 사람이 한 노력을 구체적으로 썼는가","내가 배우고 싶은 점을 썼는가"]},"explanation":["위인에게만 배울 점이 있는 것이 아니에요.","친구나 이웃의 노력에서도 배울 점을 찾을 수 있어요.","노력과 배울 점을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#20','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C10',3,'mc','auto','「이름처럼 쓰는 숫자」에서 버스를 실제 버스 모양으로 그리고 기울여 나타낸 것을 보고 알 수 있는 그림의 역할은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X18','K3-2-u2-X08']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"「이름처럼 쓰는 숫자」에서 버스를 실제 버스 모양으로 그리고 기울여 나타낸 것을 보고 알 수 있는 그림의 역할은 무엇인가요?","options":[{"t":"무엇을 설명하는지 한눈에 알아보게 하고 눈에 띄게 한다","correct":true},{"t":"글로 쓴 내용을 똑같이 한 번 더 쓴다","mis":"K3-2-u2-X19"},{"t":"그림은 꾸미는 일만 한다","mis":"K3-2-u2-X18"},{"t":"버스가 실제로 기울어져 달린다는 것을 알려 준다","mis":"K3-2-u2-X08"}],"explanation":["그림은 글로 설명되지 않는 부분을 한눈에 보여 줘요.","버스 모양을 기울여 나타낸 부분이 눈에 띄어요.","글과 그림은 하는 일이 달라요."],"asset":{"type":"passage","lines":["제목: 다니는 곳에 따라 다른 버스 번호 (「버스 번호」만 초록색)","버스는 출발지와 도착지에 따라 번호판이 달라집니다.","서울 시내버스 번호의 첫 번째 번호는 출발지,","두 번째 번호는 도착지를 가리킵니다.","[그림] 지역마다 다른 색을 칠하고 1~7 번호를 적은 지도","[그림] 1211번 초록 버스 — 기울어진 모양으로 그림","[그림 아래 말] 1번 지역에서 출발해서 2번 지역에 도착하는 버스예요."],"title":"『국어』 92쪽 3번 글과 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#21','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C14',3,'error','auto','친구 발표 자료에 붙인 붙임쪽지예요. 알맞지 않게 쓴 것은 누구의 쪽지인가요?',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"error","stem":"친구 발표 자료에 붙인 붙임쪽지예요. 알맞지 않게 쓴 것은 누구의 쪽지인가요?","options":[{"t":"태윤: 틀린 곳이 많아. 다시 해.","correct":true,"mis_target":"K3-2-u2-X25"},{"t":"서진: 띠 색을 실제 색 글씨로 써서 한눈에 구별됐어.","mis":"K3-2-u2-X25"},{"t":"가은: 제목이 가운데에 크게 있어서 무엇을 발표하는지 바로 알았어.","mis":"K3-2-u2-X25"}],"explanation":["붙임쪽지에는 친구 자료의 잘한 점을 써요.","더 잘 보이게 할 방법을 함께 쓰면 도움이 돼요.","잘못한 곳만 쓰면 친구가 무엇을 고쳐야 할지 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#22','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C16',3,'error','auto','‘것·수·줄’을 넣어 문장을 썼어요. 띄어쓰기를 잘못한 친구는 누구인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":22,"concept":"K3-2-u2-C16","difficulty":3,"kind":"error","stem":"‘것·수·줄’을 넣어 문장을 썼어요. 띄어쓰기를 잘못한 친구는 누구인가요?","options":[{"t":"은호: 나는 피아노를 칠줄 안다.","correct":true,"mis_target":"K3-2-u2-X27"},{"t":"라희: 우리는 함께 놀 수 있다.","mis":"K3-2-u2-X27"},{"t":"준서: 가을이 온 것을 느꼈다.","mis":"K3-2-u2-X27"}],"explanation":["「칠 줄」로 띄어 써야 해요.","‘줄’은 다른 말에 기대어 쓰는 말이에요.","「놀 수」, 「온 것」은 바르게 띄어 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#23','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C6',4,'essay','teacher','『국어활동』 23쪽 흥부와 제비 이야기에서 장면 두 개를 골라, 각 장면에 어울리는 목소리를 보기에서 고르고 그렇게 고른 까닭을 인물의 상황이나 마음으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u2-C6","difficulty":4,"kind":"essay","stem":"『국어활동』 23쪽 흥부와 제비 이야기에서 장면 두 개를 골라, 각 장면에 어울리는 목소리를 보기에서 고르고 그렇게 고른 까닭을 인물의 상황이나 마음으로 쓰세요.","answer_guide":{"answer":"예: ㉠ 장면 — 속상하다. 다리가 부러진 제비를 보고 흥부가 마음 아파하기 때문이다. ㉢ 장면 — 반갑다. 남쪽에 갔던 제비가 봄에 다시 날아와 흥부와 아이들이 손을 흔들며 반겼기 때문이다.","scoring_points":["장면 두 개를 골랐는가","장면마다 어울리는 목소리를 보기에서 골랐는가","고른 까닭을 인물의 상황이나 마음으로 썼는가"]},"explanation":["보기: 명랑하다·반갑다·울먹이다·슬프다·놀라다·속상하다.","목소리는 그 장면의 상황과 마음에서 찾아요.","장면이 바뀌면 목소리와 표정도 바뀌어요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#24','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C12',4,'essay','teacher','『국어』 101쪽처럼 관심 있는 직업을 하나 골라 발표 자료를 계획해요. 직업과 고른 까닭, 그 직업이 하는 일 가운데 글로 자세히 쓸 것, 그림으로 나타낼 것을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C12","difficulty":4,"kind":"essay","stem":"『국어』 101쪽처럼 관심 있는 직업을 하나 골라 발표 자료를 계획해요. 직업과 고른 까닭, 그 직업이 하는 일 가운데 글로 자세히 쓸 것, 그림으로 나타낼 것을 쓰세요.","answer_guide":{"answer":"예: 직업 — 수의사. 까닭 — 동물을 좋아하고 아픈 동물을 돕고 싶다. 글 — 동물의 병을 살피고 치료하며 기르는 사람에게 돌보는 방법을 알려 준다는 일. 그림 — 청진기를 대고 강아지를 진찰하는 모습.","scoring_points":["관심 있는 직업과 고른 까닭을 썼는가","하는 일 가운데 글로 자세히 쓸 것을 정했는가","그림으로 나타낼 것을 알맞게 정했는가"]},"explanation":["자신의 적성과 흥미를 생각해 직업을 골라요.","가수의 예처럼 하는 일은 글로, 모습은 그림으로 나타내요.","친구의 발표를 듣고 새롭게 안 점도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_c#25','kor',3,2,'u2','','tb_g3_2_kor_u2_review_c','unit_review','K3-2-u2-C11',4,'mc','auto','『국어』 93쪽 4번 표를 떠올려요. 「이름처럼 쓰는 숫자」에서 색·크기·모양을 글과 그림에 어떻게 썼는지 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X18']::text[],false,'{"seq":25,"concept":"K3-2-u2-C11","difficulty":4,"kind":"mc","stem":"『국어』 93쪽 4번 표를 떠올려요. 「이름처럼 쓰는 숫자」에서 색·크기·모양을 글과 그림에 어떻게 썼는지 바르게 묶은 것은 무엇인가요?","options":[{"t":"색 — 제목에서 강조할 부분의 색을 바꿈 · 크기 — 승용차보다 번호판을 크게 그림 · 모양 — 지역 번호를 지도로 보여 줌","correct":true},{"t":"색 — 승용차보다 번호판을 크게 그림 · 크기 — 제목의 색을 바꿈 · 모양 — 지도로 보여 줌","mis":"K3-2-u2-X20"},{"t":"색 — 지도로 보여 줌 · 크기 — 제목 글자 모양을 바꿈 · 모양 — 번호판을 크게 그림","mis":"K3-2-u2-X20"},{"t":"색·크기·모양은 모두 꾸미려고 쓴 것","mis":"K3-2-u2-X18"}],"explanation":["색: 제목의 강조할 부분, 지도에서 지역마다 다른 색.","크기: 제목 글자를 크게, 승용차 번호판을 크게.","모양: 제목 글자 모양, 지역 번호를 알려 주는 지도."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#1','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C2',1,'mc','auto','『국어』 69쪽 글에 ∨와 ∨∨를 표시했어요. 문장과 문장 사이에 쓴 표시는 무엇인가요?',ARRAY['K3-2-u2-X06','K3-2-u2-X32']::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 69쪽 글에 ∨와 ∨∨를 표시했어요. 문장과 문장 사이에 쓴 표시는 무엇인가요?","options":[{"t":"∨∨","correct":true},{"t":"∨","mis":"K3-2-u2-X06"},{"t":"?","mis":"K3-2-u2-X32"},{"t":"!","mis":"K3-2-u2-X32"}],"explanation":["문장과 문장 사이는 조금 더 길게 쉬어요.","더 길게 쉬어 읽는 표시는 ∨∨예요.","「…자주 봅니다.∨∨」처럼 문장 끝에 써요."],"asset":{"type":"passage","lines":["우리는∨길을 걸을 때∨주의 표지판을 자주 봅니다.∨∨","주의 표지판은∨노란색 배경에∨진한 빨간색 선이 둘려 있습니다.∨∨","그래서 사람들은∨주의할 점을∨바로 파악할 수 있습니다.∨∨"],"title":"띄어 읽기 표시를 한 글 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#2','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C3',1,'mc','auto','『국어』 69쪽 오른쪽 주의 표지판이 나타내는 뜻은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":2,"concept":"K3-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 69쪽 오른쪽 주의 표지판이 나타내는 뜻은 무엇인가요?","options":[{"t":"공사 중이니 조심히 지나가라는 뜻","correct":true},{"t":"자전거만 다닐 수 있다는 뜻","mis":"K3-2-u2-X15"},{"t":"사람이 건너는 신호라는 뜻","mis":"K3-2-u2-X15"},{"t":"오른쪽으로 건너라는 뜻","mis":"K3-2-u2-X15"}],"explanation":["넷째 문장에 뜻이 쓰여 있어요.","「공사 중입니다. 조심히 지나가세요!」라는 뜻이에요.","자전거만 다니는 길은 67쪽 표지판이에요."],"asset":{"type":"passage","lines":["우리는 길을 걸을 때 주의 표지판을 자주 봅니다.","주의 표지판은 노란색 배경에 진한 빨간색 선이 둘려 있습니다.","그래서 사람들은 주의할 점을 바로 파악할 수 있습니다.","오른쪽 주의 표지판은 “공사 중입니다. 조심히 지나가세요!”라는 뜻을 나타냅니다.","[그림] 세모난 노란 표지판 안에 땅을 파는 사람 모양"],"title":"『국어』 69쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#3','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C4',1,'ox','auto','「나무」에서 나무는 혼자 자랄 뿐, 다른 나무나 풀, 동물과는 함께 살지 않는다고 했어요.',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"ox","stem":"「나무」에서 나무는 혼자 자랄 뿐, 다른 나무나 풀, 동물과는 함께 살지 않는다고 했어요.","answer":"X","reason_options":[{"t":"나무는 다른 나무와 풀, 온갖 동물과 어우러져 숲을 이룬다고 했어요.","correct":true},{"t":"글에 쓰여 있지 않아도 내가 짐작한 것이 글의 내용이에요.","mis":"K3-2-u2-X08"}],"mis":"K3-2-u2-X08","explanation":["글의 마지막 부분을 다시 읽어요.","숲에서는 수많은 동물과 식물이 나무의 도움을 받으며 살아요.","글의 내용은 글에 쓰여 있는 것으로 확인해요."],"asset":{"type":"passage","lines":["(간추림) 사람이 먹는 나무 열매를 과일이라고 한다.","(간추림) 가시가 있는 찔레나무·탱자나무는 옛날부터 울타리로 썼다.","(간추림) 은행나무·플라타너스는 공해에 강하고 잎에 잔털이 있어","먼지를 잡아 주어 길가에 가로수로 심는다.","나무는 다른 나무와 풀, 온갖 동물과 어우러져 숲을 이룹니다."],"title":"「나무」 뒷부분 — 『국어』 71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#4','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C5',1,'mc','auto','「신기한 구슬」에서 상자 속 물건이 녹슨 쇠구슬인 것을 본 장면의 분위기는 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에서 상자 속 물건이 녹슨 쇠구슬인 것을 본 장면의 분위기는 무엇인가요?","options":[{"t":"실망스럽고 맥이 빠진다","correct":true},{"t":"행복하고 즐겁다","mis":"K3-2-u2-X12"},{"t":"신나고 들뜬다","mis":"K3-2-u2-X12"},{"t":"편안하고 느긋하다","mis":"K3-2-u2-X12"}],"explanation":["하늘의 선물인 줄 알았는데 녹슨 쇠구슬이었어요.","강토는 「애걔, 이게 뭐야?」 하며 김이 빠졌어요.","그래서 실망스럽고 맥이 빠지는 분위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#5','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',1,'mc','auto','『국어활동』 23쪽 보기의 목소리 가운데 흥부가 다친 제비를 보고 치료해 주는 장면에 어울리는 것을 두 개 고르면 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":5,"concept":"K3-2-u2-C6","difficulty":1,"kind":"mc","stem":"『국어활동』 23쪽 보기의 목소리 가운데 흥부가 다친 제비를 보고 치료해 주는 장면에 어울리는 것을 두 개 고르면 무엇인가요?","options":[{"t":"슬프다, 속상하다","correct":true},{"t":"명랑하다, 반갑다","mis":"K3-2-u2-X12"},{"t":"놀라다, 반갑다","mis":"K3-2-u2-X12"},{"t":"명랑하다, 놀라다","mis":"K3-2-u2-X12"}],"explanation":["다리가 부러진 제비를 본 흥부는 마음이 아파요.","「많이 아프겠구나」라는 말에서 마음이 드러나요.","슬프고 속상한 목소리가 어울려요."],"asset":{"type":"passage","lines":["㉠ 흥부는 다리가 부러진 제비를 정성스럽게 치료해 주었어요.","㉡ 다 나은 제비는 남쪽으로 돌아갔고, 흥부는 손을 흔들어 주었어요.","㉢ 다시 봄, 남쪽에 갔던 제비가 흥부네 마당으로 날아들었어요.","㉣ 제비가 마당을 빙빙 돌다 박씨 하나를 떨어뜨려 주었어요.","보기(목소리): 명랑하다 · 반갑다 · 울먹이다 · 슬프다 · 놀라다 · 속상하다"],"title":"흥부와 제비 장면 — 『국어활동』 23쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#6','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C8',1,'mc','auto','「신기한 구슬」에 나온 「영롱한」의 뜻은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":6,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「신기한 구슬」에 나온 「영롱한」의 뜻은 무엇인가요?","options":[{"t":"구슬이 울리는 소리가 맑고 아름다운","correct":true},{"t":"소리가 탁하고 시끄러운","mis":"K3-2-u2-X16"},{"t":"색이 어둡고 칙칙한","mis":"K3-2-u2-X16"},{"t":"모양이 녹슬고 볼품없는","mis":"K3-2-u2-X16"}],"explanation":["『국어』 79쪽 낱말 풀이를 보아요.","구슬이 「뾰로롱!」 영롱한 소리를 뿜어냈어요.","녹슨 겉모습과 달리 소리는 맑고 아름다웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#7','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C10',1,'mc','auto','「지역마다 다른 전화번호」에서 유선 전화의 지역 번호에 대해 말한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":7,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「지역마다 다른 전화번호」에서 유선 전화의 지역 번호에 대해 말한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"서울 빼고 모두 세 자리 번호다","correct":true},{"t":"모든 지역이 두 자리 번호다","mis":"K3-2-u2-X15"},{"t":"사는 지역과 상관없이 모두 같다","mis":"K3-2-u2-X15"},{"t":"휴대 전화 번호의 맨 앞자리다","mis":"K3-2-u2-X15"}],"explanation":["지역 번호는 지역에 따라 모두 달라요.","말풍선에 「서울 빼고 모두 세 자리 번호예요.」라고 했어요.","휴대 전화 번호는 지역과 상관이 없어요."],"asset":{"type":"passage","lines":["유선 전화번호의 맨 앞자리는 지역 번호입니다.","지역에 따라 모두 번호가 다릅니다.","[그림] 지역마다 다른 색을 칠한 우리나라 지도","[말풍선] 서울 빼고 모두 세 자리 번호예요.","[말풍선] 휴대 전화 번호는 사는 지역과 상관이 없어."],"title":"「지역마다 다른 전화번호」 — 『국어』 91쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#8','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C16',1,'mc','auto','『국어』 104쪽 「단풍 구경」의 문장을 옮겨 썼어요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"『국어』 104쪽 「단풍 구경」의 문장을 옮겨 썼어요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"집에 갈 시간이 된 줄 압니다.","correct":true},{"t":"집에 갈 시간이 된줄 압니다.","mis":"K3-2-u2-X27"},{"t":"집에 갈 시간이된 줄 압니다.","mis":"K3-2-u2-X27"},{"t":"집에 갈 시간이 된줄압니다.","mis":"K3-2-u2-X27"}],"explanation":["‘줄’은 다른 말에 기대어 쓰는 말이에요.","앞말과 띄어 「된 줄」, 뒷말과도 띄어 「줄 압니다」라고 써요.","「가는 줄 모릅니다」도 같아요."],"asset":{"type":"passage","lines":["단풍이 든 산에 오르면 우리는 가을이 온 것을 느낄 수 있습니다.","붉은 것, 노란 것, 그리고 계속해서 푸른 것까지.","알록달록 가을 풍경을 구경하다 보면 시간 가는 줄 모릅니다.","날이 어둑어둑해지고 나서야 집에 갈 시간이 된 줄 압니다.","가을을 오래 느낄 수 있으면 좋겠습니다."],"title":"「단풍 구경」 — 『국어』 104쪽","hi":["온 것","느낄 수","붉은 것","노란 것","푸른 것","가는 줄","된 줄"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#9','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C1',2,'ox','auto','『국어활동』 22쪽 승우처럼 ‘누가/무엇이’에 해당하는 말이 길 때 한 번 더 띄어 읽으면 유창하게 읽은 것이 아니에요.',ARRAY['K3-2-u2-X03']::text[],false,'{"seq":9,"concept":"K3-2-u2-C1","difficulty":2,"kind":"ox","stem":"『국어활동』 22쪽 승우처럼 ‘누가/무엇이’에 해당하는 말이 길 때 한 번 더 띄어 읽으면 유창하게 읽은 것이 아니에요.","answer":"X","reason_options":[{"t":"‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽는 것도 유창하게 읽는 방법이에요.","correct":true},{"t":"한 문장에서는 꼭 한 번만 쉬어야 해요.","mis":"K3-2-u2-X03"}],"mis":"K3-2-u2-X03","explanation":["승우는 「‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽었어.」라고 했어요.","긴 덩어리는 한 번 더 쉬면 뜻이 또렷해져요.","승우도 유창하게 읽었어요."],"asset":{"type":"speech","turns":[{"who":"고은","text":"‘누가/무엇이’ 다음에 조금 띄어 읽었어."},{"who":"승우","text":"‘누가/무엇이’에 해당하는 말이 길면 한 번 더 띄어 읽었어."},{"who":"혜윤","text":"문장과 문장 사이는 조금 더 길게 띄어 읽었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#10','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C1',2,'mc','auto','「가을 나들이에 주의합시다」는 「…입니다」, 「…합니다」로 끝나는 문장이 많아요. 이 글을 읽을 때 알맞은 말투는 무엇인가요?',ARRAY['K3-2-u2-X32','K3-2-u2-X12']::text[],false,'{"seq":10,"concept":"K3-2-u2-C1","difficulty":2,"kind":"mc","stem":"「가을 나들이에 주의합시다」는 「…입니다」, 「…합니다」로 끝나는 문장이 많아요. 이 글을 읽을 때 알맞은 말투는 무엇인가요?","options":[{"t":"조금 더 공손한 말투","correct":true},{"t":"친구와 장난치는 말투","mis":"K3-2-u2-X32"},{"t":"화가 난 말투","mis":"K3-2-u2-X12"},{"t":"울먹이는 말투","mis":"K3-2-u2-X12"}],"explanation":["문장 끝을 보면 글쓴이의 말투를 알 수 있어요.","‘-ㅂ니다’로 끝나는 문장은 조금 더 공손하게 읽어요.","주의할 점을 알려 주는 글이라 또박또박 읽어요."],"asset":{"type":"passage","lines":["가을은 나들이하기에 좋은 계절입니다.","그러나 가을은 진드기가 급증하는 시기이기도 합니다.","나들이할 때에는 긴팔, 긴바지를 입어서 피부를 가려 주어야 합니다.","풀 위에 앉을 때에는 돗자리를 사용하면 진드기를 피할 수 있습니다.","집에 돌아와서는 몸을 깨끗이 씻고 옷도 세탁합니다."],"title":"「가을 나들이에 주의합시다」 — 『국어활동』 22쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#11','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C5',2,'mc','auto','「박에스더」 콜레라 장면에서 박에스더의 「인물의 마음」으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X36','K3-2-u2-X11']::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"「박에스더」 콜레라 장면에서 박에스더의 「인물의 마음」으로 알맞은 것은 무엇인가요?","options":[{"t":"미신으로 건강을 지키려는 사람들이 안타까운 마음","correct":true},{"t":"“고양이 그림은 왜 걸어 놓았나요?”","mis":"K3-2-u2-X36"},{"t":"많은 사람이 콜레라에 걸렸다.","mis":"K3-2-u2-X36"},{"t":"고양이를 무서워하는 마음","mis":"K3-2-u2-X11"}],"explanation":["「에스더는 마음이 아팠다.」에서 마음이 드러나요.","물음은 「말」, 콜레라가 돈 것은 「상황」이에요.","마음은 인물의 말과 행동, 글쓴이가 쓴 마음 표현에서 찾아요."],"asset":{"type":"passage","lines":["“선생님은 콜레라가 무섭지도 않으세요?”","“저도 두려워요. 그렇지만 저렇게 많은 사람이 저를 기다리고 있는걸요.”","(간추림) 많은 집에 고양이 그림이 걸려 있었다.","“고양이 그림은 왜 걸어 놓았나요?”","(간추림) 쥐가 옮기는 병이니 고양이 그림이 막아 준다고 믿었다.","아직도 이런 미신으로 건강을 지키려는 사람이 많다는 사실에","에스더는 마음이 아팠다."],"title":"「박에스더」 콜레라 장면 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#12','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C7',2,'mc','auto','「박에스더」에서 에스더를 기다린 사람들로 글에 나온 사람이 아닌 것은 누구인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":12,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「박에스더」에서 에스더를 기다린 사람들로 글에 나온 사람이 아닌 것은 누구인가요?","options":[{"t":"이웃 나라의 왕","correct":true},{"t":"병원에 가기 어려운 어린아이","mis":"K3-2-u2-X15"},{"t":"장애인","mis":"K3-2-u2-X15"},{"t":"여자 의사를 찾는 여자 환자","mis":"K3-2-u2-X15"}],"explanation":["「병원에 가기 어려운 어린아이, 장애인, 여자 의사를 찾는 여자 환자」가 나와요.","많은 사람이 에스더를 기다렸어요.","글에 없는 사람을 짐작해 고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#13','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C11',2,'mc','auto','『국어활동』 24쪽 더 알아보기예요. 보통 차가운 느낌을 주는 색끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u2-X31']::text[],false,'{"seq":13,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"『국어활동』 24쪽 더 알아보기예요. 보통 차가운 느낌을 주는 색끼리 묶은 것은 무엇인가요?","options":[{"t":"파랑, 청록","correct":true},{"t":"빨강, 노랑","mis":"K3-2-u2-X31"},{"t":"노랑, 청록","mis":"K3-2-u2-X31"},{"t":"빨강, 파랑","mis":"K3-2-u2-X31"}],"explanation":["색깔에 따라 느낌이 달라질 수 있어요.","보통 파랑과 청록은 차가운 느낌을 줘요.","빨강과 노랑은 따뜻한 느낌을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#14','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C12',2,'mc','auto','태권도 글 ㉱에서 태권도를 하면 좋은 점으로 나오지 않은 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"태권도 글 ㉱에서 태권도를 하면 좋은 점으로 나오지 않은 것은 무엇인가요?","options":[{"t":"키가 빨리 큰다","correct":true},{"t":"체력이 좋아진다","mis":"K3-2-u2-X15"},{"t":"집중력이 높아진다","mis":"K3-2-u2-X15"},{"t":"상대를 존중하는 마음을 배운다","mis":"K3-2-u2-X15"}],"explanation":["좋은 점은 첫째, 둘째, 셋째로 나와요.","체력, 집중력, 상대를 존중하는 마음이에요.","글에 없는 내용은 고르지 않아요."],"asset":{"type":"passage","lines":["태권도를 하면 좋은 점이 많다.","첫째, 발차기와 손동작을 할 때 여러 근육을 써서 체력이 좋아진다.","둘째, 품새에 집중해서 연습하므로 집중력이 높아진다.","품새는 기본 동작과 기술을 자연스럽게 연결하는 연습이다.","셋째, 겨루기를 하면서 상대를 존중하는 마음을 배우게 된다.","그래서 태권도를 하면 예절도 함께 익힐 수 있다."],"title":"글 ㉱ — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#15','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C13',2,'mc','auto','『국어』 96쪽에서 발표 자료를 만들 때 얼개를 먼저 짜는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X23','K3-2-u2-X22']::text[],false,'{"seq":15,"concept":"K3-2-u2-C13","difficulty":2,"kind":"mc","stem":"『국어』 96쪽에서 발표 자료를 만들 때 얼개를 먼저 짜는 까닭은 무엇인가요?","options":[{"t":"제목·그림·설명을 어디에 놓을지 미리 정하려고","correct":true},{"t":"얼개를 짜면 그림을 그리지 않아도 되어서","mis":"K3-2-u2-X19"},{"t":"얼개가 복잡할수록 좋은 자료라서","mis":"K3-2-u2-X23"},{"t":"바로 만들면 시간이 남아서","mis":"K3-2-u2-X22"}],"explanation":["얼개는 자료의 뼈대예요.","무엇을 어디에, 어떤 크기로 놓을지 먼저 정해요.","얼개 짜기는 발표 자료를 만들 때 아주 중요한 과정이에요."],"asset":{"type":"passage","lines":["제목과 내용 — 태권도의 기본자세","그림 — 태권도의 기본자세를 보여 주는 그림","색, 크기, 모양 — 제목: 파란색, 본문보다 크게 / 본문: 검은색, 제목보다 작게","얼개 — 맨 위 가운데에 제목(글자 크기 키우기·다른 색깔로)","얼개 — 가운데에 앞서기·주춤서기·앞굽이 서기 그림 셋","얼개 — 그림 아래 자세 이름과 설명(설명 글자는 작게, 간단하게)"],"title":"발표 자료를 만드는 방법 — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#16','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C15',2,'mc','auto','짧은 이야기를 소개한 친구의 발표를 들은 뒤 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X26','K3-2-u2-X25']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"짧은 이야기를 소개한 친구의 발표를 들은 뒤 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"이야기에 대해 새롭게 안 점을 이야기한다","correct":true},{"t":"내 발표 차례만 기다린다","mis":"K3-2-u2-X26"},{"t":"내용과 상관없이 박수만 친다","mis":"K3-2-u2-X26"},{"t":"잘못한 곳만 찾아 말한다","mis":"K3-2-u2-X25"}],"explanation":["다른 친구들의 발표를 끝까지 들어요.","짧은 이야기에 대해 새롭게 안 점을 말해요.","서로 긍정적인 반응을 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#17','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C4',3,'ox','auto','스스로 점검표에 ●를 색칠하는 까닭은 친구와 점수를 견주어 누가 더 잘 읽는지 가리려는 거예요.',ARRAY['K3-2-u2-X09']::text[],false,'{"seq":17,"concept":"K3-2-u2-C4","difficulty":3,"kind":"ox","stem":"스스로 점검표에 ●를 색칠하는 까닭은 친구와 점수를 견주어 누가 더 잘 읽는지 가리려는 거예요.","answer":"X","reason_options":[{"t":"점검은 내가 어떻게 읽는지 알고 다음에 더 잘 읽으려고 하는 거예요.","correct":true},{"t":"점검은 잘못을 찾아 점수를 매기는 일이에요.","mis":"K3-2-u2-X09"}],"mis":"K3-2-u2-X09","explanation":["스스로 확인하면 부족한 부분을 알 수 있어요.","아쉬운 부분은 다시 연습해 고쳐요.","친구와는 잘한 점과 아쉬운 점을 서로 보충해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#18','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',3,'mc','auto','「“괜찮아. 생일은 뭐 내년에도 있잖아.” 강토는 애써 어른스럽게 말을 했다.」를 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X13','K3-2-u2-X32']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"mc","stem":"「“괜찮아. 생일은 뭐 내년에도 있잖아.” 강토는 애써 어른스럽게 말을 했다.」를 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"서운함을 감추고 애써 괜찮은 척하는 목소리로 읽는다","correct":true},{"t":"정말 아무렇지 않은 듯 신나게 읽는다","mis":"K3-2-u2-X12"},{"t":"엉엉 우는 목소리로 크게 읽는다","mis":"K3-2-u2-X13"},{"t":"따옴표 속 말도 해설과 똑같은 말투로 읽는다","mis":"K3-2-u2-X32"}],"explanation":["「애써 어른스럽게」에서 강토의 마음을 짐작해요.","속으로는 서운하지만 겉으로는 괜찮은 척해요.","마음이 드러나는 목소리로, 낱말은 또렷하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#19','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C9',3,'ox','auto','「박에스더」를 읽고 「나도 박에스더처럼 내 목표를 이루려고 노력해야겠다.」라고 생각한 것은 글과 상관없는 생각이에요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":19,"concept":"K3-2-u2-C9","difficulty":3,"kind":"ox","stem":"「박에스더」를 읽고 「나도 박에스더처럼 내 목표를 이루려고 노력해야겠다.」라고 생각한 것은 글과 상관없는 생각이에요.","answer":"X","reason_options":[{"t":"에스더가 꿈을 이루려고 노력한 모습을 보고 든 생각이라 글과 이어진 생각이에요.","correct":true},{"t":"글에 그대로 쓰인 말만 생각이나 느낌이 될 수 있어요.","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["『국어』 88쪽 예시 답이에요.","인물의 노력을 보며 내 삶을 돌아본 생각이에요.","생각이나 느낌은 사람마다 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#20','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C10',3,'mc','auto','『국어활동』 25쪽 3번 예시처럼 자신을 소개할 때 글로 설명하면 좋은 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 25쪽 3번 예시처럼 자신을 소개할 때 글로 설명하면 좋은 것은 무엇인가요?","options":[{"t":"소개하고 싶은 까닭이나 태어난 곳처럼 그림으로 나타내기 어려운 것","correct":true},{"t":"키우는 동물의 모습","mis":"K3-2-u2-X19"},{"t":"좋아하는 과목을 나타내는 물건","mis":"K3-2-u2-X19"},{"t":"특기를 하는 모습","mis":"K3-2-u2-X19"}],"explanation":["그림으로 나타내기 어려운 부분은 글로 설명해요.","키우는 동물, 좋아하는 과목, 특기는 알맞은 그림으로 나타내요.","이름과 생일, 나이는 크고 진한 글씨로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#21','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C14',3,'mc','auto','발표 자료를 더 보완한다면 어떤 점을 보완하고 싶은지 생각해 보아요. 알맞은 생각은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X19','K3-2-u2-X25']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"발표 자료를 더 보완한다면 어떤 점을 보완하고 싶은지 생각해 보아요. 알맞은 생각은 무엇인가요?","options":[{"t":"중요한 낱말에 색을 넣어 주목할 수 있게 하고 싶다","correct":true},{"t":"모든 글자를 가장 크게 바꾸고 싶다","mis":"K3-2-u2-X23"},{"t":"그림을 모두 빼고 글만 남기고 싶다","mis":"K3-2-u2-X19"},{"t":"친구 의견은 듣지 않고 그대로 두고 싶다","mis":"K3-2-u2-X25"}],"explanation":["제목을 더 크게, 그림 옆에 설명 더하기, 중요한 낱말에 색 넣기처럼 보완할 수 있어요.","전하려는 것이 더 잘 보이게 보완해요.","친구들의 의견을 참고하면 더 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#22','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C16',3,'mc','auto','‘줄’이 다른 말에 기대어 쓰여 앞말과 띄어 써야 하는 문장은 무엇인가요?',ARRAY['K3-2-u2-X28']::text[],false,'{"seq":22,"concept":"K3-2-u2-C16","difficulty":3,"kind":"mc","stem":"‘줄’이 다른 말에 기대어 쓰여 앞말과 띄어 써야 하는 문장은 무엇인가요?","options":[{"t":"시간 가는 줄 모르고 놀았다.","correct":true},{"t":"줄넘기를 열 번 했다.","mis":"K3-2-u2-X28"},{"t":"빨랫줄에 옷을 널었다.","mis":"K3-2-u2-X28"},{"t":"줄을 서서 기다렸다.","mis":"K3-2-u2-X28"}],"explanation":["「가는 줄」의 ‘줄’은 앞말에 기대어 「방법·셈속」을 나타내요.","줄넘기, 빨랫줄은 한 낱말이고, 「줄을 서다」의 줄은 혼자 쓰인 낱말이에요.","모든 ‘줄’을 띄어 쓰는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#23','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C1',4,'essay','teacher','자신이 고른 이야기 한 편의 제목을 쓰고, 그 이야기를 유창하게 읽는 방법 두 가지와 인물의 마음을 짐작할 수 있는 부분 한 곳을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u2-C1","difficulty":4,"kind":"essay","stem":"자신이 고른 이야기 한 편의 제목을 쓰고, 그 이야기를 유창하게 읽는 방법 두 가지와 인물의 마음을 짐작할 수 있는 부분 한 곳을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「흥부와 놀부」. 방법 — ‘누가/무엇이’ 다음에 조금 띄어 읽는다. 장면의 분위기에 어울리는 목소리와 말투로 읽는다. 마음을 짐작할 부분 — “아이고, 많이 아프겠구나. 내가 꼭 고쳐 줄게.”에서 제비를 가엾게 여기는 흥부의 마음을 알 수 있다.","scoring_points":["이야기 제목을 썼는가","유창하게 읽는 방법을 두 가지 썼는가","인물의 마음을 짐작할 수 있는 부분을 찾아 썼는가"]},"explanation":["이야기는 교사가 정해 주어도 돼요.","띄어 읽기, 발음, 분위기에 어울리는 목소리와 말투를 떠올려요.","인물의 마음은 말이나 행동에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#24','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C10',4,'essay','teacher','『국어』 92~93쪽에서 배운 것을 떠올려요. 「이름처럼 쓰는 숫자」의 「주민 등록 번호」 부분을 글과 그림으로 설명한다면, 글로 쓸 내용과 그림으로 나타낼 내용을 하나씩 정하고 글과 그림을 함께 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C10","difficulty":4,"kind":"essay","stem":"『국어』 92~93쪽에서 배운 것을 떠올려요. 「이름처럼 쓰는 숫자」의 「주민 등록 번호」 부분을 글과 그림으로 설명한다면, 글로 쓸 내용과 그림으로 나타낼 내용을 하나씩 정하고 글과 그림을 함께 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 글 — 주민 등록 번호에는 태어난 연도와 날짜, 남자인지 여자인지 같은 나만의 정보가 담겨 있다는 것. 그림 — 번호의 자리마다 화살표로 「태어난 연도·월·일」을 가리키는 표. 좋은 점 — 글로 뜻을 간략히 알려 주고 그림으로 어느 자리가 무엇인지 한눈에 보여 줄 수 있다.","scoring_points":["글로 쓸 내용을 정했는가","그림으로 나타낼 내용을 정했는가","글과 그림을 함께 쓰면 좋은 점을 썼는가"]},"explanation":["글은 중요한 내용을 간략하게 제시해요.","그림은 중요한 내용을 한눈에 파악하게 나타내요.","글과 그림을 연결해 보면 더 잘 이해돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u2_review_d#25','kor',3,2,'u2','','tb_g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',4,'mc','auto','「신기한 구슬」의 끝 장면에서 녹슨 쇠구슬이 갑자기 「뾰로롱!」 소리를 내며 은빛으로 빛났어요. 앞 장면과 견주어 분위기가 어떻게 바뀌었고, 어떻게 읽으면 좋을까요?',ARRAY['K3-2-u2-X30','K3-2-u2-X14','K3-2-u2-X12']::text[],false,'{"seq":25,"concept":"K3-2-u2-C6","difficulty":4,"kind":"mc","stem":"「신기한 구슬」의 끝 장면에서 녹슨 쇠구슬이 갑자기 「뾰로롱!」 소리를 내며 은빛으로 빛났어요. 앞 장면과 견주어 분위기가 어떻게 바뀌었고, 어떻게 읽으면 좋을까요?","options":[{"t":"실망스러운 분위기에서 신비롭고 놀라운 분위기로 바뀌니, 놀란 목소리로 생생하게 읽는다","correct":true},{"t":"처음부터 끝까지 실망스러운 분위기라 계속 힘없이 읽는다","mis":"K3-2-u2-X30"},{"t":"분위기는 바뀌었지만 읽는 목소리는 바꾸지 않는다","mis":"K3-2-u2-X14"},{"t":"무서운 분위기로 바뀌니 떨리는 목소리로 작게 읽는다","mis":"K3-2-u2-X12"}],"explanation":["녹슨 구슬에 실망했던 장면 다음이에요.","구슬이 영롱한 소리를 내며 빛나 신기하고 놀라운 분위기로 바뀌어요.","분위기가 바뀌면 목소리와 표정도 바꾸어 읽어요."],"asset":{"type":"passage","lines":["① 강토는 열 살 생일을 손꼽아 기다렸다.","② 생일 하루 앞, 할아버지가 큰 병이 나셨다.","③ 생일 아침, 엄마는 생일을 잊은 듯했다.","④ 할머니가 오셔서 푸짐한 생일상을 차려 주셨다.","⑤ 할아버지 선물을 열어 보니 녹슨 쇠구슬이었다.","⑥ 툭 떨어뜨리자 구슬이 “뾰로롱!” 소리를 내며 빛났다."],"title":"「신기한 구슬」 간추린 흐름 — 『국어』 74~79쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
